DROP TABLE IF EXISTS `approval_steps`;
CREATE TABLE `approval_steps` (
  `id` int NOT NULL AUTO_INCREMENT,
  `workflowId` int NOT NULL,
  `stepNumber` int NOT NULL,
  `stepName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `assignedToId` int DEFAULT NULL,
  `approvedById` int DEFAULT NULL,
  `approvedAt` timestamp NULL DEFAULT NULL,
  `comments` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `approval_steps_workflowId_approval_workflows_id_fk` (`workflowId`),
  KEY `approval_steps_assignedToId_users_id_fk` (`assignedToId`),
  KEY `approval_steps_approvedById_users_id_fk` (`approvedById`),
  CONSTRAINT `approval_steps_workflowId_approval_workflows_id_fk` FOREIGN KEY (`workflowId`) REFERENCES `approval_workflows` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `approval_steps_assignedToId_users_id_fk` FOREIGN KEY (`assignedToId`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `approval_steps_approvedById_users_id_fk` FOREIGN KEY (`approvedById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

