  `organizationalGroupId` int DEFAULT NULL,
  `companyId` int DEFAULT NULL,
  `businessUnitId` int DEFAULT NULL,
  `beforeData` json DEFAULT NULL,
  `afterData` json DEFAULT NULL,
  `userAgent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  KEY `audit_logs_userId_users_id_fk` (`userId`),
  CONSTRAINT `audit_logs_userId_users_id_fk` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

