-- ------------------------------------------------------------
-- Tabela: business_units
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `business_units`;
CREATE TABLE `business_units` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `logoUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organizationalGroupId` int DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  KEY `business_units_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `business_units_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `business_units` (`id`, `name`, `code`, `description`, `status`, `createdById`, `createdAt`, `updatedAt`, `logoUrl`, `organizationalGroupId`) VALUES
