  (2, 'Grupo Arqueo Africa', 'África', 'Operações do Grupo Arqueo no continente africano, incluindo projetos e empresas em países da África.', 'active', NULL, '2026-04-15 21:13:20', '2026-05-21 18:03:27', NULL, 2),
  (3, 'Foods and Drinks', 'F&D', 'Divisão de alimentos e bebidas do Grupo Arqueo, englobando empresas do setor alimentício e de bebidas.', 'active', NULL, '2026-04-15 21:13:20', '2026-05-21 18:03:27', NULL, 3);

-- ------------------------------------------------------------
-- Tabela: companies
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `companies`;
CREATE TABLE `companies` (
  `id` int NOT NULL AUTO_INCREMENT,
  `businessUnitId` int NOT NULL,
  `legalName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tradeName` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cnpj` varchar(18) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logoUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `organizationalGroupId` int DEFAULT NULL,
  `companyType` enum('holding','subsidiary','branch','independent') COLLATE utf8mb4_unicode_ci DEFAULT 'subsidiary',
  `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Brasil',
  PRIMARY KEY (`id`) ,
  KEY `companies_businessUnitId_business_units_id_fk` (`businessUnitId`),
  KEY `companies_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `companies_businessUnitId_business_units_id_fk` FOREIGN KEY (`businessUnitId`) REFERENCES `business_units` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `companies_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

