-- ------------------------------------------------------------
-- Tabela: compliance_alerts
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `compliance_alerts`;
CREATE TABLE `compliance_alerts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `supplierId` int DEFAULT NULL,
  `documentId` int DEFAULT NULL,
  `alertType` enum('expiration','missing_document','compliance_issue','review_needed') COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dueDate` timestamp NULL DEFAULT NULL,
  `isResolved` tinyint(1) NOT NULL DEFAULT '0',
  `resolvedAt` timestamp NULL DEFAULT NULL,
  `resolvedById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `compliance_alerts_supplierId_suppliers_id_fk` (`supplierId`),
  KEY `compliance_alerts_documentId_documents_id_fk` (`documentId`),
  KEY `compliance_alerts_resolvedById_users_id_fk` (`resolvedById`),
  CONSTRAINT `compliance_alerts_supplierId_suppliers_id_fk` FOREIGN KEY (`supplierId`) REFERENCES `suppliers` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `compliance_alerts_documentId_documents_id_fk` FOREIGN KEY (`documentId`) REFERENCES `documents` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `compliance_alerts_resolvedById_users_id_fk` FOREIGN KEY (`resolvedById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

