-- ------------------------------------------------------------
-- Tabela: contract_amendments
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_amendments`;
CREATE TABLE `contract_amendments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amendmentType` enum('financial','scope','term','mixed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'financial',
  `status` enum('draft','review','active','terminated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valueChange` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `newTotalValue` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `newEndDate` timestamp NULL DEFAULT NULL,
  `content` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signedAt` timestamp NULL DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `contract_amendments_contractId_contracts_id_fk` (`contractId`),
  KEY `contract_amendments_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `contract_amendments_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `contract_amendments_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contract_amendments` (`id`, `contractId`, `number`, `title`, `amendmentType`, `status`, `description`, `valueChange`, `newTotalValue`, `newEndDate`, `content`, `notes`, `signedAt`, `createdById`, `createdAt`, `updatedAt`) VALUES
  (2, 2, 'ADT-002', 'Segundo Aditivo ao Contrato N° 055-06-2026', 'term', 'review', 'Prorrogação do prazo de vigência do contrato por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'Fica prorrogado o prazo de vigência do contrato, que agora vai de 06/03/2026 a 06/05/2026. Todas as demais cláusulas permanecem inalteradas.', 'Resumo IA: O aditivo prorroga o prazo de vigência do contrato por mais 60 dias. As condições contratuais permanecem inalteradas, garantindo a continuidade dos serviços.', '2026-04-06 04:00:00', 1, '2026-04-16 22:40:37', '2026-04-16 22:40:37'),
  (30001, 60001, 'ADT-002', 'Segundo Aditivo ao Contrato Nº 057-06-2025 de Prestação de Serviços', 'term', 'review', 'Prorrogação do prazo de execução dos serviços por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'O aditivo ajusta a prorrogação do contrato, mantendo vigência de 06/03/2026 até 06/05/2026, conforme o interesse recíproco das partes. O início dos serviços é retroativo a 06 de março de 2026.', 'Resumo IA: O segundo aditivo ao contrato estabelece a continuidade da prestação de serviços pelo prazo adicional de 60 dias, alterando a data de término para 06 de maio de 2026. As demais cláusulas do contrato permanecem inalteradas.', '2026-04-06 04:00:00', 1, '2026-04-17 21:26:36', '2026-04-17 21:26:36'),
  (60001, 90001, ' Nº 102-10-2025', 'Aditivo de Contrato Nº 102-10-2025 de Prestação de Serviços', 'term', 'review', 'Alteração do prazo de vigência do contrato de prestação de serviços de Analista de Geoprocessamento.', NULL, NULL, '2026-05-07 04:00:00', 'As partes ajustam o prazo de vigência do contrato originalmente de 21/11/2025 a 06/03/2026 para 07/03/2026 a 07/05/2026, mantendo todas as demais cláusulas e condições.', 'Resumo IA: O aditivo altera o prazo do contrato de prestação de serviços de Analista de Geoprocessamento, prorrogando a vigência até 07 de maio de 2026. Todas as demais cláusulas do contrato permanecem inalteradas.', '2026-04-07 04:00:00', 1, '2026-04-20 18:20:37', '2026-04-20 18:20:37'),
  (90001, 120001, 'ADT-002', 'Segundo Aditivo ao Contrato N° 058-06-2025 de Prestação de Serviços', 'term', 'review', 'Prorrogação do prazo contratual por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'O prazo de vigência do contrato foi prorrogado para o período de 06/03/2026 a 06/05/2026, mantendo-se as demais cláusulas contratuais inalteradas e válidas.', 'Resumo IA: O segundo aditivo faz a prorrogação do contrato, estendendo o período de vigência por mais 60 dias. As condições previamente acordadas permanecem inalteradas.', '2026-04-06 04:00:00', 1, '2026-04-20 20:36:59', '2026-04-20 20:36:59'),
  (90002, 120002, NULL, '2° Aditivo de Contrato Nº 094-09-2025', 'term', 'review', 'Prorrogação do contrato por mais 60 dias para a prestação de serviços pela CONTRATADA.', NULL, NULL, '2026-05-06 04:00:00', 'Aditivo que prorroga o prazo de vigência do contrato de prestação de serviços por mais 60 dias, passando a vigorar de 06/03/2026 até 06/05/2026, mantendo todas as demais cláusulas inalteradas.', 'Resumo IA: O presente aditivo prorroga o contrato de prestação de serviços por mais 60 dias. As partes concordam com as novas datas de vigência e reafirmam o compromisso com as cláusulas não alteradas do contrato.', '2026-04-07 04:00:00', 1, '2026-04-20 21:06:26', '2026-04-20 21:06:26'),
  (90003, 120003, 'ADT-002', 'Segundo Aditivo ao Contrato nº 060-06-2025', 'term', 'review', 'Prorrogação do prazo de vigência do contrato por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'O presente aditivo estabelece a prorrogação do prazo de execução dos serviços da Contratada, passando a vigência a ser de 06/03/2026 até 06/05/2026, sem alteração dos demais termos do contrato original.', 'Resumo IA: O aditivo prorroga a vigência do contrato original por 60 dias, mantendo as demais cláusulas inalteradas. A nova data de término é 6 de maio de 2026.', '2026-04-06 04:00:00', 1, '2026-04-20 21:32:07', '2026-04-20 21:32:07'),
  (120001, 150001, 'ADT-002', 'Segundo Aditivo ao Contrato Nº 052-05-2025', 'term', 'review', 'Prorrogação do prazo de vigência do contrato de prestação de serviços por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'As partes ajustam a prorrogação do contrato por mais 60 dias, com nova data de vigência de 06/03/2026 a 06/05/2026. Todas as outras cláusulas permanecem inalteradas.', 'Resumo IA: O segundo aditivo prorroga o prazo do contrato de prestação de serviços por mais 60 dias, alterando a vigência até o dia 06 de maio de 2026. As demais condições do contrato permanecem inalteradas.', '2026-04-09 04:00:00', 1, '2026-04-20 22:14:22', '2026-04-20 22:14:22'),
  (120002, 150002, NULL, 'Segundo Aditivo ao Contrato Nº 061-06-2025', 'term', 'review', 'Prorrogação do prazo de vigência do contrato por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'As partes ajustam a continuidade da prestação de serviços pelo prazo de 06/03/2026 até 06/05/2026, mantendo-se válidas as demais cláusulas contratuais.', 'Resumo IA: O aditivo prorrogou o contrato por mais 60 dias, alterando a data de término para 06 de maio de 2026. As cláusulas não conflitantes permanecem inalteradas.', '2026-04-09 04:00:00', 1, '2026-04-20 22:30:26', '2026-04-20 22:30:26'),
  (150001, 180001, 'ADT-002', 'Segundo Aditivo ao Contrato N° 062-06-2025 de Prestação de Serviços', 'term', 'review', 'Prorrogação do contrato por mais 60 dias, com novo prazo de vigência.', NULL, NULL, '2026-05-06 04:00:00', 'O prazo de vigência do contrato é prorrogado para o período de 06/03/2026 a 06/05/2026. Mantêm-se válidas todas as demais cláusulas não conflitantes.', 'Resumo IA: O aditivo prorroga o prazo de vigência do contrato por mais 60 dias. As condições contratuais não são alteradas, exceto pelo novo prazo estabelecido.', '2026-04-06 04:00:00', 1, '2026-04-20 23:39:31', '2026-04-20 23:39:31'),
  (150002, 180002, 'ADT-002', 'Segundo Aditivo ao Contrato N° 063-06-2025', 'term', 'review', 'Prorrogação do prazo de vigência do contrato por mais 60 dias.', NULL, NULL, '2026-05-06 04:00:00', 'O prazo de vigência do contrato é prorrogado de 06/03/2026 até 06/05/2026, mantendo as demais cláusulas inalteradas. O anexo possui efeitos retroativos a 06 de março de 2026.', 'Resumo IA: O Segundo Aditivo prorroga o prazo do contrato por mais 60 dias. As condições contratuais permanecem inalteradas, e o aditivo possui efeitos retroativos à data de início do serviço.', '2026-04-06 04:00:00', 1, '2026-04-20 23:49:31', '2026-04-20 23:49:31'),
  (180001, 210001, 'Anexo 2', 'Regulamento para Atividades de Campo', 'scope', 'review', 'Estabelece diretrizes e normas para atividades de campo das empresas do Grupo Arqueo.', NULL, NULL, NULL, 'O aditivo define as normas de mobilização e desmobilização, prestação de contas, logística, uso de veículos, EPIs e pagamentos para as atividades de campo da contratada, incluindo a descrição dos direitos e obrigações de ambas as partes.', 'Resumo IA: Este aditivo apresenta diretrizes claras para a execução das atividades de campo, especificando responsabilidades da contratada em relação a deslocamentos, reembolsos e uso de equipamentos, visando garantir segurança e conformidade operacional.', '2026-02-13 05:00:00', 1, '2026-04-24 17:06:14', '2026-04-24 17:06:14');

-- ------------------------------------------------------------
-- Tabela: contract_clicksign_events
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_clicksign_events`;
CREATE TABLE `contract_clicksign_events` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `clicksignDocumentId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eventType` enum('envelope_created','document_uploaded','signers_added','requirements_set','envelope_activated','notification_sent','signer_signed','signer_refused','envelope_completed','envelope_cancelled','envelope_expired','resend','send_failed','webhook_received') COLLATE utf8mb4_unicode_ci NOT NULL,
  `eventData` json DEFAULT NULL,
  `signerId` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `clicksignEnvelopeId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `errorMessage` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `httpStatus` int DEFAULT NULL,
  `requestId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  KEY `contract_clicksign_events_contractId_contracts_id_fk` (`contractId`),
  CONSTRAINT `contract_clicksign_events_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

