  (180001, 360001, NULL, 'send_failed', '[object Object]', NULL, '2026-05-11 19:11:33', '47ad96bc-db68-422a-86cf-7279d9a1bc11', 'Erro de conexão com Clicksign após 3 tentativas: Body is unusable: Body has already been read', 0, NULL),
  (180002, 360001, NULL, 'send_failed', '[object Object]', NULL, '2026-05-11 19:16:41', '47ad96bc-db68-422a-86cf-7279d9a1bc11', '<!--\n  toggle_internationalization_errors_pages_enabled\n  TODO: Remove this file\n-->\n<!DOCTYPE html>\n<html>\n<head>\n<title>Clicksign</title>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<link href="/favicon.ico" type="image/x-icon" rel="icon">\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n<link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap" rel="stylesheet">\n<style>\n  * {\n    box-sizing: border-box;\n  }\n  html {\n    height: 100%;\n  }\n  body {\n    margin: 0;\n    height: 100%;\n    color: #181818;\n    background-color: #fff;\n    font-family: \'DM Sans\', sans-serif;\n    font-size: 14px;\n    font-weight: 400;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    font-smoothing: antialiased;\n  }\n  .cs-error-pages-public {\n    padding: 16px 0;\n    display: flex;\n    align-items: center;\n    flex-direction: column;\n    margin: auto;\n    width: 100%;\n    height: 100%;\n    min-height: 100vh;\n  }\n  .cs-error-pages-public a {\n    color: #1474F5;\n  }\n  .cs-error-pages-public a:hover {\n    color: #4591f7;\n  }\n  .cs-error-pages-public img {\n    width: 100%;\n    height: auto;\n  }\n  .cs-error-pages-public > .text,\n  .cs-error-pages-public > .image {\n    margin: 0 16px;\n  }\n  .cs-error-pages-public > .text .image {\n    margin-bottom: 16px;\n  }\n  .cs-error-pages-public > .text .info {\n    margin-bottom: 16px;\n  }\n  .cs-error-pages-public .info .description {\n    color: #91959a;\n    font-size: 16px;\n    text-transform: uppercase;\n  }\n  .cs-error-pages-public > .text .info .title {\n    margin: 0 0 8px;\n    font-size: 24px;\n    font-weight: 700;\n  }\n  .cs-error-pages-public > .text .info .subtitle {\n    margin: 0 0 8px;\n    color: #83878d;\n    font-size: 16px;\n    font-weight: 400;\n  }\n  .cs-error-pages-public > .text .content {\n    margin-bottom: 32px;\n    line-height: 1.7;\n  }\n  .cs-error-pages-public > .text .logo {\n    max-width: 150px;\n  }\n  .cs-error-pages-public > .image {\n    display: none;\n    margin: 0 auto;\n    flex-grow: 1;\n    max-width: 570px;\n  }\n  @media (min-width: 768px) {\n    .cs-error-pages-public {\n      padding: 72px 0;\n      flex-direction: row;\n      justify-content: center;\n      align-items: flex-start;\n      max-width: 1140px;\n    }\n    .cs-error-pages-public > .text {\n      max-width: 486px;\n    }\n    .cs-error-pages-public > .text .info {\n      margin-bottom: 32px;\n    }\n    .cs-error-pages-public > .text .info .title {\n      font-size: 36px;\n    }\n    .cs-error-pages-public > .text .info .subtitle {\n      font-size: 24px;\n    }\n    .cs-error-pages-public > .text .image {\n      display: none;\n    }\n    .cs-error-pages-public > .image {\n      display: block;\n    }\n  }\n</style>\n</head>\n\n<body>\n  <section class="cs-error-pages-public">\n    <div class="text">\n      <header class="info">\n        <span class="description">Erro 404</span>\n        <h1 class="title">Puxa! Página indisponível</h1>\n        <h2 class="subtitle">O link que você está tentando acessar está incorreto.</h2>\n      </header>\n\n      <div class="image">\n        <img src="/errors/404.svg" alt="404">\n      </div>\n\n      <div class="content">\n        <p>Fique calmo! Você pode explorar a nossa <a href="https://clicksign.com" target="_blank">página inicial</a> ou fazer <a href="https://app.clicksign.com/signin" target="_blank">login</a>.</p>\n        <p>Precisa de ajuda? Visite nossa <a href="https://ajuda.clicksign.com" target="_blank">Central de Ajuda</a> ou envie um e-mail para <a href="mailto:ajuda@clicksign.com">ajuda@clicksign.com</a>.</p>\n      </div>\n\n      <footer class="logo">\n        <a href="https://clicksign.com" target="_blank">\n          <img alt="Clicksign Logo" src="/logo-clicksign-full-black-2024.svg">\n        </a>\n      </footer>\n    </div>\n\n    <div class="image">\n      <img src="/errors/404.svg" alt="404">\n    </div>\n  </section>\n</body>\n</html>\n', 404, '3f8a7b3d-473d-44a1-b07b-d44dac98aaa4'),
