-- ------------------------------------------------------------
-- Tabela: contract_expiration_notifications
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_expiration_notifications`;
CREATE TABLE `contract_expiration_notifications` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `supplierId` int NOT NULL,
  `daysBeforeExpiration` int NOT NULL,
  `effectiveDateSource` enum('original','amendment') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'original',
  `amendmentId` int DEFAULT NULL,
  `sentAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `notificationTitle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `contract_expiration_notifications_contractId_contracts_id_fk` (`contractId`),
  KEY `contract_expiration_notifications_supplierId_suppliers_id_fk` (`supplierId`),
  CONSTRAINT `contract_expiration_notifications_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `contract_expiration_notifications_supplierId_suppliers_id_fk` FOREIGN KEY (`supplierId`) REFERENCES `suppliers` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- (sem dados)

-- ------------------------------------------------------------
-- Tabela: contract_items
