DROP TABLE IF EXISTS `contract_items`;
CREATE TABLE `contract_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` decimal(10,3) DEFAULT NULL,
  `unitPrice` decimal(15,2) DEFAULT NULL,
  `totalPrice` decimal(15,2) DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `contract_items_contractId_contracts_id_fk` (`contractId`),
  CONSTRAINT `contract_items_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

