-- ------------------------------------------------------------
-- Tabela: contract_signers
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_signers`;
CREATE TABLE `contract_signers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(320) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cpfCnpj` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('contractor','contracted','witness','guarantor') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'contractor',
  `signOrder` int DEFAULT '1',
  `clicksignSignerId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signedAt` timestamp NULL DEFAULT NULL,
  `status` enum('pending','signed','refused','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `clicksignRequirementId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `emailDeliveryStatus` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lastNotifiedAt` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  KEY `contract_signers_contractId_contracts_id_fk` (`contractId`),
  CONSTRAINT `contract_signers_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

