-- ------------------------------------------------------------
-- Tabela: contract_templates
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_templates`;
CREATE TABLE `contract_templates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contractType` enum('service','supply','lease','consulting','maintenance','other') COLLATE utf8mb4_unicode_ci DEFAULT 'service',
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `fileUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fileName` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organizationalGroupId` int DEFAULT NULL,
  `orgCompanyId` int DEFAULT NULL,
  `fileKey` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  KEY `contract_templates_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `contract_templates_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contract_templates` (`id`, `name`, `description`, `contractType`, `content`, `isActive`, `createdById`, `createdAt`, `updatedAt`, `fileUrl`, `fileName`, `organizationalGroupId`, `orgCompanyId`, `fileKey`) VALUES
  (1, 'Contrato Simples de Prestação de Serviços Recorrentes', 'Modelo contratual para serviços recorrentes de baixa complexidade, com estrutura formal completa e menor rigidez operacional.', 'service', 'CONTRATO SIMPLES DE PRESTAÇÃO DE SERVIÇOS RECORRENTES\n\nModelo Contratual — Nível de Rigidez: 1/5\nTipo: Prestação de Serviços Recorrentes\n\n---\n\nCONTRATO DE PRESTAÇÃO DE SERVIÇOS RECORRENTES N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato de Prestação de Serviços Recorrentes ("Contrato"), que se regerá pelas cláusulas e condições seguintes:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratada").\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços recorrentes descritos no Anexo I deste instrumento ("Serviços"), a serem executados de forma contínua durante toda a vigência contratual.\n\n1.2. Os Serviços objeto deste Contrato são de natureza recorrente e de baixa complexidade operacional, sendo prestados em regime de continuidade, conforme periodicidade e condições estabelecidas neste instrumento.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional e legal necessária para a execução dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO E DOS ENTREGÁVEIS\n\n2.1. O escopo dos Serviços compreende todas as atividades, tarefas e entregas descritas no Anexo I, que integra o presente Contrato para todos os fins de direito.\n\n2.2. A Contratada deverá executar os Serviços com diligência, profissionalismo e qualidade técnica adequada, observando as melhores práticas do mercado aplicáveis à natureza das atividades contratadas.\n\n2.3. Os entregáveis periódicos, quando aplicáveis, serão definidos de comum acordo entre as Partes e formalizados em cronograma específico, que poderá ser ajustado mediante comunicação escrita entre as Partes, sem necessidade de aditamento contratual, desde que não implique alteração de valor ou prazo global.\n\n2.4. A Contratante poderá solicitar ajustes razoáveis no escopo dos Serviços, desde que tais ajustes não impliquem acréscimo de custo ou complexidade relevante. Ajustes que impliquem variação de valor deverão ser formalizados por aditamento.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser renovado por iguais e sucessivos períodos mediante acordo escrito entre as Partes.\n\n3.2. A renovação do Contrato poderá ser formalizada por meio de simples notificação escrita, com antecedência mínima de [PRAZO DE ANTECEDÊNCIA] dias antes do término do período vigente, sem necessidade de celebração de novo instrumento.\n\n3.3. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo I.\n\n3.4. Qualquer das Partes poderá não renovar o Contrato ao término do período vigente, mediante comunicação escrita à outra Parte com antecedência mínima de [PRAZO] dias, sem que tal decisão configure rescisão antecipada ou gere qualquer ônus.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor mensal de R$ [VALOR] ([VALOR POR EXTENSO]), perfazendo o valor total estimado para o período inicial de vigência de R$ [VALOR TOTAL] ([VALOR TOTAL POR EXTENSO]).\n\n4.2. O valor contratual é fixo para o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução dos Serviços, incluindo, sem limitação, mão de obra, encargos trabalhistas e previdenciários, tributos, deslocamentos e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após prévia aprovação escrita da Contratante e formalização de aditamento contratual ou ordem de serviço específica.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado mensalmente, até o [DIA] dia útil do mês subsequente à prestação dos Serviços, mediante apresentação de nota fiscal ou fatura pela Contratada, devidamente acompanhada dos documentos exigidos pela legislação fiscal aplicável.\n\n5.2. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada, cujos dados constam do Anexo II deste instrumento.\n\n5.3. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso.\n\n5.4. A Contratada deverá emitir as notas fiscais em conformidade com a legislação tributária vigente, indicando corretamente os serviços prestados, os tributos incidentes e os dados das Partes.\n\n5.5. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, sob pena de aceitação tácita do valor faturado.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 30 (trinta) dias da data de sua aplicação, sendo aplicado automaticamente caso a Contratante não se manifeste contrariamente no prazo de 15 (quinze) dias.\n\n6.3. As Partes poderão, de comum acordo, adotar índice diverso do previsto nesta cláusula, desde que tal acordo seja formalizado por escrito.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com qualidade, diligência e profissionalismo, observando as normas técnicas e legais aplicáveis;\n\nb) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação exigidas para a execução dos Serviços;\n\nc) Designar profissional qualificado como ponto focal para comunicação com a Contratante, responsável pelo acompanhamento e coordenação dos Serviços;\n\nd) Comunicar à Contratante, com a maior brevidade possível, qualquer ocorrência que possa comprometer a execução regular dos Serviços;\n\ne) Cumprir a legislação trabalhista, previdenciária, fiscal e ambiental aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos;\n\nf) Guardar sigilo sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato;\n\ng) Reparar, no prazo acordado entre as Partes, eventuais falhas ou inadequações nos Serviços prestados, sem ônus adicional para a Contratante.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato;\n\nb) Fornecer à Contratada, em tempo hábil, todas as informações, documentos e acessos necessários à execução dos Serviços;\n\nc) Designar interlocutor responsável pelo acompanhamento dos Serviços e pela comunicação com a Contratada;\n\nd) Comunicar à Contratada, com antecedência razoável, eventuais alterações em seus processos internos que possam impactar a execução dos Serviços;\n\ne) Colaborar com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade;\n\nf) Avaliar e aprovar os entregáveis no prazo acordado, evitando atrasos que possam impactar o cronograma de execução.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais e estratégicos da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços ou assessores que necessitem conhecê-las para os fins deste Contrato, desde que previamente informados da natureza confidencial das informações e vinculados a obrigações de sigilo equivalentes às previstas neste instrumento.\n\n9.3. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato;\nb) Já fossem de conhecimento da Parte receptora antes da celebração deste instrumento;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais;\nd) Devam ser divulgadas por força de lei, regulamento ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível.\n\n9.4. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 2 (dois) anos após o término ou rescisão deste Contrato.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD) e demais normas aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato e de acordo com as instruções da Contratante.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais adequadas para proteger os dados pessoais a que tiver acesso contra acessos não autorizados, perdas, destruição ou qualquer forma de tratamento inadequado.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 72 (setenta e duas) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre a natureza e extensão do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução da Contratante, devolver ou eliminar os dados pessoais tratados em razão deste instrumento, salvo obrigação legal de retenção.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos e materiais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição ou ônus adicional.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável e irretratável, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação e comunicação ao público.\n\n11.3. A Contratada declara que os Serviços prestados e os materiais entregues não violam direitos de propriedade intelectual de terceiros, responsabilizando-se por eventuais reclamações nesse sentido.\n\n11.4. As ferramentas, metodologias e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade, sendo concedida à Contratante licença de uso não exclusiva e não transferível para os fins deste Contrato.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos que causar à outra em decorrência do descumprimento das obrigações previstas neste Contrato, desde que devidamente comprovados.\n\n12.2. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio ou danos imateriais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo ou culpa grave.\n\n12.3. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total pago nos últimos 6 (seis) meses de vigência do Contrato, exceto nos casos de dolo, fraude ou violação de obrigações de confidencialidade e proteção de dados.\n\n12.4. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes de atos ou omissões da Contratante, caso fortuito ou força maior.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O descumprimento injustificado de obrigações contratuais relevantes por qualquer das Partes poderá ensejar a aplicação de advertência escrita, como medida prévia à rescisão contratual.\n\n13.2. Em caso de descumprimento reiterado ou de gravidade relevante, a Parte prejudicada poderá rescindir o Contrato, nos termos da Cláusula Décima Quarta, sem prejuízo do direito à reparação dos danos comprovadamente sofridos.\n\n13.3. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observado o princípio da razoabilidade, e somente após notificação prévia com prazo razoável para regularização.\n\n13.4. Não serão aplicadas penalidades nos casos em que o descumprimento decorra de caso fortuito, força maior ou atos atribuíveis à própria Parte prejudicada.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 30 (trinta) dias;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais, após notificação prévia com prazo de 15 (quinze) dias para regularização.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada os valores correspondentes aos Serviços já prestados e não pagos, sem qualquer multa rescisória adicional.\n\n14.3. Em caso de rescisão sem justa causa pela Contratada antes do término do período contratual, esta deverá concluir os Serviços em andamento ou garantir a transição adequada para outro prestador, no prazo acordado entre as Partes.\n\n14.4. A rescisão deste Contrato não afetará os direitos e obrigações das Partes já constituídos até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade e proteção de dados.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa) e demais normas aplicáveis ao combate à corrupção, ao suborno e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas ou para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas de governança corporativa e de compliance compatíveis com os princípios de integridade, transparência e ética nos negócios.\n\n15.4. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada poderá subcontratar partes dos Serviços a terceiros especializados, desde que previamente comunicado à Contratante, responsabilizando-se integralmente pela qualidade e pelo cumprimento das obrigações contratuais pelos subcontratados.\n\n16.2. A Contratante poderá, a seu critério, solicitar a substituição de subcontratado que demonstre incapacidade técnica ou que não atenda aos padrões mínimos de qualidade exigidos.\n\n16.3. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte.\n\n16.4. A subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações e solicitações relacionadas a este Contrato deverão ser realizadas por escrito, por meio de carta com aviso de recebimento, e-mail com confirmação de leitura ou outro meio que permita a comprovação do recebimento.\n\n17.2. As comunicações deverão ser endereçadas aos representantes e contatos indicados pelas Partes no Anexo III deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio.\n\n17.4. Alterações relevantes nas condições de execução dos Serviços, nos valores contratuais ou nos prazos deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis, os seguintes anexos:\n\nAnexo I — Descrição detalhada dos Serviços, escopo, periodicidade e entregáveis;\nAnexo II — Dados bancários da Contratada para fins de pagamento;\nAnexo III — Representantes e contatos das Partes para fins de comunicação;\nAnexo IV — Cronograma de execução e marcos de entrega, quando aplicável.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas.\n\n18.3. Os Anexos poderão ser atualizados de comum acordo entre as Partes, mediante comunicação escrita, sem necessidade de aditamento ao instrumento principal, desde que tais atualizações não impliquem alteração de valores, prazos ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos ou precedente para situações futuras.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada, tendo ambas as formas igual validade jurídica nos termos da legislação vigente.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus representantes, pelo prazo de 30 (trinta) dias contados da notificação do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido, qualquer das Partes poderá submeter a controvérsia ao foro eleito, nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 1, NULL, '2026-04-15 19:41:48', '2026-04-15 19:41:48', NULL, NULL, NULL, NULL, NULL),
  (2, 'Contrato de Prestação de Serviços com Controle Básico de Entregas', 'Modelo contratual para serviços com entregas definidas, aceite básico e maior previsibilidade operacional.', 'service', 'CONTRATO DE PRESTAÇÃO DE SERVIÇOS COM CONTROLE BÁSICO DE ENTREGAS\n\nModelo Contratual — Nível de Rigidez: 2/5\nTipo: Prestação de Serviços com Entregas Definidas\n\n---\n\nCONTRATO DE PRESTAÇÃO DE SERVIÇOS COM CONTROLE BÁSICO DE ENTREGAS N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato de Prestação de Serviços com Controle Básico de Entregas ("Contrato"), que se regerá pelas cláusulas e condições seguintes:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratada").\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços especificados e delimitados no Anexo I deste instrumento ("Serviços"), a serem executados conforme o cronograma, os entregáveis e os critérios de aceite estabelecidos neste instrumento e em seus Anexos.\n\n1.2. Os Serviços objeto deste Contrato possuem escopo definido e entregas identificáveis, devendo ser executados com estrita observância das especificações técnicas, dos padrões de qualidade e dos prazos previstos neste instrumento.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional e legal necessária para a execução dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato e a comunicar à Contratante qualquer alteração que possa comprometer tal capacidade.\n\n1.4. Quaisquer serviços não expressamente previstos no Anexo I não integram o escopo deste Contrato e somente poderão ser executados mediante prévia formalização de aditamento contratual ou ordem de serviço específica, aprovada por escrito pela Contratante.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO, DOS ENTREGÁVEIS E DOS CRITÉRIOS DE ACEITE\n\n2.1. O escopo dos Serviços compreende todas as atividades, tarefas e entregas descritas no Anexo I, que integra o presente Contrato para todos os fins de direito, com indicação expressa dos entregáveis, das especificações técnicas aplicáveis e dos marcos de execução.\n\n2.2. Cada entregável previsto no Anexo I deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado de documentação técnica suficiente para sua avaliação, observado o prazo de submissão estabelecido no cronograma.\n\n2.3. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento de cada entregável, para aprová-lo ou rejeitá-lo, mediante comunicação escrita fundamentada. O silêncio da Contratante no referido prazo implicará aceitação tácita do entregável submetido.\n\n2.4. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo de [PRAZO] dias úteis para realizar as correções e ajustes indicados pela Contratante, sem ônus adicional para esta, submetendo nova versão para aprovação.\n\n2.5. A rejeição reiterada de um mesmo entregável, sem justificativa técnica válida, ou o descumprimento do prazo de correção previsto no item 2.4, poderá ensejar a aplicação das penalidades previstas na Cláusula Décima Terceira deste instrumento.\n\n2.6. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos ou defeitos que se manifestem posteriormente, dentro do prazo de garantia estabelecido no Anexo I.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por igual período mediante acordo escrito entre as Partes, formalizado com antecedência mínima de [PRAZO] dias antes do término da vigência.\n\n3.2. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo I.\n\n3.3. O cronograma detalhado de execução dos Serviços, com os marcos intermediários e as datas de entrega de cada entregável, constará do Anexo I e será de cumprimento obrigatório por ambas as Partes.\n\n3.4. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com a maior brevidade possível, acompanhados de justificativa técnica e de proposta de replanejamento, para análise e aprovação da Contratante.\n\n3.5. Atrasos decorrentes de atos ou omissões da Contratante, de caso fortuito ou de força maior, devidamente comprovados, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo entre as Partes.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$ [VALOR] ([VALOR POR EXTENSO]), conforme o cronograma financeiro estabelecido no Anexo II deste instrumento.\n\n4.2. O valor contratual é fixo e irreajustável durante o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento e de alteração de escopo formalizada por aditamento contratual.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução dos Serviços, incluindo, sem limitação, mão de obra, encargos trabalhistas e previdenciários, tributos, deslocamentos, materiais e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após prévia aprovação escrita da Contratante e formalização de aditamento contratual com definição de valor, prazo e entregáveis adicionais.\n\n4.5. A Contratante não será responsável pelo pagamento de quaisquer valores além dos expressamente previstos neste instrumento e em seus Anexos, salvo nos casos de aditamento contratual devidamente formalizado.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo I, mediante apresentação de nota fiscal ou fatura pela Contratada.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da respectiva nota fiscal, devidamente acompanhada dos documentos exigidos pela legislação fiscal aplicável.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada, cujos dados constam do Anexo III deste instrumento.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso, sem prejuízo da atualização monetária pelo IPCA.\n\n5.5. A Contratante poderá reter o pagamento de parcela vinculada a entregável rejeitado até a aprovação formal da versão corrigida, sem que tal retenção configure inadimplemento contratual.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados, sob pena de aceitação tácita do valor faturado.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice oficial que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 30 (trinta) dias da data de sua aplicação, sendo aplicado automaticamente caso a Contratante não se manifeste contrariamente no prazo de 15 (quinze) dias.\n\n6.3. Não haverá reajuste durante o período inicial de vigência do Contrato, salvo nos casos de alteração de escopo formalizada por aditamento ou de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes.\n\n6.4. As Partes poderão, de comum acordo, adotar índice diverso do previsto nesta cláusula, desde que tal acordo seja formalizado por escrito e não implique desequilíbrio econômico-financeiro do Contrato.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com qualidade, diligência e profissionalismo, observando as normas técnicas, as especificações do Anexo I e as melhores práticas do mercado aplicáveis à natureza das atividades contratadas;\n\nb) Cumprir rigorosamente o cronograma de execução e as datas de entrega dos entregáveis previstos no Anexo I;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação exigidas para a execução dos Serviços, incluindo registros profissionais e certidões aplicáveis;\n\nd) Designar profissional qualificado como gestor do contrato, responsável pelo acompanhamento, coordenação e comunicação com a Contratante, com poderes para tomar decisões operacionais no âmbito dos Serviços;\n\ne) Comunicar à Contratante, com a maior brevidade possível, qualquer ocorrência que possa comprometer a execução regular dos Serviços ou o cumprimento do cronograma;\n\nf) Cumprir a legislação trabalhista, previdenciária, fiscal, ambiental e de segurança do trabalho aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos;\n\ng) Guardar sigilo sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato;\n\nh) Reparar, no prazo estabelecido na Cláusula Segunda, eventuais falhas, inadequações ou não conformidades nos Serviços prestados, sem ônus adicional para a Contratante;\n\ni) Apresentar, quando solicitado pela Contratante, relatórios de progresso e de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato;\n\nb) Fornecer à Contratada, em tempo hábil, todas as informações, documentos, acessos e recursos necessários à execução dos Serviços, conforme especificado no Anexo I;\n\nc) Designar gestor do contrato com poderes para aprovar entregáveis, emitir ordens de serviço e tomar decisões operacionais no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável, eventuais alterações em seus processos internos, requisitos técnicos ou condições operacionais que possam impactar a execução dos Serviços;\n\nf) Colaborar com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade, evitando atrasos no cronograma de execução;\n\ng) Disponibilizar infraestrutura, equipamentos e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos e de propriedade intelectual da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços ou assessores que necessitem conhecê-las para os fins deste Contrato, desde que previamente informados da natureza confidencial das informações e vinculados a obrigações de sigilo equivalentes às previstas neste instrumento.\n\n9.3. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato;\nb) Já fossem de conhecimento comprovado da Parte receptora antes da celebração deste instrumento;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais, o que deverá ser comprovado documentalmente;\nd) Devam ser divulgadas por força de lei, regulamento ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível, buscando, na medida do possível, a proteção das informações divulgadas.\n\n9.4. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 3 (três) anos após o término ou rescisão deste Contrato, independentemente do motivo que lhe deu causa.\n\n9.5. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará a responsabilização da Parte infratora pelos danos causados, nos termos da Cláusula Décima Segunda deste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD), o Regulamento Geral de Proteção de Dados da União Europeia (GDPR), quando aplicável, e demais normas aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato e de acordo com as instruções documentadas da Contratante.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais adequadas e proporcionais aos riscos envolvidos para proteger os dados pessoais a que tiver acesso contra acessos não autorizados, perdas, destruição, alteração ou qualquer forma de tratamento inadequado.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 48 (quarenta e oito) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre a natureza, extensão e possível impacto do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução da Contratante, devolver ou eliminar de forma segura os dados pessoais tratados em razão deste instrumento, fornecendo comprovação documental da eliminação, salvo obrigação legal de retenção.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita da Contratante, devendo garantir que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos e materiais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição ou ônus adicional.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação, comunicação ao público e quaisquer outros direitos de exploração previstos na legislação aplicável.\n\n11.3. A Contratada declara que os Serviços prestados e os materiais entregues não violam direitos de propriedade intelectual de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas ou ações judiciais nesse sentido, incluindo os custos de defesa da Contratante.\n\n11.4. As ferramentas, metodologias, processos e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade, sendo concedida à Contratante licença de uso não exclusiva, intransferível e limitada aos fins deste Contrato.\n\n11.5. A Contratada deverá, ao final do Contrato, entregar à Contratante todos os arquivos, documentos, códigos-fonte e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica adequada.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos e comprovados que causar à outra em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato.\n\n12.2. A Contratada será responsável pela qualidade técnica dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos e não conformidades identificados durante o prazo de garantia estabelecido no Anexo I.\n\n12.3. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio ou danos imateriais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo, fraude ou culpa grave devidamente comprovados.\n\n12.4. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual.\n\n12.5. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes de atos ou omissões da Contratante, de caso fortuito ou de força maior, desde que tais ocorrências sejam devidamente comunicadas e comprovadas.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previsto no cronograma do Anexo I sujeitará a Contratada ao pagamento de multa moratória de 0,5% (zero vírgula cinco por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 10% (dez por cento) do valor total do Contrato.\n\n13.2. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 5% (cinco por cento) do valor total do Contrato, sem prejuízo do direito à reparação dos danos comprovadamente sofridos.\n\n13.3. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observado o princípio da razoabilidade, e somente após notificação prévia com prazo razoável para regularização, exceto nos casos de descumprimento que, por sua natureza, tornem inviável a concessão de prazo.\n\n13.4. Os valores das multas poderão ser descontados dos pagamentos devidos à Contratada ou cobrados judicialmente, a critério da Contratante.\n\n13.5. Não serão aplicadas penalidades nos casos em que o descumprimento decorra de caso fortuito, força maior, atos atribuíveis à própria Parte prejudicada ou de circunstâncias devidamente comunicadas e aceitas pela outra Parte.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 45 (quarenta e cinco) dias;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais, após notificação prévia com prazo de 15 (quinze) dias para regularização;\nd) Por qualquer das Partes, de forma imediata, nos casos de falência, recuperação judicial ou extrajudicial, insolvência ou dissolução da outra Parte.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada:\n\na) Os valores correspondentes aos Serviços já prestados e entregáveis aprovados até a data de rescisão;\nb) Os custos comprovados e não reembolsados incorridos pela Contratada em razão do Contrato;\nc) Multa rescisória equivalente a 10% (dez por cento) do valor remanescente do Contrato.\n\n14.3. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional.\n\n14.4. Em caso de rescisão com justa causa pela Contratada, esta terá direito ao recebimento de todos os valores devidos pelos Serviços prestados até a data de rescisão, acrescidos de indenização pelos danos comprovadamente sofridos.\n\n14.5. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados e propriedade intelectual.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa), o Foreign Corrupt Practices Act (FCPA), quando aplicável, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas, para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas, ou para qualquer finalidade que contrarie a legislação vigente.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas de governança corporativa e de compliance compatíveis com os princípios de integridade, transparência, ética nos negócios e responsabilidade social.\n\n15.4. A Contratada declara que não emprega menores de 18 (dezoito) anos em trabalho noturno, perigoso ou insalubre, nem menores de 16 (dezesseis) anos em qualquer trabalho, salvo na condição de aprendiz, a partir de 14 (quatorze) anos.\n\n15.5. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis e da responsabilização pelos danos causados.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada somente poderá subcontratar partes dos Serviços a terceiros especializados mediante prévia autorização escrita da Contratante, que poderá condicioná-la à apresentação de informações sobre o subcontratado, incluindo qualificação técnica e certidões de regularidade fiscal e trabalhista.\n\n16.2. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos e omissões dos subcontratados.\n\n16.3. A Contratante poderá, a seu critério, solicitar a substituição de subcontratado que demonstre incapacidade técnica, irregularidade legal ou que não atenda aos padrões de qualidade exigidos, devendo a Contratada promover a substituição no prazo de [PRAZO] dias.\n\n16.4. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte, não podendo ser recusado sem justificativa razoável.\n\n16.5. A subcontratação não autorizada constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades previstas na Cláusula Décima Terceira e podendo ensejar a rescisão do Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações e solicitações relacionadas a este Contrato deverão ser realizadas por escrito, por meio de carta com aviso de recebimento, e-mail com confirmação de leitura ou plataforma de gestão de projetos previamente acordada entre as Partes.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato indicados pelas Partes no Anexo IV deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio, desde que não haja notificação de falha no envio.\n\n17.4. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável.\n\n17.5. Alterações no escopo, nos valores contratuais, nos prazos ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis, os seguintes anexos:\n\nAnexo I — Descrição detalhada dos Serviços, escopo, entregáveis, especificações técnicas, critérios de aceite e prazo de garantia;\nAnexo II — Cronograma financeiro com valores e condições de pagamento por entregável ou marco;\nAnexo III — Dados bancários da Contratada para fins de pagamento;\nAnexo IV — Gestores do contrato e contatos das Partes para fins de comunicação;\nAnexo V — Cronograma detalhado de execução com marcos intermediários e datas de entrega.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas.\n\n18.3. Os Anexos poderão ser atualizados de comum acordo entre as Partes, mediante comunicação escrita assinada pelos gestores do contrato, sem necessidade de aditamento ao instrumento principal, desde que tais atualizações não impliquem alteração de valores, prazos globais ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente para situações futuras ou modificação tácita das condições contratuais.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível por decisão judicial ou arbitral, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por escrito e assinadas por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato, pelo prazo de 15 (quinze) dias contados da notificação do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes poderão, de comum acordo, submeter a controvérsia à mediação ou à arbitragem, nos termos da Lei n.º 9.307/1996 e da Lei n.º 13.140/2015, antes de recorrer ao Poder Judiciário.\n\n20.4. Não havendo acordo quanto à mediação ou arbitragem, qualquer das Partes poderá submeter a controvérsia ao foro eleito nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 1, NULL, '2026-04-15 19:49:22', '2026-04-15 19:49:22', NULL, NULL, NULL, NULL, NULL),
  (3, 'Contrato Corporativo de Prestação de Serviços com SLA', 'Modelo contratual corporativo com SLA, critérios de aceite e maior rigor operacional.', 'service', 'CONTRATO CORPORATIVO DE PRESTAÇÃO DE SERVIÇOS COM SLA\n\nModelo Contratual — Nível de Rigidez: 3/5\nTipo: Prestação de Serviços Corporativos com Acordo de Nível de Serviço\n\n---\n\nCONTRATO CORPORATIVO DE PRESTAÇÃO DE SERVIÇOS COM SLA N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato Corporativo de Prestação de Serviços com Acordo de Nível de Serviço ("Contrato"), que se regerá pelas cláusulas e condições seguintes, as quais as Partes declaram ter lido, compreendido e aceito integralmente:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratada").\n\nAs Partes, em conjunto, serão denominadas "Partes" e, individualmente, "Parte".\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços técnicos especializados descritos no Anexo I — Especificação Técnica dos Serviços ("Serviços"), a serem executados em conformidade com o escopo, os entregáveis, os critérios de aceite, os Acordos de Nível de Serviço (SLA) e o cronograma estabelecidos neste instrumento e em seus Anexos.\n\n1.2. Os Serviços objeto deste Contrato possuem escopo técnico detalhado, com entregáveis claramente identificados, métricas de desempenho mensuráveis e critérios formais de aceite, devendo ser executados com estrita observância das especificações técnicas, das normas aplicáveis, dos padrões de qualidade corporativa e dos SLAs definidos no Anexo VI.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional, financeira e legal necessária para a execução integral dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato e a comunicar imediatamente à Contratante qualquer alteração que possa comprometer tal capacidade.\n\n1.4. Quaisquer serviços não expressamente previstos no Anexo I não integram o escopo deste Contrato e somente poderão ser executados mediante prévia aprovação formal da Contratante e formalização de aditamento contratual escrito, com definição de escopo, valor, prazo e entregáveis adicionais.\n\n1.5. A Contratada reconhece que a execução dos Serviços poderá envolver acesso a sistemas, infraestrutura, dados e informações sensíveis da Contratante, comprometendo-se a observar todos os protocolos de segurança, confidencialidade e proteção de dados estabelecidos neste instrumento e nas políticas internas da Contratante que lhe forem comunicadas.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO, DOS ENTREGÁVEIS, DOS CRITÉRIOS DE ACEITE E DO SLA\n\n2.1. O escopo técnico dos Serviços compreende todas as atividades, tarefas, entregáveis e responsabilidades descritas no Anexo I, que integra o presente Contrato para todos os fins de direito, com indicação expressa das especificações técnicas, dos padrões de qualidade aplicáveis e dos marcos de execução.\n\n2.2. Cada entregável previsto no Anexo I deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado de documentação técnica completa, relatório de testes ou validação e declaração de conformidade com as especificações, observado o prazo de submissão estabelecido no cronograma do Anexo V.\n\n2.3. Os critérios formais de aceite de cada entregável estão definidos no Anexo I e incluem, sem limitação: conformidade técnica com as especificações, aderência aos padrões de qualidade estabelecidos, ausência de defeitos críticos ou bloqueadores, cumprimento dos SLAs aplicáveis e aprovação nos testes de aceitação definidos.\n\n2.4. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento formal de cada entregável com sua documentação completa, para aprová-lo ou rejeitá-lo mediante comunicação escrita fundamentada, com indicação detalhada das não conformidades identificadas e dos critérios de aceite não atendidos.\n\n2.5. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo de [PRAZO] dias úteis para realizar as correções e ajustes necessários, sem ônus adicional para a Contratante, submetendo nova versão acompanhada de relatório de correções com indicação das não conformidades sanadas.\n\n2.6. A rejeição de entregável em segunda análise, por não conformidades já identificadas na primeira rejeição e não devidamente corrigidas, constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades previstas na Cláusula Décima Terceira e podendo ensejar a rescisão do Contrato por justa causa.\n\n2.7. Os Acordos de Nível de Serviço (SLA) aplicáveis a cada categoria de serviço estão definidos no Anexo VI e incluem, sem limitação: disponibilidade mínima dos sistemas ou serviços, tempo máximo de resposta a incidentes, tempo máximo de resolução, janelas de manutenção programada e métricas de desempenho operacional.\n\n2.8. O descumprimento dos SLAs definidos no Anexo VI ensejará a aplicação de créditos de serviço ou penalidades conforme tabela constante do mesmo Anexo, calculados proporcionalmente ao grau e à duração do descumprimento, sem prejuízo das demais sanções contratuais aplicáveis.\n\n2.9. A Contratada deverá disponibilizar à Contratante relatórios mensais de desempenho com indicação dos SLAs medidos no período, comparação com as metas estabelecidas, análise de causa raiz de eventuais descumprimentos e plano de ação corretiva para os indicadores abaixo da meta.\n\n2.10. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos, defeitos latentes ou não conformidades que se manifestem posteriormente, dentro do prazo de garantia estabelecido no Anexo I.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por períodos iguais e sucessivos mediante acordo escrito entre as Partes, formalizado com antecedência mínima de 60 (sessenta) dias antes do término da vigência.\n\n3.2. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo V, e estará condicionado ao cumprimento das condições precedentes eventualmente estabelecidas no Anexo I.\n\n3.3. O cronograma detalhado de execução dos Serviços, com os marcos intermediários, as datas de entrega de cada entregável e os marcos de pagamento correspondentes, constará do Anexo V e será de cumprimento obrigatório por ambas as Partes.\n\n3.4. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com antecedência mínima de [PRAZO] dias antes da data prevista de entrega, acompanhados de justificativa técnica detalhada, análise de impacto e proposta de replanejamento, para análise e aprovação formal da Contratante.\n\n3.5. A aprovação de replanejamento pela Contratante não constituirá renúncia ao direito de aplicar as penalidades cabíveis pelo atraso, salvo se expressamente previsto no instrumento de aprovação do replanejamento.\n\n3.6. Atrasos decorrentes exclusivamente de atos ou omissões da Contratante, de caso fortuito ou de força maior, devidamente comunicados e comprovados documentalmente, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo formal entre as Partes.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação integral dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$ [VALOR] ([VALOR POR EXTENSO]), conforme o cronograma financeiro detalhado no Anexo II deste instrumento, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução.\n\n4.2. O valor contratual é fixo e irreajustável durante o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento, de alteração de escopo formalizada por aditamento contratual e de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução integral dos Serviços, incluindo, sem limitação, mão de obra especializada, encargos trabalhistas e previdenciários, tributos, licenças de software, deslocamentos, hospedagem, materiais, equipamentos e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após aprovação formal escrita da Contratante, com indicação de valor, prazo e entregáveis adicionais, e formalização de aditamento contratual. A execução de serviços adicionais sem autorização prévia não gerará obrigação de pagamento para a Contratante.\n\n4.5. A Contratante não será responsável pelo pagamento de quaisquer valores além dos expressamente previstos neste instrumento e em seus Anexos, salvo nos casos de aditamento contratual devidamente formalizado e assinado por representantes autorizados de ambas as Partes.\n\n4.6. Os créditos de serviço decorrentes de descumprimento de SLA, conforme tabela do Anexo VI, serão deduzidos automaticamente dos valores das faturas subsequentes, sem necessidade de formalização adicional, salvo contestação fundamentada da Contratada no prazo de 5 (cinco) dias úteis.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo V, mediante apresentação de nota fiscal ou fatura pela Contratada, acompanhada dos documentos comprobatórios exigidos.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da respectiva nota fiscal, devidamente acompanhada de: (i) relatório de execução do período; (ii) certidões de regularidade fiscal e trabalhista atualizadas; e (iii) comprovantes de recolhimento de encargos aplicáveis.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada no Anexo III deste instrumento, sendo vedada a emissão de duplicatas, cheques ou outros títulos de crédito sem prévia autorização escrita da Contratante.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso e atualização monetária pelo IPCA, desde que o atraso não decorra de contestação fundamentada de valores pela Contratante.\n\n5.5. A Contratante poderá reter o pagamento de parcela vinculada a entregável rejeitado, a SLA não cumprido ou a obrigações acessórias não atendidas, sem que tal retenção configure inadimplemento contratual, devendo comunicar à Contratada os motivos da retenção no prazo de 5 (cinco) dias úteis.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados e dos critérios aplicados, sob pena de aceitação tácita do valor faturado.\n\n5.7. A Contratada não poderá ceder, endossar ou transferir os créditos decorrentes deste Contrato a terceiros sem prévia autorização escrita da Contratante.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice oficial que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 45 (quarenta e cinco) dias da data de sua aplicação, sendo aplicado mediante acordo formal entre as Partes, formalizado por aditamento contratual ou por comunicação escrita assinada pelos gestores do contrato.\n\n6.3. Não haverá reajuste durante o período inicial de vigência do Contrato, salvo nos casos de alteração de escopo formalizada por aditamento, de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes, ou de alteração de legislação tributária que impacte diretamente os custos dos Serviços.\n\n6.4. Em caso de desequilíbrio econômico-financeiro do Contrato decorrente de fatos imprevisíveis e alheios à vontade das Partes, qualquer delas poderá solicitar a revisão dos valores contratuais, mediante apresentação de documentação comprobatória e negociação de boa-fé, nos termos do artigo 317 do Código Civil.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com excelência técnica, diligência, profissionalismo e observância das melhores práticas do mercado, das normas técnicas aplicáveis e das especificações do Anexo I, garantindo a qualidade e a conformidade dos entregáveis com os critérios de aceite estabelecidos;\n\nb) Cumprir rigorosamente o cronograma de execução, as datas de entrega dos entregáveis e os SLAs definidos no Anexo VI, comunicando proativamente à Contratante qualquer risco de descumprimento;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação técnica exigidas para a execução dos Serviços, incluindo registros profissionais, certificações, licenças e certidões aplicáveis;\n\nd) Designar profissional sênior qualificado como gestor técnico do contrato, com poderes para tomar decisões operacionais, coordenar a equipe de execução e ser o ponto focal de comunicação com a Contratante;\n\ne) Manter equipe técnica qualificada e em número suficiente para a execução dos Serviços dentro dos prazos e padrões de qualidade estabelecidos, comunicando à Contratante qualquer substituição de profissional-chave com antecedência mínima de [PRAZO] dias;\n\nf) Comunicar à Contratante, com a maior brevidade possível e em prazo não superior a 24 (vinte e quatro) horas, qualquer ocorrência, incidente ou evento que possa comprometer a execução regular dos Serviços, o cumprimento do cronograma ou o atendimento dos SLAs;\n\ng) Cumprir integralmente a legislação trabalhista, previdenciária, fiscal, ambiental, de segurança do trabalho e de proteção de dados aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos e por seus reflexos sobre a Contratante;\n\nh) Guardar sigilo absoluto sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato, nos termos da Cláusula Nona;\n\ni) Reparar, no prazo estabelecido na Cláusula Segunda, eventuais falhas, inadequações, não conformidades ou defeitos nos Serviços prestados ou nos entregáveis entregues, sem ônus adicional para a Contratante;\n\nj) Apresentar à Contratante, na periodicidade estabelecida no Anexo I, relatórios de progresso, de desempenho de SLA e de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável, dos indicadores de qualidade e das ações corretivas em andamento;\n\nk) Adotar, em suas operações, práticas de governança corporativa, compliance e gestão de riscos compatíveis com os padrões exigidos pela Contratante e com a legislação aplicável;\n\nl) Participar de reuniões de acompanhamento, revisão de desempenho e comitês de gestão do contrato na periodicidade e formato definidos no Anexo I.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato, observadas as condições de aprovação de entregáveis e de apresentação de documentação fiscal;\n\nb) Fornecer à Contratada, em tempo hábil e de forma completa, todas as informações, documentos, especificações, acessos, credenciais e recursos necessários à execução dos Serviços, conforme especificado no Anexo I;\n\nc) Designar gestor técnico do contrato com poderes para aprovar entregáveis, emitir ordens de serviço, autorizar alterações de escopo e tomar decisões operacionais no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada e referência expressa aos critérios de aceite não atendidos em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável e não inferior a [PRAZO] dias, eventuais alterações em seus processos internos, requisitos técnicos, sistemas, políticas de segurança ou condições operacionais que possam impactar a execução dos Serviços ou o cumprimento dos SLAs;\n\nf) Colaborar ativamente com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade, evitando atrasos no cronograma de execução e no cumprimento dos SLAs;\n\ng) Disponibilizar infraestrutura, equipamentos, sistemas e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante;\n\nh) Participar das reuniões de acompanhamento, revisão de desempenho e comitês de gestão do contrato na periodicidade e formato definidos no Anexo I;\n\ni) Notificar a Contratada, de forma tempestiva e fundamentada, sobre qualquer descumprimento de obrigação contratual ou de SLA, antes de aplicar as penalidades previstas neste instrumento.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos, de propriedade intelectual, de clientes e de colaboradores da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços, assessores jurídicos ou técnicos que: (i) necessitem conhecê-las para os fins deste Contrato; (ii) sejam previamente informados da natureza confidencial das informações; e (iii) estejam vinculados a obrigações de sigilo equivalentes às previstas neste instrumento, por contrato escrito ou por disposição legal.\n\n9.3. Cada Parte deverá adotar medidas técnicas e organizacionais adequadas para proteger as Informações Confidenciais da outra Parte contra acesso não autorizado, divulgação indevida, perda, destruição ou qualquer forma de uso inadequado, observando padrões de segurança equivalentes aos que adota para proteger suas próprias informações confidenciais de mesma natureza, mas nunca inferiores a um padrão razoável de diligência.\n\n9.4. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato ou de qualquer outra obrigação de confidencialidade;\nb) Já fossem de conhecimento comprovado e documentado da Parte receptora antes da celebração deste instrumento, sem restrição de divulgação;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais, o que deverá ser comprovado documentalmente;\nd) Sejam recebidas de terceiros que as divulguem de forma lícita e sem restrição de confidencialidade;\ne) Devam ser divulgadas por força de lei, regulamento, ordem judicial ou determinação de autoridade competente, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível, buscando a proteção das informações divulgadas na medida do possível.\n\n9.5. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 5 (cinco) anos após o término ou rescisão deste Contrato, independentemente do motivo que lhe deu causa, sendo que as informações que constituam segredo de negócio permanecerão protegidas pelo prazo legal aplicável.\n\n9.6. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará a responsabilização da Parte infratora pelos danos diretos e indiretos causados, incluindo lucros cessantes e danos reputacionais, nos termos da Cláusula Décima Segunda deste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD), o Regulamento Geral de Proteção de Dados da União Europeia (GDPR), quando aplicável, e demais normas nacionais e internacionais aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato, de acordo com as instruções documentadas da Contratante e em observância aos princípios da finalidade, adequação, necessidade, livre acesso, qualidade dos dados, transparência, segurança, prevenção, não discriminação e responsabilização.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais robustas e proporcionais aos riscos envolvidos para proteger os dados pessoais a que tiver acesso, incluindo, sem limitação: controles de acesso baseados em perfil, criptografia de dados em trânsito e em repouso, registros de auditoria (logs), planos de resposta a incidentes e treinamento regular de sua equipe em proteção de dados.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 24 (vinte e quatro) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre: (i) natureza do incidente; (ii) categorias e volume de dados afetados; (iii) possível impacto sobre os titulares; (iv) medidas adotadas ou a adotar para mitigar os efeitos do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução documentada da Contratante, devolver ou eliminar de forma segura e irreversível os dados pessoais tratados em razão deste instrumento, fornecendo comprovação técnica da eliminação, salvo obrigação legal de retenção, hipótese em que deverá informar à Contratante os dados retidos e o fundamento legal aplicável.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita da Contratante, devendo garantir contratualmente que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento e respondendo solidariamente por eventuais violações.\n\n10.7. A Contratada deverá designar encarregado de proteção de dados (DPO) ou ponto focal de privacidade para as atividades desenvolvidas no âmbito deste Contrato, cujos dados de contato deverão constar do Anexo IV.\n\n10.8. As Partes comprometem-se a cooperar com a Autoridade Nacional de Proteção de Dados (ANPD) e com as autoridades de proteção de dados de outras jurisdições aplicáveis, fornecendo as informações solicitadas no âmbito de suas competências.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos, códigos, algoritmos, metodologias, materiais e demais criações intelectuais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição, ônus adicional ou necessidade de autorização da Contratada.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável, universal e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação, comunicação ao público, transformação, incorporação em outras obras e quaisquer outros direitos de exploração previstos na legislação de propriedade intelectual aplicável.\n\n11.3. A Contratada declara que os Serviços prestados, os entregáveis entregues e os materiais produzidos não violam direitos de propriedade intelectual, direitos autorais, patentes, marcas ou segredos de negócio de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas, notificações ou ações judiciais nesse sentido, incluindo os custos razoáveis de defesa da Contratante.\n\n11.4. As ferramentas, metodologias, frameworks, processos, bibliotecas e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade exclusiva, sendo concedida à Contratante licença de uso não exclusiva, intransferível, irrevogável e limitada aos fins deste Contrato e à operação dos entregáveis produzidos.\n\n11.5. A Contratada deverá, ao final do Contrato e quando solicitado durante sua vigência, entregar à Contratante todos os arquivos, documentos, códigos-fonte, scripts, configurações e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica completa e atualizada.\n\n11.6. A Contratada não poderá utilizar o nome, a marca, o logotipo ou qualquer outro elemento de identidade visual da Contratante em materiais de marketing, portfólio ou comunicações externas sem prévia autorização escrita da Contratante.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos e comprovados que causar à outra em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato, devendo a Parte prejudicada demonstrar o nexo de causalidade entre o descumprimento e o dano sofrido.\n\n12.2. A Contratada será responsável pela qualidade técnica dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos, não conformidades e falhas de desempenho identificados durante a execução do Contrato e dentro do prazo de garantia estabelecido no Anexo I.\n\n12.3. A Contratada será responsável pelos danos causados a terceiros em decorrência da execução dos Serviços, incluindo danos a colaboradores, clientes e parceiros da Contratante, devendo manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato.\n\n12.4. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio, danos imateriais ou danos consequenciais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo, fraude, culpa grave, violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual, devidamente comprovados.\n\n12.5. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados, propriedade intelectual ou responsabilidade perante terceiros.\n\n12.6. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes exclusivamente de atos ou omissões da Contratante, de caso fortuito ou de força maior, desde que tais ocorrências sejam comunicadas imediatamente e comprovadas documentalmente.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previsto no cronograma do Anexo V sujeitará a Contratada ao pagamento de multa moratória de 0,5% (zero vírgula cinco por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 15% (quinze por cento) do valor total do Contrato.\n\n13.2. O descumprimento dos SLAs definidos no Anexo VI, além dos créditos de serviço previstos no mesmo Anexo, poderá ensejar a aplicação de multa adicional de até 5% (cinco por cento) do valor mensal do Contrato, proporcional ao grau de descumprimento e ao impacto operacional causado à Contratante.\n\n13.3. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 10% (dez por cento) do valor total do Contrato, sem prejuízo do direito à reparação integral dos danos comprovadamente sofridos.\n\n13.4. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observados os princípios da razoabilidade e da proporcionalidade, e somente após notificação prévia com prazo razoável para regularização, exceto nos casos de descumprimento que, por sua natureza ou gravidade, tornem inviável ou desnecessária a concessão de prazo.\n\n13.5. Os valores das multas poderão ser descontados dos pagamentos devidos à Contratada, cobrados judicialmente ou deduzidos de garantias contratuais eventualmente prestadas, a critério da Contratante.\n\n13.6. Não serão aplicadas penalidades nos casos em que o descumprimento decorra exclusivamente de caso fortuito, força maior, atos atribuíveis à própria Parte prejudicada ou de circunstâncias devidamente comunicadas, documentadas e aceitas formalmente pela outra Parte.\n\n13.7. A aplicação de penalidades não exclui o direito da Parte prejudicada de exigir a execução específica das obrigações inadimplidas ou de rescindir o Contrato por justa causa, conforme as hipóteses previstas na Cláusula Décima Quarta.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido nas seguintes hipóteses:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento, acerto de contas e transferência de responsabilidades;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 60 (sessenta) dias, sem prejuízo do pagamento pelos Serviços já prestados e das obrigações assumidas até a data de rescisão;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais essenciais, após notificação prévia com prazo de 15 (quinze) dias para regularização, exceto nas hipóteses de descumprimento que, por sua natureza, tornem inviável a concessão de prazo;\nd) Por qualquer das Partes, de forma imediata, nos casos de falência, recuperação judicial ou extrajudicial, insolvência, dissolução ou liquidação da outra Parte;\ne) Por qualquer das Partes, de forma imediata, em caso de violação comprovada de obrigações de confidencialidade, proteção de dados, compliance ou anticorrupção.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada:\n\na) Os valores correspondentes aos Serviços já prestados e entregáveis aprovados até a data de rescisão, calculados proporcionalmente ao cronograma financeiro do Anexo II;\nb) Os custos comprovados, razoáveis e não reembolsados incorridos pela Contratada em razão do Contrato, mediante apresentação de documentação comprobatória;\nc) Multa rescisória equivalente a 15% (quinze por cento) do valor remanescente do Contrato.\n\n14.3. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional, multa rescisória ou reembolso de custos.\n\n14.4. Em caso de rescisão com justa causa pela Contratada, esta terá direito ao recebimento de todos os valores devidos pelos Serviços prestados até a data de rescisão, acrescidos de indenização pelos danos diretos e comprovadamente sofridos em razão do descumprimento da Contratante.\n\n14.5. Em qualquer hipótese de rescisão, a Contratada deverá: (i) concluir os Serviços em andamento que possam ser finalizados no prazo de aviso prévio; (ii) transferir para a Contratante ou para terceiro por ela indicado todos os materiais, documentos, códigos e informações relacionados aos Serviços; e (iii) cooperar com a transição para o novo prestador de serviços pelo prazo de até 30 (trinta) dias após a data de rescisão, mediante remuneração proporcional.\n\n14.6. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados, propriedade intelectual e responsabilidade por danos causados.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa), o Foreign Corrupt Practices Act (FCPA) e o UK Bribery Act, quando aplicáveis, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno, à lavagem de dinheiro e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas, para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas, ou para qualquer finalidade que contrarie a legislação vigente ou os princípios éticos corporativos.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas robustas de governança corporativa, compliance e integridade, incluindo: (i) programa de integridade estruturado; (ii) canal de denúncias acessível e independente; (iii) treinamentos regulares em ética e anticorrupção; e (iv) due diligence de terceiros aplicável.\n\n15.4. A Contratada declara que não emprega menores de 18 (dezoito) anos em trabalho noturno, perigoso ou insalubre, nem menores de 16 (dezesseis) anos em qualquer trabalho, salvo na condição de aprendiz, a partir de 14 (quatorze) anos, e que não utiliza trabalho análogo ao escravo ou em condições degradantes.\n\n15.5. A Contratante poderá realizar auditorias de compliance na Contratada, com aviso prévio de 10 (dez) dias úteis, para verificar o cumprimento das obrigações previstas nesta cláusula, devendo a Contratada cooperar plenamente e fornecer os documentos e informações solicitados.\n\n15.6. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis, da responsabilização pelos danos causados e da comunicação às autoridades competentes.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada somente poderá subcontratar partes dos Serviços a terceiros especializados mediante prévia autorização escrita e expressa da Contratante, que poderá condicioná-la à: (i) apresentação de informações detalhadas sobre o subcontratado, incluindo qualificação técnica, experiência comprovada e certidões de regularidade; (ii) realização de due diligence de compliance; e (iii) assinatura de instrumento de confidencialidade e proteção de dados pelo subcontratado.\n\n16.2. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos, omissões, falhas e descumprimentos dos subcontratados como se fossem seus próprios.\n\n16.3. A Contratante poderá, a seu critério, solicitar a substituição imediata de subcontratado que demonstre incapacidade técnica, irregularidade legal, descumprimento de SLA, violação de obrigações de confidencialidade ou proteção de dados, ou que não atenda aos padrões de qualidade e compliance exigidos, devendo a Contratada promover a substituição no prazo de [PRAZO] dias.\n\n16.4. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte, que poderá recusá-la com ou sem justificativa, exceto nos casos de reorganização societária da Parte cedente, hipótese em que a cessão será permitida desde que a cessionária assuma integralmente as obrigações contratuais e possua capacidade técnica equivalente.\n\n16.5. A subcontratação não autorizada constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e podendo ensejar a rescisão imediata do Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações, rejeições, solicitações e demais atos com efeitos jurídicos relacionados a este Contrato deverão ser realizados por escrito, por meio de: (i) carta com aviso de recebimento; (ii) e-mail com confirmação de leitura; ou (iii) plataforma de gestão de projetos ou de comunicação corporativa previamente acordada entre as Partes.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato e aos pontos focais indicados pelas Partes no Anexo IV deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual, com efeitos a partir do recebimento da notificação de atualização.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio, desde que não haja notificação de falha no envio ou de endereço inválido.\n\n17.4. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação, aplicação de penalidades e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável, com indicação expressa do objeto e dos efeitos do ato.\n\n17.5. Alterações no escopo, nos valores contratuais, nos prazos globais, nos SLAs ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo ineficazes quaisquer acordos verbais sobre tais matérias.\n\n17.6. As Partes comprometem-se a realizar reuniões periódicas de acompanhamento do contrato, na periodicidade e formato definidos no Anexo I, para revisão de desempenho, análise de SLAs, discussão de riscos e alinhamento de expectativas.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis e de igual hierarquia, os seguintes Anexos:\n\nAnexo I — Especificação Técnica dos Serviços: descrição detalhada do escopo, entregáveis, especificações técnicas, critérios de aceite, prazo de garantia e responsabilidades de cada Parte;\nAnexo II — Cronograma Financeiro: valores, condições e datas de pagamento por entregável ou marco;\nAnexo III — Dados Bancários da Contratada: informações para fins de pagamento;\nAnexo IV — Gestores do Contrato e Pontos Focais: dados de contato das Partes para fins de comunicação e gestão;\nAnexo V — Cronograma de Execução: marcos intermediários, datas de entrega de entregáveis e marcos de pagamento;\nAnexo VI — Acordo de Nível de Serviço (SLA): métricas de desempenho, metas, metodologia de medição, créditos de serviço e penalidades por descumprimento.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas, desde que não contrariem as disposições essenciais deste instrumento.\n\n18.3. Os Anexos I, V e VI somente poderão ser atualizados mediante aditamento contratual formal, assinado por representantes autorizados de ambas as Partes. Os demais Anexos poderão ser atualizados por comunicação escrita assinada pelos gestores do contrato, desde que tais atualizações não impliquem alteração de valores, prazos globais, SLAs ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações, propostas, cartas de intenção e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente vinculante para situações futuras ou modificação tácita das condições contratuais, devendo qualquer renúncia ser expressa e formalizada por escrito.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível por decisão judicial ou arbitral transitada em julgado, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original das Partes.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001, da Lei n.º 14.063/2020 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica e probatória.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo ineficazes quaisquer acordos verbais ou comunicações informais sobre matérias essenciais do Contrato.\n\n19.7. Este Contrato é regido pela legislação brasileira, em especial pelo Código Civil, pelo Código de Defesa do Consumidor, quando aplicável, pela Lei Anticorrupção, pela LGPD e pelas demais normas aplicáveis à sua natureza e objeto.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato, pelo prazo de 20 (vinte) dias corridos contados da notificação formal do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes comprometem-se a submeter a controvérsia à mediação, nos termos da Lei n.º 13.140/2015, perante câmara de mediação de reconhecida reputação, pelo prazo de 30 (trinta) dias, antes de recorrer ao Poder Judiciário ou à arbitragem.\n\n20.4. Não sendo resolvida a controvérsia por mediação, as Partes poderão, de comum acordo, submeter a questão à arbitragem, nos termos da Lei n.º 9.307/1996, perante câmara arbitral de reconhecida reputação, com sede em [CIDADE], aplicando-se o regulamento da câmara escolhida.\n\n20.5. Não havendo acordo quanto à arbitragem ou sendo esta inviável, qualquer das Partes poderá submeter a controvérsia ao foro eleito nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas, ou eletronicamente por meio de plataforma de assinatura digital certificada.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 1, NULL, '2026-04-15 19:55:23', '2026-04-15 19:55:23', NULL, NULL, NULL, NULL, NULL),
  (4, 'Contrato Estratégico de Prestação de Serviços com Proteção Reforçada da Contratante', 'Modelo contratual estratégico para contratações relevantes, com maior proteção da contratante e controles reforçados.', 'service', 'CONTRATO ESTRATÉGICO DE PRESTAÇÃO DE SERVIÇOS COM PROTEÇÃO REFORÇADA DA CONTRATANTE\n\nModelo Contratual — Nível de Rigidez: 4/5\nTipo: Prestação de Serviços Estratégicos\n\n---\n\nCONTRATO ESTRATÉGICO DE PRESTAÇÃO DE SERVIÇOS COM PROTEÇÃO REFORÇADA DA CONTRATANTE N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato Estratégico de Prestação de Serviços com Proteção Reforçada da Contratante ("Contrato"), que se regerá pelas cláusulas e condições seguintes, as quais as Partes declaram ter lido, compreendido, negociado e aceito integralmente, reconhecendo que o presente instrumento foi elaborado com o objetivo de assegurar a máxima proteção patrimonial, operacional e jurídica da Contratante:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratada").\n\nAs Partes, em conjunto, serão denominadas "Partes" e, individualmente, "Parte".\n\nCONSIDERANDO que a Contratante possui interesse estratégico na contratação dos Serviços objeto deste instrumento, em razão de sua relevância operacional e criticidade para a continuidade de seus negócios;\n\nCONSIDERANDO que a Contratada declara possuir toda a capacidade técnica, operacional, financeira, legal e regulatória necessária para a execução integral e tempestiva dos Serviços;\n\nCONSIDERANDO que as Partes reconhecem a importância de estabelecer mecanismos robustos de controle, monitoramento, responsabilização e proteção da Contratante;\n\nAs Partes celebram o presente instrumento nos termos e condições a seguir:\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços técnicos estratégicos especializados descritos no Anexo I — Especificação Técnica Detalhada dos Serviços ("Serviços"), a serem executados em conformidade estrita com o escopo fechado, os entregáveis vinculantes, os critérios formais de aceite, os Acordos de Nível de Serviço (SLA), a Matriz de Responsabilidades e o cronograma estabelecidos neste instrumento e em seus Anexos, que integram o presente Contrato para todos os fins de direito.\n\n1.2. Os Serviços objeto deste Contrato são de natureza estratégica e possuem relevância operacional crítica para a Contratante, razão pela qual o escopo é fechado, os entregáveis são vinculantes, os critérios de aceite são formalmente rigorosos e os mecanismos de controle, monitoramento e responsabilização são reforçados em relação aos contratos de menor criticidade.\n\n1.3. A Contratada declara, sob as penas da lei, que: (i) possui toda a capacidade técnica, operacional, financeira e legal necessária para a execução integral dos Serviços; (ii) não possui impedimento legal, regulatório ou contratual que inviabilize a execução; (iii) os profissionais designados possuem as qualificações, certificações e experiência comprovada exigidas no Anexo I; e (iv) manterá todas essas condições durante toda a vigência do Contrato, comunicando imediatamente qualquer alteração relevante.\n\n1.4. O escopo dos Serviços é estritamente delimitado pelo Anexo I e pela Matriz de Responsabilidades constante do Anexo VII. Quaisquer atividades não expressamente previstas nesses documentos não integram o escopo contratual e somente poderão ser executadas mediante aprovação formal escrita da Contratante e formalização de aditamento contratual, com definição prévia de escopo adicional, valor, prazo, entregáveis e critérios de aceite. A execução de atividades fora do escopo sem autorização prévia não gerará qualquer obrigação de pagamento para a Contratante e poderá ser considerada descumprimento contratual.\n\n1.5. A Contratada reconhece que a execução dos Serviços envolverá acesso a ativos estratégicos, sistemas críticos, dados sensíveis e informações confidenciais da Contratante, comprometendo-se a observar rigorosamente todos os protocolos de segurança, confidencialidade, proteção de dados e gestão de riscos estabelecidos neste instrumento, nos Anexos e nas políticas internas da Contratante que lhe forem comunicadas, as quais a Contratada declara ter recebido, lido e aceito.\n\n1.6. A Contratada não poderá alegar desconhecimento das condições operacionais, dos requisitos técnicos, das políticas de segurança, dos padrões de qualidade ou das especificações do Anexo I como justificativa para descumprimento de obrigações contratuais, tendo declarado, ao assinar este instrumento, que realizou toda a due diligence necessária para a correta precificação e execução dos Serviços.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO FECHADO, DOS ENTREGÁVEIS VINCULANTES, DOS CRITÉRIOS FORMAIS DE ACEITE E DO SLA\n\n2.1. O escopo técnico dos Serviços é fechado e vinculante, compreendendo exclusivamente as atividades, tarefas, entregáveis e responsabilidades descritas no Anexo I, com indicação expressa das especificações técnicas, dos padrões de qualidade aplicáveis, dos marcos de execução, dos critérios formais de aceite e da Matriz de Responsabilidades do Anexo VII.\n\n2.2. Cada entregável previsto no Anexo I é vinculante e deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado de: (i) documentação técnica completa e atualizada; (ii) relatório de testes ou validação com resultados detalhados; (iii) declaração formal de conformidade com as especificações, assinada pelo gestor técnico da Contratada; e (iv) checklist de critérios de aceite com indicação do status de cada item, observado o prazo de submissão estabelecido no cronograma do Anexo V.\n\n2.3. Os critérios formais de aceite de cada entregável são vinculantes e estão definidos no Anexo I, incluindo, sem limitação: conformidade técnica integral com as especificações, aderência plena aos padrões de qualidade estabelecidos, ausência de defeitos críticos, bloqueadores ou de alta severidade, cumprimento dos SLAs aplicáveis, aprovação nos testes de aceitação definidos e conformidade com os requisitos de segurança e proteção de dados estabelecidos.\n\n2.4. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento formal de cada entregável com sua documentação completa e checklist de aceite, para aprová-lo ou rejeitá-lo mediante comunicação escrita fundamentada, com indicação detalhada de cada critério de aceite não atendido, do grau de não conformidade e do impacto operacional identificado.\n\n2.5. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo improrrogável de [PRAZO] dias úteis para realizar as correções e ajustes necessários, sem ônus adicional para a Contratante, submetendo nova versão acompanhada de: (i) relatório detalhado de correções, com indicação de cada não conformidade sanada e da solução técnica adotada; (ii) nova declaração formal de conformidade; e (iii) novo checklist de critérios de aceite atualizado.\n\n2.6. A rejeição de entregável em segunda análise, por não conformidades já identificadas na primeira rejeição e não devidamente corrigidas, constituirá descumprimento contratual grave e imediato, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e conferindo à Contratante o direito de rescindir o Contrato por justa causa, sem necessidade de notificação prévia adicional.\n\n2.7. A rejeição de 3 (três) ou mais entregáveis em segunda análise, em qualquer momento da vigência do Contrato, conferirá à Contratante o direito de rescindir imediatamente o Contrato por justa causa, independentemente de notificação prévia, com direito à indenização integral pelos danos sofridos.\n\n2.8. Os Acordos de Nível de Serviço (SLA) aplicáveis a cada categoria de serviço são vinculantes e estão definidos no Anexo VI, incluindo: disponibilidade mínima dos sistemas ou serviços, tempo máximo de resposta a incidentes por severidade, tempo máximo de resolução por categoria, janelas de manutenção programada, métricas de desempenho operacional e indicadores-chave de qualidade (KQI).\n\n2.9. O descumprimento dos SLAs definidos no Anexo VI ensejará, cumulativamente: (i) aplicação automática de créditos de serviço conforme tabela do Anexo VI, deduzidos das faturas subsequentes sem necessidade de notificação; (ii) abertura de registro formal de não conformidade pela Contratante; e (iii) obrigação da Contratada de apresentar, no prazo de 48 (quarenta e oito) horas, análise de causa raiz e plano de ação corretiva com cronograma de implementação.\n\n2.10. O descumprimento reiterado de SLAs, definido como 3 (três) ou mais ocorrências no mesmo indicador em período de 90 (noventa) dias, constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades previstas na Cláusula Décima Terceira e conferindo à Contratante o direito de rescindir o Contrato por justa causa.\n\n2.11. A Contratada deverá disponibilizar à Contratante relatórios mensais de desempenho, no prazo de 5 (cinco) dias úteis após o encerramento de cada mês, com: (i) indicadores de SLA medidos no período e comparação com as metas; (ii) análise de causa raiz de todos os descumprimentos; (iii) plano de ação corretiva com responsáveis e prazos; (iv) tendências e riscos identificados; e (v) indicadores de qualidade dos entregáveis entregues no período.\n\n2.12. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos, defeitos latentes, não conformidades que se manifestem posteriormente ou falhas de segurança identificadas após a aprovação, dentro do prazo de garantia estabelecido no Anexo I, que não poderá ser inferior a 12 (doze) meses.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por períodos iguais e sucessivos mediante acordo escrito entre as Partes, formalizado com antecedência mínima de 90 (noventa) dias antes do término da vigência, condicionado à avaliação formal de desempenho da Contratada pela Contratante com resultado satisfatório.\n\n3.2. A prorrogação do Contrato estará condicionada ao cumprimento integral, pela Contratada, de todas as obrigações contratuais durante o período anterior, incluindo: (i) cumprimento dos SLAs com percentual mínimo de [PERCENTUAL]% de atingimento; (ii) ausência de penalidades aplicadas nos últimos 6 (seis) meses; (iii) regularidade fiscal, trabalhista e previdenciária; e (iv) avaliação de desempenho com nota mínima de [NOTA] na escala definida no Anexo I.\n\n3.3. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, condicionado ao cumprimento das condições precedentes estabelecidas no Anexo I, incluindo, sem limitação: apresentação de certidões de regularidade, comprovação de qualificação técnica dos profissionais designados, assinatura de termos de confidencialidade e proteção de dados pelos profissionais da Contratada que acessarão os sistemas e informações da Contratante, e aprovação dos planos de execução e de gestão de riscos.\n\n3.4. O cronograma detalhado de execução dos Serviços, com os marcos intermediários, as datas de entrega de cada entregável, os marcos de pagamento correspondentes e os pontos de controle obrigatórios, constará do Anexo V e será de cumprimento obrigatório por ambas as Partes.\n\n3.5. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com antecedência mínima de [PRAZO] dias antes da data prevista de entrega, acompanhados de: (i) justificativa técnica detalhada e documentada; (ii) análise de impacto no cronograma global e nos demais entregáveis; (iii) proposta de replanejamento com novo cronograma; e (iv) plano de ação para recuperação do atraso, para análise e aprovação formal da Contratante.\n\n3.6. A aprovação de replanejamento pela Contratante não constituirá renúncia ao direito de aplicar as penalidades cabíveis pelo atraso, não alterará os valores contratuais e não eximirá a Contratada de sua responsabilidade pelos danos decorrentes do atraso, salvo se expressamente previsto no instrumento de aprovação do replanejamento.\n\n3.7. Atrasos decorrentes exclusivamente de atos ou omissões documentados da Contratante, de caso fortuito ou de força maior, devidamente comunicados no prazo de 24 (vinte e quatro) horas após a ocorrência e comprovados documentalmente, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo formal entre as Partes, sem direito a acréscimo de valor contratual, salvo disposição expressa em contrário.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação integral dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$ [VALOR] ([VALOR POR EXTENSO]), conforme o cronograma financeiro detalhado no Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo V.\n\n4.2. O valor contratual é fixo, global e irreajustável durante o período inicial de vigência, ressalvadas exclusivamente as hipóteses de reajuste previstas na Cláusula Sexta, de alteração de escopo formalizada por aditamento contratual e de variação extraordinária de custos decorrente de fatos imprevisíveis, alheios à vontade das Partes e devidamente comprovados documentalmente.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui, sem exceção, todos os custos diretos e indiretos necessários à execução integral dos Serviços, incluindo: mão de obra especializada e encargos, tributos, licenças de software, ferramentas, deslocamentos, hospedagem, materiais, equipamentos, seguros obrigatórios, certificações, auditorias e quaisquer outras despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. A Contratada declara que o valor proposto foi estabelecido após análise completa do escopo, das especificações técnicas, dos SLAs, dos critérios de aceite e das condições contratuais, não podendo alegar, em nenhuma hipótese, desequilíbrio econômico-financeiro decorrente de má avaliação do escopo ou das condições de execução.\n\n4.5. Eventuais serviços adicionais somente serão executados após: (i) solicitação formal escrita da Contratante; (ii) apresentação de proposta detalhada pela Contratada com escopo, valor, prazo e entregáveis adicionais; (iii) aprovação formal escrita da Contratante; e (iv) formalização de aditamento contratual. A execução de serviços adicionais sem observância deste procedimento não gerará qualquer obrigação de pagamento para a Contratante.\n\n4.6. Os créditos de serviço decorrentes de descumprimento de SLA, conforme tabela do Anexo VI, serão deduzidos automaticamente dos valores das faturas subsequentes, sem necessidade de formalização adicional. A Contratada terá o prazo de 3 (três) dias úteis para contestar formalmente os créditos aplicados, com fundamentação técnica documentada, sob pena de aceitação tácita.\n\n4.7. A Contratante poderá reter até [PERCENTUAL]% do valor de cada parcela como garantia de cumprimento das obrigações contratuais, a ser liberado ao final do Contrato, após a comprovação do cumprimento integral de todas as obrigações, incluindo a entrega de toda a documentação técnica, a realização da transição de conhecimento e a ausência de pendências, reclamações ou litígios relacionados ao Contrato.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo V, mediante apresentação de nota fiscal ou fatura pela Contratada, acompanhada obrigatoriamente de: (i) relatório de execução do período com indicação do percentual de conclusão de cada entregável; (ii) certidões de regularidade fiscal federal, estadual, municipal, trabalhista (FGTS e INSS) atualizadas; (iii) comprovantes de recolhimento de encargos trabalhistas e previdenciários dos profissionais alocados; (iv) declaração de ausência de passivos trabalhistas relacionados ao Contrato; e (v) relatório de desempenho de SLA do período.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da nota fiscal com toda a documentação exigida no item 5.1. A ausência de qualquer documento suspenderá o prazo de pagamento até a regularização, sem que tal suspensão configure inadimplemento da Contratante.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada no Anexo III, sendo vedada a emissão de duplicatas, cheques, boletos bancários ou outros títulos de crédito sem prévia autorização escrita da Contratante. A Contratada não poderá protestar títulos relacionados a este Contrato sem prévia notificação à Contratante com antecedência mínima de 10 (dez) dias úteis.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso e atualização monetária pelo IPCA, desde que: (i) o atraso não decorra de contestação fundamentada de valores pela Contratante; (ii) a Contratada tenha cumprido integralmente todas as obrigações contratuais do período; e (iii) a nota fiscal tenha sido emitida em conformidade com as exigências deste instrumento.\n\n5.5. A Contratante poderá reter ou glosar, total ou parcialmente, o pagamento de qualquer parcela nas seguintes hipóteses, sem que tal retenção configure inadimplemento contratual: (i) entregável rejeitado ou em processo de revisão; (ii) SLA não cumprido no período, pelo valor dos créditos de serviço correspondentes; (iii) obrigações acessórias não atendidas, incluindo ausência de documentação exigida; (iv) existência de débitos da Contratada perante a Contratante; (v) irregularidade fiscal, trabalhista ou previdenciária da Contratada; ou (vi) indícios de irregularidade na execução dos Serviços, até a conclusão de apuração formal.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados e dos critérios aplicados. A ausência de contestação no prazo não constituirá renúncia ao direito de contestar vícios ocultos ou irregularidades identificadas posteriormente.\n\n5.7. A Contratada não poderá ceder, endossar, transferir, penhorar ou onerar os créditos decorrentes deste Contrato a terceiros sem prévia autorização escrita da Contratante, sob pena de nulidade do ato e de rescisão do Contrato por justa causa.\n\n5.8. A Contratante poderá compensar eventuais créditos que possua perante a Contratada, decorrentes de penalidades, créditos de SLA, retenções ou indenizações, com os valores devidos à Contratada, independentemente de autorização judicial, mediante comunicação escrita prévia.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo IBGE, ou por outro índice oficial que venha a substituí-lo, limitado ao teto de [PERCENTUAL]% ao ano.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 60 (sessenta) dias da data de sua aplicação, sendo aplicado mediante acordo formal entre as Partes, formalizado por aditamento contratual assinado por representantes autorizados de ambas as Partes.\n\n6.3. O reajuste somente será concedido se a Contratada demonstrar, mediante documentação comprobatória: (i) cumprimento integral dos SLAs no período anterior, com percentual de atingimento mínimo de [PERCENTUAL]%; (ii) ausência de penalidades aplicadas nos últimos 12 (doze) meses; e (iii) avaliação de desempenho satisfatória pela Contratante.\n\n6.4. Não haverá reajuste durante o período inicial de vigência do Contrato. Eventuais pedidos de revisão de valores por desequilíbrio econômico-financeiro somente serão analisados se a Contratada demonstrar, de forma inequívoca e documentada, a ocorrência de fato imprevisível, extraordinário e alheio à sua vontade que tenha impactado substancialmente os custos dos Serviços, nos termos do artigo 317 do Código Civil.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, de caráter vinculante e cujo descumprimento ensejará as sanções previstas neste instrumento:\n\na) Executar os Serviços com excelência técnica, máxima diligência, profissionalismo, observância das melhores práticas do mercado, das normas técnicas aplicáveis, das especificações do Anexo I e dos critérios formais de aceite estabelecidos, garantindo a qualidade, a conformidade e a segurança dos entregáveis;\n\nb) Cumprir rigorosamente o cronograma de execução, as datas de entrega dos entregáveis e os SLAs definidos no Anexo VI, comunicando proativamente à Contratante, com a antecedência estabelecida neste instrumento, qualquer risco de descumprimento identificado;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação técnica exigidas para a execução dos Serviços, incluindo registros profissionais, certificações, licenças, certidões e seguros aplicáveis, apresentando comprovação à Contratante sempre que solicitado e, independentemente de solicitação, na periodicidade definida no Anexo I;\n\nd) Designar profissional sênior qualificado como gestor técnico do contrato, com poderes para tomar decisões operacionais, coordenar a equipe de execução e ser o ponto focal de comunicação com a Contratante, cuja substituição deverá ser comunicada com antecedência mínima de [PRAZO] dias e estará condicionada à aprovação prévia da Contratante;\n\ne) Manter equipe técnica qualificada, certificada e em número suficiente para a execução dos Serviços dentro dos prazos e padrões de qualidade estabelecidos, comunicando à Contratante qualquer substituição de profissional-chave com antecedência mínima de [PRAZO] dias, acompanhada do currículo do substituto para aprovação prévia da Contratante;\n\nf) Comunicar à Contratante, no prazo máximo de 2 (duas) horas após a identificação, qualquer ocorrência, incidente, falha, vulnerabilidade de segurança ou evento que possa comprometer a execução regular dos Serviços, o cumprimento do cronograma, o atendimento dos SLAs ou a segurança dos sistemas e dados da Contratante;\n\ng) Cumprir integralmente a legislação trabalhista, previdenciária, fiscal, ambiental, de segurança do trabalho, de proteção de dados e de compliance aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos e por seus reflexos sobre a Contratante, incluindo custos de defesa, multas e indenizações;\n\nh) Guardar sigilo absoluto sobre todas as informações confidenciais e estratégicas da Contratante a que tiver acesso em razão da execução deste Contrato, nos termos da Cláusula Nona, fazendo com que todos os seus profissionais e subcontratados assinem termos individuais de confidencialidade antes de qualquer acesso a informações ou sistemas da Contratante;\n\ni) Reparar, no prazo estabelecido na Cláusula Segunda, eventuais falhas, inadequações, não conformidades, defeitos ou vulnerabilidades de segurança nos Serviços prestados ou nos entregáveis entregues, sem ônus adicional para a Contratante, incluindo durante o período de garantia;\n\nj) Apresentar à Contratante, na periodicidade estabelecida no Anexo I, relatórios de progresso, de desempenho de SLA, de gestão de riscos e de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável, dos indicadores de qualidade, dos riscos identificados e das ações corretivas em andamento;\n\nk) Adotar, em suas operações, práticas robustas de governança corporativa, compliance, gestão de riscos e segurança da informação compatíveis com os padrões exigidos pela Contratante e com a legislação aplicável, submetendo-se às auditorias previstas neste instrumento;\n\nl) Participar de reuniões de acompanhamento, revisão de desempenho, comitês de gestão do contrato e reuniões de gestão de riscos na periodicidade e formato definidos no Anexo I, com participação obrigatória do gestor técnico do contrato;\n\nm) Manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato, apresentando apólice à Contratante antes do início dos Serviços e sempre que renovada;\n\nn) Elaborar e manter atualizado, durante toda a vigência do Contrato, plano de continuidade de negócios e plano de recuperação de desastres para os Serviços prestados, submetendo-os à aprovação da Contratante e realizando testes periódicos conforme definido no Anexo I;\n\no) Realizar a transição de conhecimento ao final do Contrato, conforme plano definido no Anexo I, garantindo a continuidade operacional da Contratante e a transferência integral de todos os ativos, documentos, códigos, configurações e informações relacionados aos Serviços.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato, observadas as condições de aprovação de entregáveis, de apresentação de documentação fiscal completa e de cumprimento das obrigações contratuais pela Contratada;\n\nb) Fornecer à Contratada, em tempo hábil e de forma completa, todas as informações, documentos, especificações, acessos, credenciais e recursos necessários à execução dos Serviços, conforme especificado no Anexo I e na Matriz de Responsabilidades do Anexo VII;\n\nc) Designar gestor técnico do contrato com poderes para aprovar entregáveis, emitir ordens de serviço, autorizar alterações de escopo, aplicar penalidades e tomar decisões operacionais no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada e referência expressa a cada critério de aceite não atendido em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável e não inferior a [PRAZO] dias, eventuais alterações em seus processos internos, requisitos técnicos, sistemas, políticas de segurança ou condições operacionais que possam impactar a execução dos Serviços ou o cumprimento dos SLAs;\n\nf) Disponibilizar infraestrutura, equipamentos, sistemas e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante, nos prazos estabelecidos no cronograma;\n\ng) Participar das reuniões de acompanhamento, revisão de desempenho, comitês de gestão do contrato e reuniões de gestão de riscos na periodicidade e formato definidos no Anexo I;\n\nh) Notificar a Contratada, de forma tempestiva e fundamentada, sobre qualquer descumprimento de obrigação contratual ou de SLA, antes de aplicar as penalidades previstas neste instrumento, exceto nas hipóteses em que a natureza do descumprimento torne desnecessária ou inviável a notificação prévia.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais e estratégicas a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos, de propriedade intelectual, de clientes, de colaboradores, de fornecedores e de parceiros da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços, assessores jurídicos ou técnicos que: (i) necessitem conhecê-las para os fins deste Contrato; (ii) sejam previamente informados da natureza confidencial das informações; (iii) assinem individualmente termos de confidencialidade com obrigações equivalentes às previstas neste instrumento; e (iv) sejam expressamente autorizados pela Parte titular das informações.\n\n9.3. Cada Parte deverá adotar medidas técnicas e organizacionais robustas, proporcionais aos riscos envolvidos e compatíveis com os padrões de segurança da informação mais atuais, para proteger as Informações Confidenciais da outra Parte contra acesso não autorizado, divulgação indevida, perda, destruição ou qualquer forma de uso inadequado.\n\n9.4. A Contratada deverá: (i) implementar controles de acesso baseados no princípio do menor privilégio; (ii) manter registros de auditoria (logs) de todos os acessos a informações e sistemas da Contratante; (iii) criptografar as Informações Confidenciais em trânsito e em repouso; e (iv) realizar auditorias periódicas de segurança conforme definido no Anexo I.\n\n9.5. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que sejam ou se tornem de domínio público por meios lícitos, que já fossem de conhecimento comprovado e documentado da Parte receptora antes da celebração deste instrumento, que sejam desenvolvidas de forma independente e documentada pela Parte receptora, que sejam recebidas de terceiros de forma lícita e sem restrição, ou que devam ser divulgadas por força de lei ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível e buscar proteção das informações divulgadas.\n\n9.6. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 7 (sete) anos após o término ou rescisão deste Contrato, sendo que as informações que constituam segredo de negócio ou dados estratégicos permanecerão protegidas pelo prazo legal aplicável, sem limitação temporal.\n\n9.7. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará: (i) rescisão imediata do Contrato por justa causa; (ii) responsabilização pelos danos diretos e indiretos causados, incluindo lucros cessantes, danos reputacionais e custos de contenção; e (iii) adoção de medidas cautelares e inibitórias pela Contratante, independentemente de notificação prévia.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (LGPD), o GDPR quando aplicável, e demais normas nacionais e internacionais aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato, adotando uma abordagem de privacy by design e privacy by default em todas as atividades de tratamento de dados.\n\n10.2. A Contratada atuará na qualidade de operadora de dados, processando dados pessoais exclusivamente para as finalidades previstas neste Contrato, de acordo com as instruções documentadas e expressas da Contratante, vedado qualquer tratamento para finalidades próprias ou de terceiros, incluindo análise, comercialização, compartilhamento ou uso para treinamento de modelos de inteligência artificial.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais de segurança de nível elevado, incluindo, sem limitação: criptografia de dados em trânsito e em repouso com algoritmos aprovados pela Contratante, controles de acesso baseados em perfil e no princípio do menor privilégio, autenticação multifator para acesso a sistemas com dados pessoais, registros de auditoria completos e imutáveis, planos de resposta a incidentes testados periodicamente, e treinamento regular e documentado de toda a equipe em proteção de dados.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 2 (duas) horas após tomar ciência do ocorrido, fornecendo relatório preliminar com as informações disponíveis, seguido de relatório completo no prazo de 24 (vinte e quatro) horas, contendo: natureza e extensão do incidente, categorias e volume de dados afetados, possível impacto sobre os titulares, medidas adotadas e a adotar para mitigar os efeitos, e identificação dos responsáveis pela resposta ao incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, no prazo de 5 (cinco) dias úteis e conforme instrução documentada da Contratante, devolver ou eliminar de forma segura, certificada e irreversível todos os dados pessoais tratados em razão deste instrumento, fornecendo certificado técnico de eliminação assinado por profissional qualificado, salvo obrigação legal de retenção, hipótese em que deverá informar à Contratante os dados retidos, o fundamento legal e o prazo de retenção aplicável.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita da Contratante, devendo garantir contratualmente que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento, respondendo solidariamente por eventuais violações.\n\n10.7. A Contratada designará encarregado de proteção de dados (DPO) dedicado para as atividades desenvolvidas no âmbito deste Contrato, cujos dados de contato deverão constar do Anexo IV, e que deverá estar disponível para comunicação com a Contratante em prazo não superior a 4 (quatro) horas em casos de incidentes.\n\n10.8. A Contratada submeter-se-á a auditorias de proteção de dados realizadas pela Contratante ou por terceiro por ela designado, com aviso prévio de 5 (cinco) dias úteis, devendo cooperar plenamente e fornecer todos os documentos, registros e informações solicitados.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos, códigos, algoritmos, metodologias, materiais, dados e demais criações intelectuais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva e plena da Contratante, que poderá utilizá-los livremente, sem qualquer restrição, ônus adicional, necessidade de autorização ou pagamento de royalties à Contratada.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável, universal, exclusiva e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo todos os direitos de exploração previstos na legislação de propriedade intelectual aplicável, em todos os territórios e por todo o prazo de proteção legal.\n\n11.3. A Contratada declara, sob as penas da lei, que os Serviços prestados, os entregáveis entregues e os materiais produzidos não violam direitos de propriedade intelectual, direitos autorais, patentes, marcas, segredos de negócio ou quaisquer outros direitos de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas, notificações ou ações judiciais nesse sentido, incluindo os custos razoáveis de defesa da Contratante, honorários advocatícios e eventuais condenações.\n\n11.4. A Contratada deverá, ao final do Contrato e quando solicitado durante sua vigência, entregar à Contratante todos os arquivos, documentos, códigos-fonte, scripts, configurações, dados, credenciais e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica completa, atualizada e suficiente para a operação e manutenção independente pela Contratante ou por terceiro por ela designado.\n\n11.5. A Contratada não poderá utilizar o nome, a marca, o logotipo, os dados, os resultados ou qualquer outro elemento relacionado à Contratante em materiais de marketing, portfólio, publicações, apresentações ou comunicações externas sem prévia autorização escrita da Contratante.\n\n11.6. A Contratada não poderá utilizar os dados, informações, metodologias ou resultados obtidos no âmbito deste Contrato para desenvolver produtos, serviços ou soluções para terceiros, ou para treinar modelos de inteligência artificial, sem prévia autorização escrita da Contratante.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. A Contratada é integralmente responsável pela qualidade técnica, pela conformidade, pela segurança e pelo desempenho dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos, não conformidades, falhas de desempenho e vulnerabilidades de segurança identificados durante a execução do Contrato e dentro do prazo de garantia estabelecido no Anexo I.\n\n12.2. A Contratada será responsável pelos danos diretos e indiretos causados à Contratante em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato, incluindo lucros cessantes, danos emergentes, danos reputacionais, custos de substituição de fornecedor e custos de remediação de incidentes de segurança.\n\n12.3. A Contratada será responsável pelos danos causados a terceiros em decorrência da execução dos Serviços, devendo manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato.\n\n12.4. A limitação de responsabilidade prevista em contratos de menor criticidade não se aplica ao presente instrumento. A responsabilidade total da Contratada perante a Contratante ficará limitada ao dobro do valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados, propriedade intelectual ou responsabilidade perante terceiros, hipóteses em que a responsabilidade será ilimitada.\n\n12.5. A Contratada indenizará e manterá a Contratante indene de quaisquer reclamações, demandas, ações judiciais, custos, despesas e condenações decorrentes de: (i) descumprimento de obrigações trabalhistas, previdenciárias, fiscais ou regulatórias da Contratada; (ii) violação de direitos de propriedade intelectual de terceiros; (iii) incidentes de segurança ou violações de proteção de dados causados pela Contratada; e (iv) danos causados a terceiros em razão da execução dos Serviços.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previsto no cronograma do Anexo V sujeitará a Contratada ao pagamento de multa moratória de 1% (um por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 20% (vinte por cento) do valor total do Contrato.\n\n13.2. O descumprimento dos SLAs definidos no Anexo VI, além dos créditos de serviço previstos no mesmo Anexo, ensejará a aplicação de multa adicional de até 10% (dez por cento) do valor mensal do Contrato, proporcional ao grau de descumprimento e ao impacto operacional causado à Contratante.\n\n13.3. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 20% (vinte por cento) do valor total do Contrato, sem prejuízo do direito à reparação integral dos danos comprovadamente sofridos.\n\n13.4. A violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual sujeitará a Contratada ao pagamento de multa específica de R$ [VALOR] por ocorrência, sem prejuízo da responsabilidade pelos danos causados, da rescisão imediata do Contrato por justa causa e das medidas legais cabíveis.\n\n13.5. O descumprimento de obrigações de compliance, ética e anticorrupção sujeitará a Contratada ao pagamento de multa de 30% (trinta por cento) do valor total do Contrato, sem prejuízo da rescisão imediata por justa causa e das demais sanções legais aplicáveis.\n\n13.6. As penalidades previstas nesta cláusula são cumulativas entre si e com a obrigação de reparação integral dos danos, podendo ser aplicadas simultaneamente quando o mesmo fato ensejar a incidência de mais de uma penalidade.\n\n13.7. Os valores das multas serão descontados dos pagamentos devidos à Contratada, cobrados judicialmente ou deduzidos de garantias contratuais eventualmente prestadas, a critério exclusivo da Contratante.\n\n13.8. Não serão aplicadas penalidades nos casos em que o descumprimento decorra exclusivamente de caso fortuito, força maior ou atos atribuíveis exclusivamente à própria Contratante, devidamente comunicados no prazo de 2 (duas) horas após a ocorrência e comprovados documentalmente.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido nas seguintes hipóteses:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento, acerto de contas, transição de conhecimento e transferência de responsabilidades;\n\nb) Pela Contratante, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 90 (noventa) dias, sem prejuízo do pagamento pelos Serviços já prestados e aprovados, dos custos comprovados de desmobilização e de multa rescisória de 10% (dez por cento) do valor remanescente do Contrato;\n\nc) Pela Contratada, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 120 (cento e vinte) dias, sem prejuízo do pagamento de multa rescisória de 20% (vinte por cento) do valor remanescente do Contrato e da obrigação de garantir a continuidade dos Serviços durante o período de aviso prévio;\n\nd) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais essenciais, após notificação prévia com prazo de 10 (dez) dias para regularização, exceto nas hipóteses de descumprimento que, por sua natureza, tornem inviável ou desnecessária a concessão de prazo;\n\ne) Pela Contratante, de forma imediata, nos casos de: (i) falência, recuperação judicial ou extrajudicial, insolvência, dissolução ou liquidação da Contratada; (ii) violação comprovada de obrigações de confidencialidade, proteção de dados, compliance ou anticorrupção; (iii) rejeição de 3 (três) ou mais entregáveis em segunda análise; (iv) descumprimento reiterado de SLAs conforme definido na Cláusula Segunda; ou (v) qualquer ato que comprometa a segurança dos sistemas, dados ou operações da Contratante.\n\n14.2. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional, multa rescisória ou reembolso de custos, devendo ainda pagar à Contratante a multa compensatória prevista na Cláusula Décima Terceira e indenizar os danos causados.\n\n14.3. Em qualquer hipótese de rescisão, a Contratada deverá: (i) continuar prestando os Serviços durante o período de transição, de até 90 (noventa) dias, mediante remuneração proporcional; (ii) transferir para a Contratante ou para terceiro por ela indicado todos os materiais, documentos, códigos, dados, credenciais e informações relacionados aos Serviços; (iii) cooperar plenamente com o processo de transição; e (iv) garantir a continuidade operacional da Contratante durante todo o período de transição.\n\n14.4. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados, propriedade intelectual, garantia e responsabilidade por danos causados.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992, o FCPA, o UK Bribery Act, quando aplicáveis, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno, à lavagem de dinheiro e a práticas ilícitas.\n\n15.2. A Contratada declara possuir programa de integridade estruturado, com: (i) código de conduta e ética; (ii) canal de denúncias independente e acessível; (iii) treinamentos regulares e documentados em ética e anticorrupção; (iv) due diligence de terceiros; (v) controles internos adequados; e (vi) mecanismos de monitoramento e auditoria, comprometendo-se a mantê-lo durante toda a vigência do Contrato e a apresentar evidências à Contratante quando solicitado.\n\n15.3. A Contratante poderá realizar auditorias de compliance na Contratada, com aviso prévio de 5 (cinco) dias úteis, para verificar o cumprimento das obrigações previstas nesta cláusula, devendo a Contratada cooperar plenamente, fornecer os documentos e informações solicitados e permitir o acesso às suas instalações e sistemas.\n\n15.4. A Contratada deverá comunicar à Contratante, no prazo de 24 (vinte e quatro) horas, qualquer investigação, processo administrativo ou judicial relacionado a práticas de corrupção, suborno, lavagem de dinheiro ou outras irregularidades que possam impactar a execução deste Contrato ou a reputação da Contratante.\n\n15.5. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem necessidade de notificação prévia, sem direito a qualquer indenização pela Contratada, e com obrigação de pagamento da multa máxima prevista na Cláusula Décima Terceira, além da comunicação às autoridades competentes.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A subcontratação de qualquer parte dos Serviços é expressamente vedada sem prévia autorização escrita e expressa da Contratante, que poderá recusá-la sem necessidade de justificativa. A autorização, quando concedida, será específica para o subcontratado e para a atividade indicada, não podendo ser estendida a outros subcontratados ou atividades sem nova autorização.\n\n16.2. Para obter autorização de subcontratação, a Contratada deverá apresentar à Contratante, com antecedência mínima de 30 (trinta) dias: (i) identificação completa do subcontratado; (ii) qualificação técnica e experiência comprovada; (iii) certidões de regularidade fiscal, trabalhista e previdenciária; (iv) relatório de due diligence de compliance; (v) minuta do contrato de subcontratação; e (vi) declaração de que o subcontratado assinou termo de confidencialidade e proteção de dados.\n\n16.3. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos, omissões, falhas, descumprimentos e danos dos subcontratados como se fossem seus próprios.\n\n16.4. A Contratante poderá, a seu critério e sem necessidade de justificativa, solicitar a substituição imediata de subcontratado, devendo a Contratada promover a substituição no prazo de 5 (cinco) dias úteis, sem interrupção dos Serviços e sem ônus adicional para a Contratante.\n\n16.5. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato é expressamente vedada sem consentimento prévio e escrito da outra Parte, que poderá recusá-la sem necessidade de justificativa, exceto nos casos de reorganização societária, hipótese em que a cessão será condicionada à assunção integral das obrigações contratuais pela cessionária e à comprovação de capacidade técnica equivalente.\n\n16.6. A subcontratação não autorizada constituirá descumprimento contratual grave e imediato, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e conferindo à Contratante o direito de rescindir imediatamente o Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações, rejeições, solicitações e demais atos com efeitos jurídicos relacionados a este Contrato deverão ser realizados por escrito, por meio de: (i) carta com aviso de recebimento; (ii) e-mail com confirmação de leitura; ou (iii) plataforma de gestão de contratos previamente acordada entre as Partes, com registro de auditoria.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato e aos pontos focais indicados pelas Partes no Anexo IV, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual, com efeitos a partir do recebimento da notificação de atualização.\n\n17.3. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação, aplicação de penalidades, retenções de pagamento e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável, com indicação expressa do objeto e dos efeitos do ato.\n\n17.4. Alterações no escopo, nos valores contratuais, nos prazos globais, nos SLAs ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo absolutamente ineficazes quaisquer acordos verbais, e-mails informais ou comunicações não formalizadas sobre tais matérias.\n\n17.5. As Partes comprometem-se a realizar reuniões periódicas de acompanhamento do contrato, na periodicidade e formato definidos no Anexo I, com registro em ata assinada pelos gestores do contrato de ambas as Partes, que integrará o histórico documental do Contrato.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis e de igual hierarquia, os seguintes Anexos:\n\nAnexo I — Especificação Técnica Detalhada dos Serviços: descrição fechada do escopo, entregáveis vinculantes, especificações técnicas, critérios formais de aceite, prazo de garantia, requisitos de segurança e responsabilidades de cada Parte;\nAnexo II — Cronograma Financeiro: valores, condições e datas de pagamento por entregável ou marco, incluindo retenção de garantia;\nAnexo III — Dados Bancários da Contratada: informações para fins de pagamento;\nAnexo IV — Gestores do Contrato e Pontos Focais: dados de contato das Partes para fins de comunicação, gestão e resposta a incidentes;\nAnexo V — Cronograma de Execução: marcos intermediários, datas de entrega de entregáveis, marcos de pagamento e pontos de controle obrigatórios;\nAnexo VI — Acordo de Nível de Serviço (SLA): métricas de desempenho, metas, metodologia de medição, créditos de serviço e penalidades por descumprimento;\nAnexo VII — Matriz de Responsabilidades: definição detalhada das responsabilidades de cada Parte para cada atividade, entregável e marco do Contrato.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas, desde que não contrariem as disposições essenciais deste instrumento.\n\n18.3. Os Anexos I, V, VI e VII somente poderão ser atualizados mediante aditamento contratual formal, assinado por representantes autorizados de ambas as Partes. Os demais Anexos poderão ser atualizados por comunicação escrita assinada pelos gestores do contrato, desde que tais atualizações não impliquem alteração de valores, prazos globais, SLAs, escopo ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações, propostas, cartas de intenção e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente vinculante para situações futuras ou modificação tácita das condições contratuais, devendo qualquer renúncia ser expressa, específica e formalizada por escrito.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original das Partes e o nível de proteção estabelecido neste instrumento.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001, da Lei n.º 14.063/2020 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica e probatória.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo absolutamente ineficazes quaisquer acordos verbais ou comunicações informais sobre matérias essenciais do Contrato.\n\n19.7. Este Contrato é regido pela legislação brasileira, em especial pelo Código Civil, pela Lei Anticorrupção, pela LGPD e pelas demais normas aplicáveis à sua natureza e objeto.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato, pelo prazo de 15 (quinze) dias corridos contados da notificação formal do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes comprometem-se a submeter a controvérsia à mediação, nos termos da Lei n.º 13.140/2015, perante câmara de mediação de reconhecida reputação, pelo prazo de 30 (trinta) dias, antes de recorrer ao Poder Judiciário ou à arbitragem.\n\n20.4. Não sendo resolvida a controvérsia por mediação, as Partes poderão, de comum acordo, submeter a questão à arbitragem, nos termos da Lei n.º 9.307/1996, perante câmara arbitral de reconhecida reputação, com sede em [CIDADE], aplicando-se o regulamento da câmara escolhida.\n\n20.5. Não havendo acordo quanto à arbitragem ou sendo esta inviável, qualquer das Partes poderá submeter a controvérsia ao foro eleito nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas, ou eletronicamente por meio de plataforma de assinatura digital certificada.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 1, NULL, '2026-04-15 20:02:10', '2026-04-15 20:02:10', NULL, NULL, NULL, NULL, NULL),
  (5, 'Contrato Blindado de Prestação de Serviços Críticos e Sensíveis', 'Modelo contratual de máxima rigidez para serviços críticos, sensíveis e de alto impacto jurídico-operacional.', 'service', 'CONTRATO BLINDADO DE PRESTAÇÃO DE SERVIÇOS CRÍTICOS E SENSÍVEIS\n\nModelo Contratual — Nível de Rigidez: 5/5\nTipo: Prestação de Serviços Críticos e Sensíveis\n\n---\n\nCONTRATO BLINDADO DE PRESTAÇÃO DE SERVIÇOS CRÍTICOS E SENSÍVEIS N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato Blindado de Prestação de Serviços Críticos e Sensíveis ("Contrato"), que se regerá pelas cláusulas e condições seguintes, as quais as Partes declaram ter lido, compreendido, negociado individualmente e aceito integralmente, reconhecendo que o presente instrumento foi elaborado para assegurar o mais elevado nível de proteção patrimonial, operacional, reputacional e jurídica da Contratante, em razão da criticidade máxima, da sensibilidade estratégica e do alto impacto operacional dos Serviços objeto deste instrumento:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratada").\n\nAs Partes, em conjunto, serão denominadas "Partes" e, individualmente, "Parte".\n\nCONSIDERANDO que os Serviços objeto deste Contrato são de natureza crítica, sensível e de alto impacto operacional, reputacional e jurídico para a Contratante, exigindo o mais elevado nível de controle, monitoramento, responsabilização e proteção;\n\nCONSIDERANDO que a Contratada declara possuir toda a capacidade técnica, operacional, financeira, legal, regulatória e de compliance necessária para a execução integral, tempestiva e segura dos Serviços, tendo realizado due diligence completa sobre o escopo, as condições e os riscos envolvidos;\n\nCONSIDERANDO que as Partes reconhecem a necessidade de estabelecer mecanismos de governança, controle, auditoria, responsabilização e proteção da Contratante em nível máximo, compatível com a criticidade dos Serviços;\n\nCONSIDERANDO que a Contratada prestou garantia contratual na forma estabelecida neste instrumento, como condição essencial para a celebração deste Contrato;\n\nAs Partes celebram o presente instrumento nos termos e condições a seguir:\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços técnicos críticos e sensíveis especializados descritos no Anexo I — Especificação Técnica Fechada e Vinculante dos Serviços ("Serviços"), a serem executados em conformidade estrita e integral com o escopo fechado, os entregáveis vinculantes, os critérios formais e rigorosos de aceite, os Acordos de Nível de Serviço (SLA) de máxima exigência, a Matriz de Responsabilidades, o Plano de Continuidade de Negócios e o cronograma estabelecidos neste instrumento e em seus Anexos, que integram o presente Contrato para todos os fins de direito como partes indissociáveis e de igual hierarquia.\n\n1.2. Os Serviços objeto deste Contrato são de natureza crítica e sensível, com impacto operacional máximo sobre as atividades da Contratante, razão pela qual: (i) o escopo é fechado, vinculante e não passível de interpretação extensiva; (ii) os entregáveis são vinculantes e sujeitos a critérios formais rigorosos de aceite; (iii) os mecanismos de controle, monitoramento, auditoria e responsabilização são os mais elevados previstos na biblioteca contratual da Contratante; e (iv) qualquer descumprimento, ainda que parcial, de obrigação contratual essencial poderá ensejar rescisão imediata por justa causa, sem necessidade de notificação prévia adicional.\n\n1.3. A Contratada declara, sob as penas da lei e com plena consciência das consequências jurídicas, que: (i) possui toda a capacidade técnica, operacional, financeira, legal, regulatória e de compliance necessária para a execução integral, tempestiva e segura dos Serviços; (ii) não possui impedimento legal, regulatório, contratual, judicial ou administrativo que inviabilize ou restrinja a execução; (iii) os profissionais designados possuem as qualificações, certificações, habilitações e experiência comprovada exigidas no Anexo I, com registro nos órgãos profissionais competentes; (iv) manterá todas essas condições durante toda a vigência do Contrato, comunicando imediatamente qualquer alteração relevante; e (v) realizou due diligence completa sobre o escopo, as especificações técnicas, os SLAs, os critérios de aceite, as condições operacionais e os riscos envolvidos, não podendo alegar desconhecimento de qualquer condição contratual.\n\n1.4. O escopo dos Serviços é estritamente delimitado pelo Anexo I e pela Matriz de Responsabilidades constante do Anexo VIII. Quaisquer atividades não expressamente previstas nesses documentos não integram o escopo contratual e somente poderão ser executadas mediante: (i) solicitação formal escrita da Contratante; (ii) aprovação formal escrita da Contratante; e (iii) formalização de aditamento contratual com definição prévia e vinculante de escopo adicional, valor, prazo, entregáveis, critérios de aceite e SLAs aplicáveis. A execução de atividades fora do escopo sem observância deste procedimento não gerará qualquer obrigação de pagamento para a Contratante, constituirá descumprimento contratual grave e poderá ensejar rescisão imediata por justa causa.\n\n1.5. A Contratada reconhece que a execução dos Serviços envolverá acesso a ativos estratégicos críticos, sistemas de missão crítica, dados altamente sensíveis, informações confidenciais de máximo sigilo e processos operacionais essenciais da Contratante, comprometendo-se a observar rigorosamente todos os protocolos de segurança, confidencialidade, proteção de dados, gestão de riscos e planos de continuidade estabelecidos neste instrumento, nos Anexos e nas políticas internas da Contratante que lhe forem comunicadas, as quais a Contratada declara ter recebido, lido, compreendido e aceito integralmente.\n\n1.6. Como condição essencial e inafastável para a celebração e vigência deste Contrato, a Contratada deverá prestar, antes do início dos Serviços, garantia contratual na modalidade de [MODALIDADE: garantia bancária / seguro-garantia / caução em dinheiro], no valor correspondente a [PERCENTUAL]% do valor total do Contrato, conforme especificado no Anexo IX, que deverá ser mantida durante toda a vigência do Contrato e pelo prazo de 12 (doze) meses após o seu término, para cobertura de eventuais obrigações remanescentes.\n\n1.7. A não prestação da garantia contratual no prazo estabelecido no item 1.6 impedirá o início dos Serviços, não gerará qualquer obrigação de pagamento para a Contratante e poderá ensejar a rescisão deste instrumento por justa causa, com aplicação das penalidades máximas previstas na Cláusula Décima Terceira.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO FECHADO, DOS ENTREGÁVEIS VINCULANTES, DOS CRITÉRIOS FORMAIS DE ACEITE, DO SLA E DO PLANO DE CONTINUIDADE\n\n2.1. O escopo técnico dos Serviços é fechado, vinculante e não passível de interpretação extensiva, compreendendo exclusivamente as atividades, tarefas, entregáveis e responsabilidades descritas no Anexo I, com indicação expressa das especificações técnicas, dos padrões de qualidade e segurança aplicáveis, dos marcos de execução, dos critérios formais de aceite, da Matriz de Responsabilidades do Anexo VIII e do Plano de Continuidade de Negócios do Anexo X.\n\n2.2. Cada entregável previsto no Anexo I é vinculante e deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado obrigatoriamente de: (i) documentação técnica completa, atualizada e auditável; (ii) relatório de testes ou validação com resultados detalhados, evidências documentadas e assinatura do responsável técnico; (iii) declaração formal de conformidade com as especificações, assinada pelo gestor técnico sênior da Contratada e pelo responsável de qualidade; (iv) checklist de critérios de aceite com indicação do status de cada item e evidências de atendimento; (v) relatório de análise de riscos e vulnerabilidades de segurança; e (vi) declaração de conformidade com a LGPD e demais normas de proteção de dados aplicáveis, observado o prazo de submissão estabelecido no cronograma do Anexo VI.\n\n2.3. Os critérios formais de aceite de cada entregável são vinculantes, rigorosos e estão definidos no Anexo I, incluindo, sem limitação: conformidade técnica integral com as especificações, aderência plena e documentada aos padrões de qualidade e segurança estabelecidos, ausência de defeitos críticos, bloqueadores, de alta severidade ou de impacto à segurança, cumprimento integral dos SLAs aplicáveis, aprovação nos testes de aceitação e nos testes de segurança definidos, conformidade com os requisitos de proteção de dados e conformidade com o Plano de Continuidade de Negócios.\n\n2.4. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento formal de cada entregável com sua documentação completa, para aprová-lo ou rejeitá-lo mediante comunicação escrita fundamentada, com indicação detalhada de cada critério de aceite não atendido, do grau de não conformidade, do impacto operacional e de segurança identificado e da documentação de evidência correspondente.\n\n2.5. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo improrrogável de [PRAZO] dias úteis para realizar as correções e ajustes necessários, sem ônus adicional para a Contratante, submetendo nova versão acompanhada de: (i) relatório detalhado de correções, com indicação de cada não conformidade sanada, da solução técnica adotada e das evidências de correção; (ii) nova declaração formal de conformidade assinada pelo gestor técnico sênior e pelo responsável de qualidade; (iii) novo checklist de critérios de aceite atualizado com evidências; e (iv) relatório de reteste completo.\n\n2.6. A rejeição de entregável em segunda análise, por não conformidades já identificadas na primeira rejeição e não devidamente corrigidas, constituirá descumprimento contratual grave e imediato, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e conferindo à Contratante o direito de rescindir o Contrato imediatamente por justa causa, com execução integral da garantia contratual, sem necessidade de notificação prévia adicional.\n\n2.7. A rejeição de 2 (dois) ou mais entregáveis em segunda análise, em qualquer momento da vigência do Contrato, conferirá à Contratante o direito de rescindir imediatamente o Contrato por justa causa, com execução integral da garantia contratual, independentemente de notificação prévia, com direito à indenização integral pelos danos sofridos, incluindo lucros cessantes, danos emergentes e danos reputacionais.\n\n2.8. Os Acordos de Nível de Serviço (SLA) de máxima exigência aplicáveis a cada categoria de serviço são vinculantes e estão definidos no Anexo VII, incluindo: disponibilidade mínima dos sistemas ou serviços com metas de [PERCENTUAL]% ou superior, tempo máximo de resposta a incidentes críticos de até [TEMPO], tempo máximo de resolução de incidentes críticos de até [TEMPO], janelas de manutenção programada com aprovação prévia obrigatória da Contratante, métricas de desempenho operacional, indicadores-chave de qualidade (KQI) e indicadores-chave de segurança (KSI).\n\n2.9. O descumprimento dos SLAs definidos no Anexo VII ensejará, cumulativamente e de forma automática: (i) aplicação de créditos de serviço conforme tabela do Anexo VII, deduzidos das faturas subsequentes sem necessidade de notificação; (ii) abertura de registro formal de não conformidade pela Contratante com classificação de severidade; (iii) obrigação da Contratada de apresentar, no prazo de 24 (vinte e quatro) horas, análise de causa raiz e plano de ação corretiva com cronograma de implementação e responsáveis identificados; e (iv) reunião de crise com participação obrigatória da alta direção da Contratada no prazo de 48 (quarenta e oito) horas, para incidentes de severidade crítica.\n\n2.10. O descumprimento reiterado de SLAs, definido como 2 (duas) ou mais ocorrências no mesmo indicador em período de 60 (sessenta) dias, constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e conferindo à Contratante o direito de rescindir o Contrato imediatamente por justa causa, com execução integral da garantia contratual.\n\n2.11. A Contratada deverá disponibilizar à Contratante relatórios semanais de desempenho operacional e relatórios mensais de desempenho consolidado, no prazo de 3 (três) dias úteis após o encerramento de cada semana/mês, com: (i) indicadores de SLA medidos no período e comparação com as metas; (ii) análise de causa raiz de todos os descumprimentos, por menor que sejam; (iii) plano de ação corretiva com responsáveis, prazos e evidências de implementação; (iv) tendências, riscos emergentes e vulnerabilidades identificadas; (v) indicadores de qualidade e segurança dos entregáveis; e (vi) status do Plano de Continuidade de Negócios.\n\n2.12. A Contratada deverá elaborar, manter atualizado e submeter à aprovação formal da Contratante, antes do início dos Serviços, um Plano de Continuidade de Negócios (PCN) e um Plano de Recuperação de Desastres (PRD) para os Serviços prestados, conforme especificado no Anexo X, realizando testes periódicos documentados e reportando os resultados à Contratante na periodicidade definida no Anexo X. A não aprovação do PCN/PRD pela Contratante impedirá o início dos Serviços.\n\n2.13. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos, defeitos latentes, não conformidades que se manifestem posteriormente, falhas de segurança identificadas após a aprovação ou vulnerabilidades descobertas durante o período de garantia, estabelecido no Anexo I em prazo não inferior a 24 (vinte e quatro) meses, durante o qual a Contratada deverá corrigir qualquer falha identificada no prazo máximo de [PRAZO] horas para falhas críticas e [PRAZO] dias úteis para demais falhas, sem ônus adicional para a Contratante.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por períodos iguais e sucessivos mediante acordo escrito entre as Partes, formalizado com antecedência mínima de 120 (cento e vinte) dias antes do término da vigência, condicionado à avaliação formal de desempenho da Contratada pela Contratante com resultado plenamente satisfatório em todos os indicadores.\n\n3.2. A prorrogação do Contrato estará condicionada ao cumprimento integral e comprovado, pela Contratada, de todas as obrigações contratuais durante o período anterior, incluindo: (i) cumprimento dos SLAs com percentual mínimo de [PERCENTUAL]% de atingimento em todos os indicadores; (ii) ausência de qualquer penalidade aplicada nos últimos 12 (doze) meses; (iii) regularidade fiscal, trabalhista, previdenciária e de compliance; (iv) avaliação de desempenho com nota mínima de [NOTA] na escala definida no Anexo I; (v) garantia contratual vigente e válida; e (vi) aprovação formal da Contratante, que poderá recusá-la sem necessidade de justificativa.\n\n3.3. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, condicionado ao cumprimento integral de todas as condições precedentes estabelecidas no Anexo I, incluindo, sem limitação: prestação da garantia contratual, apresentação de certidões de regularidade, comprovação de qualificação técnica e certificações dos profissionais designados, assinatura de termos individuais de confidencialidade e proteção de dados por todos os profissionais da Contratada que acessarão os sistemas e informações da Contratante, aprovação dos planos de execução, de gestão de riscos, de continuidade de negócios e de recuperação de desastres, e aprovação do plano de segurança da informação.\n\n3.4. O cronograma detalhado de execução dos Serviços, com os marcos intermediários, as datas de entrega de cada entregável, os marcos de pagamento correspondentes, os pontos de controle obrigatórios e os marcos de auditoria, constará do Anexo VI e será de cumprimento obrigatório por ambas as Partes, sendo considerado documento vinculante de igual hierarquia ao presente instrumento.\n\n3.5. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com antecedência mínima de [PRAZO] dias antes da data prevista de entrega, acompanhados de: (i) justificativa técnica detalhada, documentada e assinada pelo gestor técnico sênior; (ii) análise de impacto no cronograma global, nos demais entregáveis e nos SLAs; (iii) proposta de replanejamento com novo cronograma detalhado; (iv) plano de ação para recuperação do atraso com responsáveis e prazos; e (v) análise de riscos do replanejamento proposto, para análise e aprovação formal da Contratante.\n\n3.6. A aprovação de replanejamento pela Contratante não constituirá renúncia ao direito de aplicar as penalidades cabíveis pelo atraso, não alterará os valores contratuais, não eximirá a Contratada de sua responsabilidade pelos danos decorrentes do atraso e não suspenderá a vigência da garantia contratual, salvo se expressamente e especificamente previsto no instrumento de aprovação do replanejamento.\n\n3.7. Atrasos decorrentes exclusivamente de atos ou omissões documentados e comprovados da Contratante, de caso fortuito ou de força maior, devidamente comunicados no prazo máximo de 2 (duas) horas após a ocorrência e comprovados documentalmente com evidências contemporâneas, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo formal entre as Partes, sem direito a acréscimo de valor contratual, salvo disposição expressa em contrário formalizada em aditamento contratual.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação integral dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$ [VALOR] ([VALOR POR EXTENSO]), conforme o cronograma financeiro detalhado no Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo VI, ao cumprimento integral de todas as obrigações contratuais do período e à apresentação de toda a documentação exigida.\n\n4.2. O valor contratual é fixo, global e irreajustável durante o período inicial de vigência, ressalvadas exclusivamente as hipóteses de reajuste previstas na Cláusula Sexta, de alteração de escopo formalizada por aditamento contratual e de variação extraordinária de custos decorrente de fatos absolutamente imprevisíveis, alheios à vontade das Partes e devidamente comprovados documentalmente com evidências contemporâneas, nos termos do artigo 317 do Código Civil.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui, sem exceção, todos os custos diretos e indiretos necessários à execução integral dos Serviços, incluindo: mão de obra especializada e encargos, tributos de qualquer natureza, licenças de software, ferramentas, deslocamentos, hospedagem, materiais, equipamentos, seguros obrigatórios, certificações, auditorias, testes de segurança, testes de continuidade, treinamentos, garantia contratual e quaisquer outras despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. A Contratada declara, sob as penas da lei, que o valor proposto foi estabelecido após análise completa e exaustiva do escopo, das especificações técnicas, dos SLAs, dos critérios de aceite, das condições operacionais, dos riscos envolvidos e de todas as condições contratuais, não podendo alegar, em nenhuma hipótese, desequilíbrio econômico-financeiro decorrente de má avaliação do escopo, das condições de execução ou dos riscos inerentes aos Serviços.\n\n4.5. Eventuais serviços adicionais somente serão executados após: (i) solicitação formal escrita da Contratante com descrição detalhada do escopo adicional; (ii) apresentação de proposta detalhada pela Contratada com escopo, valor, prazo, entregáveis, critérios de aceite e SLAs adicionais; (iii) análise de impacto no escopo, no cronograma e nos SLAs existentes; (iv) aprovação formal escrita da Contratante; e (v) formalização de aditamento contratual assinado por representantes autorizados de ambas as Partes. A execução de serviços adicionais sem observância rigorosa deste procedimento não gerará qualquer obrigação de pagamento para a Contratante e constituirá descumprimento contratual grave.\n\n4.6. Os créditos de serviço decorrentes de descumprimento de SLA, conforme tabela do Anexo VII, serão deduzidos automaticamente dos valores das faturas subsequentes, sem necessidade de formalização adicional, com aplicação imediata e sem possibilidade de negociação de redução. A Contratada terá o prazo de 2 (dois) dias úteis para contestar formalmente os créditos aplicados, com fundamentação técnica documentada e evidências contemporâneas, sob pena de aceitação tácita irrevogável.\n\n4.7. A Contratante reterá [PERCENTUAL]% do valor de cada parcela como garantia de execução, a ser liberado somente ao final do Contrato, após: (i) comprovação do cumprimento integral de todas as obrigações contratuais; (ii) entrega de toda a documentação técnica completa e atualizada; (iii) realização integral da transição de conhecimento e transferência de ativos; (iv) ausência de pendências, reclamações, litígios ou passivos relacionados ao Contrato; (v) aprovação formal da Contratante; e (vi) liberação da garantia contratual prestada nos termos do item 1.6.\n\n4.8. A Contratante poderá, a seu critério exclusivo e sem necessidade de autorização judicial, executar parcial ou integralmente a garantia contratual prestada nos termos do item 1.6 nas hipóteses de: (i) rescisão por justa causa; (ii) descumprimento de obrigações contratuais essenciais; (iii) aplicação de penalidades não pagas; (iv) indenizações devidas e não pagas; ou (v) qualquer outra obrigação financeira da Contratada não cumprida no prazo estabelecido.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo VI, mediante apresentação de nota fiscal ou fatura pela Contratada, acompanhada obrigatoriamente de: (i) relatório de execução do período com indicação do percentual de conclusão de cada entregável e das evidências de cumprimento dos SLAs; (ii) certidões de regularidade fiscal federal, estadual, municipal, trabalhista (FGTS e INSS) atualizadas e válidas; (iii) comprovantes de recolhimento de encargos trabalhistas e previdenciários de todos os profissionais alocados no período; (iv) declaração de ausência de passivos trabalhistas relacionados ao Contrato, assinada pelo representante legal da Contratada; (v) relatório de desempenho de SLA do período com evidências; (vi) declaração de conformidade com a LGPD e demais normas de proteção de dados; e (vii) comprovante de vigência e validade da garantia contratual.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da nota fiscal com toda a documentação exigida no item 5.1. A ausência de qualquer documento, a apresentação de documento com irregularidade ou a não conformidade de qualquer certidão suspenderá o prazo de pagamento até a regularização completa, sem que tal suspensão configure inadimplemento da Contratante ou gere qualquer encargo.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada no Anexo III, sendo expressamente vedada a emissão de duplicatas, cheques, boletos bancários ou outros títulos de crédito sem prévia autorização escrita e expressa da Contratante. A Contratada não poderá protestar, executar, ceder, endossar, transferir, penhorar ou onerar quaisquer títulos ou créditos relacionados a este Contrato sem prévia notificação à Contratante com antecedência mínima de 15 (quinze) dias úteis e sem sua autorização escrita, sob pena de rescisão imediata por justa causa.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso e atualização monetária pelo IPCA, desde que, cumulativamente: (i) o atraso não decorra de contestação fundamentada de valores pela Contratante; (ii) a Contratada tenha cumprido integralmente todas as obrigações contratuais do período, incluindo SLAs; (iii) a nota fiscal tenha sido emitida em conformidade com todas as exigências deste instrumento; e (iv) toda a documentação exigida no item 5.1 tenha sido apresentada de forma completa e regular.\n\n5.5. A Contratante poderá reter, glosar ou suspender, total ou parcialmente, o pagamento de qualquer parcela nas seguintes hipóteses, sem que tal retenção configure inadimplemento contratual ou gere qualquer encargo: (i) entregável rejeitado ou em processo de revisão; (ii) SLA não cumprido no período, pelo valor dos créditos de serviço correspondentes; (iii) obrigações acessórias não atendidas, incluindo ausência de qualquer documento exigido; (iv) existência de débitos, penalidades ou indenizações devidas pela Contratada perante a Contratante; (v) irregularidade fiscal, trabalhista, previdenciária ou de compliance da Contratada; (vi) indícios de irregularidade na execução dos Serviços, até a conclusão de apuração formal; (vii) não renovação ou redução da garantia contratual; ou (viii) qualquer descumprimento de obrigação contratual essencial.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados e dos critérios aplicados. A ausência de contestação no prazo não constituirá renúncia ao direito de contestar vícios ocultos, irregularidades identificadas posteriormente ou descumprimentos de SLA apurados após o pagamento.\n\n5.7. A Contratante poderá compensar, a seu critério exclusivo e sem necessidade de autorização judicial, eventuais créditos que possua perante a Contratada, decorrentes de penalidades, créditos de SLA, retenções, indenizações ou execução de garantia, com os valores devidos à Contratada, mediante comunicação escrita prévia com antecedência mínima de 2 (dois) dias úteis.\n\n5.8. O pagamento de qualquer parcela não constituirá aprovação tácita dos Serviços prestados no período, não implicará renúncia a direitos contratuais e não impedirá a Contratante de identificar e exigir a correção de vícios ocultos ou não conformidades identificadas posteriormente.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo IBGE, ou por outro índice oficial que venha a substituí-lo, limitado ao teto de [PERCENTUAL]% ao ano, não podendo o reajuste superar a variação real dos custos demonstrada documentalmente pela Contratada.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 90 (noventa) dias da data de sua aplicação, sendo aplicado mediante acordo formal entre as Partes, formalizado por aditamento contratual assinado por representantes autorizados de ambas as Partes, com vigência a partir da data acordada.\n\n6.3. O reajuste somente será concedido se a Contratada demonstrar, mediante documentação comprobatória completa e auditável: (i) cumprimento integral dos SLAs no período anterior, com percentual de atingimento mínimo de [PERCENTUAL]% em todos os indicadores; (ii) ausência de qualquer penalidade aplicada nos últimos 12 (doze) meses; (iii) avaliação de desempenho plenamente satisfatória pela Contratante; (iv) regularidade fiscal, trabalhista, previdenciária e de compliance; e (v) garantia contratual vigente e válida.\n\n6.4. Não haverá reajuste durante o período inicial de vigência do Contrato. Eventuais pedidos de revisão de valores por desequilíbrio econômico-financeiro somente serão analisados se a Contratada demonstrar, de forma inequívoca, contemporânea e documentada, a ocorrência de fato absolutamente imprevisível, extraordinário, alheio à sua vontade e não coberto pela análise de riscos realizada antes da celebração do Contrato, que tenha impactado substancialmente os custos dos Serviços, nos termos do artigo 317 do Código Civil.\n\n6.5. A Contratante poderá solicitar auditoria independente dos custos da Contratada como condição para análise de qualquer pedido de revisão de valores, devendo a Contratada cooperar plenamente com o processo de auditoria e fornecer todos os documentos e informações solicitados.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, de caráter vinculante, cujo descumprimento ensejará as sanções máximas previstas neste instrumento:\n\na) Executar os Serviços com excelência técnica máxima, diligência extraordinária, profissionalismo de alto nível, observância das melhores práticas internacionais do mercado, das normas técnicas e regulatórias aplicáveis, das especificações do Anexo I e dos critérios formais de aceite estabelecidos, garantindo a qualidade, a conformidade, a segurança e a resiliência dos entregáveis;\n\nb) Cumprir rigorosamente o cronograma de execução, as datas de entrega dos entregáveis e os SLAs de máxima exigência definidos no Anexo VII, comunicando proativamente à Contratante, com a antecedência estabelecida neste instrumento, qualquer risco de descumprimento identificado, por menor que seja;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação técnica exigidas para a execução dos Serviços, incluindo registros profissionais, certificações, licenças, certidões e seguros aplicáveis, apresentando comprovação à Contratante sempre que solicitado e, independentemente de solicitação, na periodicidade definida no Anexo I;\n\nd) Designar profissional sênior de máxima qualificação como gestor técnico do contrato, com poderes para tomar decisões operacionais e estratégicas, coordenar a equipe de execução e ser o ponto focal de comunicação com a Contratante, cuja substituição deverá ser comunicada com antecedência mínima de [PRAZO] dias e estará condicionada à aprovação prévia e expressa da Contratante, que poderá recusá-la sem necessidade de justificativa;\n\ne) Manter equipe técnica altamente qualificada, certificada, com experiência comprovada e em número suficiente para a execução dos Serviços dentro dos prazos e padrões de qualidade e segurança estabelecidos, comunicando à Contratante qualquer substituição de profissional-chave com antecedência mínima de [PRAZO] dias, acompanhada do currículo detalhado do substituto para aprovação prévia e expressa da Contratante;\n\nf) Comunicar à Contratante, no prazo máximo de 1 (uma) hora após a identificação, qualquer ocorrência, incidente, falha, vulnerabilidade de segurança, ameaça, evento ou situação que possa comprometer a execução regular dos Serviços, o cumprimento do cronograma, o atendimento dos SLAs, a segurança dos sistemas e dados da Contratante ou a continuidade operacional;\n\ng) Cumprir integralmente a legislação trabalhista, previdenciária, fiscal, ambiental, de segurança do trabalho, de proteção de dados, de compliance e anticorrupção aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos e por seus reflexos sobre a Contratante, incluindo custos de defesa, multas, indenizações e danos reputacionais;\n\nh) Guardar sigilo absoluto e de máximo nível sobre todas as informações confidenciais e estratégicas da Contratante a que tiver acesso em razão da execução deste Contrato, nos termos da Cláusula Nona, fazendo com que todos os seus profissionais, subcontratados e prestadores de serviços assinem termos individuais de confidencialidade e proteção de dados antes de qualquer acesso a informações, sistemas ou instalações da Contratante, mantendo registros de todos os acessos realizados;\n\ni) Reparar, nos prazos estabelecidos na Cláusula Segunda, eventuais falhas, inadequações, não conformidades, defeitos, vulnerabilidades de segurança ou lacunas nos Serviços prestados ou nos entregáveis entregues, sem ônus adicional para a Contratante, incluindo durante o período de garantia de 24 (vinte e quatro) meses;\n\nj) Apresentar à Contratante, na periodicidade estabelecida no Anexo I, relatórios semanais de progresso, relatórios mensais de desempenho de SLA, relatórios de gestão de riscos, relatórios de segurança e relatórios de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável, dos indicadores de qualidade e segurança, dos riscos identificados, das ações corretivas em andamento e do status do PCN/PRD;\n\nk) Adotar, em suas operações, práticas robustas e certificadas de governança corporativa, compliance, gestão de riscos, segurança da informação e proteção de dados, compatíveis com os padrões internacionais mais elevados e com os requisitos exigidos pela Contratante, submetendo-se a todas as auditorias previstas neste instrumento e a auditorias extraordinárias solicitadas pela Contratante;\n\nl) Participar de reuniões semanais de acompanhamento operacional, reuniões mensais de revisão de desempenho, comitês de gestão do contrato e reuniões de gestão de riscos e segurança na periodicidade e formato definidos no Anexo I, com participação obrigatória do gestor técnico sênior do contrato e, quando solicitado, da alta direção da Contratada;\n\nm) Manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] e seguro de riscos cibernéticos com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato, apresentando apólices à Contratante antes do início dos Serviços e sempre que renovadas, sendo a não renovação causa de suspensão imediata dos pagamentos;\n\nn) Elaborar, manter atualizado e submeter à aprovação formal da Contratante o Plano de Continuidade de Negócios (PCN) e o Plano de Recuperação de Desastres (PRD) para os Serviços prestados, conforme especificado no Anexo X, realizando testes periódicos documentados com participação de representantes da Contratante e reportando os resultados na periodicidade definida;\n\no) Realizar a transição de conhecimento ao final do Contrato, conforme plano detalhado definido no Anexo I, garantindo a continuidade operacional da Contratante e a transferência integral de todos os ativos, documentos, códigos, configurações, credenciais, dados e informações relacionados aos Serviços, com acompanhamento por período mínimo de [PRAZO] meses após o término do Contrato, sem ônus adicional para a Contratante;\n\np) Submeter-se a auditorias técnicas, de compliance, de segurança da informação e de proteção de dados realizadas pela Contratante ou por terceiro por ela designado, com aviso prévio de 3 (três) dias úteis para auditorias programadas e sem aviso prévio para auditorias emergenciais, devendo cooperar plenamente e fornecer todos os documentos, registros, logs e informações solicitados;\n\nq) Manter programa de integridade estruturado e certificado, com código de conduta, canal de denúncias independente, treinamentos regulares e documentados, due diligence de terceiros e controles internos robustos, apresentando evidências à Contratante na periodicidade definida no Anexo I.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato, observadas todas as condições de aprovação de entregáveis, de apresentação de documentação fiscal completa e regular e de cumprimento integral das obrigações contratuais pela Contratada;\n\nb) Fornecer à Contratada, em tempo hábil e de forma completa, todas as informações, documentos, especificações, acessos, credenciais e recursos necessários à execução dos Serviços, conforme especificado no Anexo I e na Matriz de Responsabilidades do Anexo VIII;\n\nc) Designar gestor técnico sênior do contrato com poderes para aprovar entregáveis, emitir ordens de serviço, autorizar alterações de escopo, aplicar penalidades, executar garantias e tomar decisões operacionais e estratégicas no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada, documentada e com referência expressa a cada critério de aceite não atendido, ao grau de não conformidade e às evidências identificadas em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável e não inferior a [PRAZO] dias, eventuais alterações em seus processos internos, requisitos técnicos, sistemas, políticas de segurança ou condições operacionais que possam impactar a execução dos Serviços ou o cumprimento dos SLAs;\n\nf) Disponibilizar infraestrutura, equipamentos, sistemas e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante, nos prazos estabelecidos no cronograma;\n\ng) Participar das reuniões de acompanhamento, revisão de desempenho, comitês de gestão do contrato e reuniões de gestão de riscos e segurança na periodicidade e formato definidos no Anexo I;\n\nh) Notificar a Contratada, de forma tempestiva e fundamentada, sobre qualquer descumprimento de obrigação contratual ou de SLA, antes de aplicar as penalidades previstas neste instrumento, exceto nas hipóteses em que a natureza do descumprimento torne desnecessária ou inviável a notificação prévia, incluindo os casos de descumprimento grave e imediato previstos neste instrumento.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo de máximo nível todas as informações confidenciais e estratégicas a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos, de propriedade intelectual, de clientes, de colaboradores, de fornecedores, de parceiros, de processos e de sistemas da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços, assessores jurídicos ou técnicos que: (i) necessitem conhecê-las para os fins deste Contrato, com base no princípio do menor privilégio; (ii) sejam previamente informados da natureza confidencial das informações e das consequências jurídicas de sua violação; (iii) assinem individualmente termos de confidencialidade e proteção de dados com obrigações equivalentes ou superiores às previstas neste instrumento; e (iv) sejam expressamente autorizados por escrito pela Parte titular das informações, com registro da autorização.\n\n9.3. Cada Parte deverá adotar medidas técnicas e organizacionais de máximo nível, compatíveis com os padrões de segurança da informação mais atuais e com as melhores práticas internacionais (ISO 27001, NIST, SOC 2), para proteger as Informações Confidenciais da outra Parte contra acesso não autorizado, divulgação indevida, perda, destruição, alteração ou qualquer forma de uso inadequado.\n\n9.4. A Contratada deverá: (i) implementar controles de acesso baseados no princípio do menor privilégio, com autenticação multifator obrigatória; (ii) manter registros de auditoria (logs) completos, imutáveis e auditáveis de todos os acessos a informações e sistemas da Contratante, pelo prazo mínimo de 5 (cinco) anos; (iii) criptografar as Informações Confidenciais em trânsito e em repouso com algoritmos aprovados pela Contratante; (iv) realizar auditorias de segurança periódicas e testes de intrusão conforme definido no Anexo I; (v) implementar sistema de detecção e resposta a incidentes (SIEM/SOC) para monitoramento contínuo; e (vi) manter inventário atualizado de todos os ativos que processam Informações Confidenciais da Contratante.\n\n9.5. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que sejam ou se tornem de domínio público por meios lícitos, que já fossem de conhecimento comprovado e documentado da Parte receptora antes da celebração deste instrumento, que sejam desenvolvidas de forma independente e documentada pela Parte receptora, que sejam recebidas de terceiros de forma lícita e sem restrição, ou que devam ser divulgadas por força de lei ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível, buscar proteção das informações divulgadas e minimizar o escopo da divulgação.\n\n9.6. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 10 (dez) anos após o término ou rescisão deste Contrato, sendo que as informações que constituam segredo de negócio, dados estratégicos críticos ou dados pessoais sensíveis permanecerão protegidas pelo prazo legal aplicável, sem limitação temporal.\n\n9.7. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará: (i) rescisão imediata do Contrato por justa causa, com execução integral da garantia contratual; (ii) responsabilização pelos danos diretos e indiretos causados, incluindo lucros cessantes, danos reputacionais, custos de contenção e custos de notificação de titulares de dados; (iii) adoção de medidas cautelares e inibitórias pela Contratante, independentemente de notificação prévia; e (iv) comunicação às autoridades competentes, incluindo a ANPD, quando aplicável.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (LGPD), o GDPR quando aplicável, e demais normas nacionais e internacionais aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato, adotando uma abordagem de privacy by design, privacy by default e data minimization em todas as atividades de tratamento de dados, com documentação completa de todas as atividades de tratamento.\n\n10.2. A Contratada atuará na qualidade de operadora de dados, processando dados pessoais exclusivamente para as finalidades expressamente previstas neste Contrato, de acordo com as instruções documentadas, específicas e expressas da Contratante, vedado qualquer tratamento para finalidades próprias ou de terceiros, incluindo análise, comercialização, compartilhamento, uso para treinamento de modelos de inteligência artificial ou qualquer outra finalidade não expressamente autorizada.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais de segurança de nível máximo, incluindo, sem limitação: criptografia de dados em trânsito e em repouso com algoritmos aprovados pela Contratante e de acordo com as melhores práticas internacionais, controles de acesso baseados em perfil e no princípio do menor privilégio com autenticação multifator obrigatória, registros de auditoria completos, imutáveis e auditáveis pelo prazo mínimo de 5 (cinco) anos, planos de resposta a incidentes testados semestralmente com participação de representantes da Contratante, treinamento regular e documentado de toda a equipe em proteção de dados, e avaliação de impacto à proteção de dados (DPIA) para todas as atividades de tratamento de alto risco.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 1 (uma) hora após tomar ciência do ocorrido, fornecendo relatório preliminar com as informações disponíveis, seguido de relatório completo e detalhado no prazo de 12 (doze) horas, contendo: natureza e extensão do incidente, categorias e volume de dados afetados, possível impacto sobre os titulares e sobre a Contratante, medidas adotadas e a adotar para mitigar os efeitos, identificação dos responsáveis pela resposta ao incidente, análise de causa raiz e plano de ação corretiva.\n\n10.5. Ao término deste Contrato, a Contratada deverá, no prazo de 3 (três) dias úteis e conforme instrução documentada da Contratante, devolver ou eliminar de forma segura, certificada e irreversível todos os dados pessoais tratados em razão deste instrumento, fornecendo certificado técnico de eliminação assinado por profissional qualificado e certificado, com indicação do método de eliminação utilizado, salvo obrigação legal de retenção, hipótese em que deverá informar à Contratante os dados retidos, o fundamento legal, o prazo de retenção aplicável e as medidas de segurança adotadas.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita e expressa da Contratante, devendo garantir contratualmente que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento, com nível de proteção equivalente ou superior, respondendo solidariamente por eventuais violações de qualquer suboperador.\n\n10.7. A Contratada designará encarregado de proteção de dados (DPO) dedicado e certificado para as atividades desenvolvidas no âmbito deste Contrato, cujos dados de contato deverão constar do Anexo IV, e que deverá estar disponível para comunicação com a Contratante em prazo não superior a 1 (uma) hora em casos de incidentes e em prazo não superior a 4 (quatro) horas para demais comunicações.\n\n10.8. A Contratada submeter-se-á a auditorias de proteção de dados realizadas pela Contratante ou por terceiro por ela designado, com aviso prévio de 3 (três) dias úteis para auditorias programadas e sem aviso prévio para auditorias emergenciais, devendo cooperar plenamente e fornecer todos os documentos, registros, logs e informações solicitados, incluindo acesso aos sistemas de tratamento de dados.\n\n10.9. A Contratada deverá manter, durante toda a vigência do Contrato, certificação ISO 27001 ou equivalente aprovada pela Contratante, apresentando evidências de certificação vigente antes do início dos Serviços e sempre que renovada.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos, códigos, algoritmos, metodologias, materiais, dados, modelos, processos e demais criações intelectuais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva e plena da Contratante, que poderá utilizá-los livremente, sem qualquer restrição, ônus adicional, necessidade de autorização ou pagamento de royalties à Contratada, em qualquer território e por qualquer prazo.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável, universal, exclusiva, perpétua e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo todos os direitos de exploração previstos na legislação de propriedade intelectual aplicável, em todos os territórios e por todo o prazo de proteção legal, incluindo o direito de sublicenciar, modificar, adaptar, distribuir e criar obras derivadas.\n\n11.3. A Contratada declara, sob as penas da lei, que os Serviços prestados, os entregáveis entregues e os materiais produzidos não violam direitos de propriedade intelectual, direitos autorais, patentes, marcas, segredos de negócio ou quaisquer outros direitos de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas, notificações ou ações judiciais nesse sentido, incluindo os custos razoáveis de defesa da Contratante, honorários advocatícios, eventuais condenações e danos reputacionais.\n\n11.4. A Contratada deverá, ao final do Contrato e quando solicitado durante sua vigência, entregar à Contratante todos os arquivos, documentos, códigos-fonte, scripts, configurações, dados, credenciais, chaves de criptografia e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica completa, atualizada e suficiente para a operação, manutenção e evolução independente pela Contratante ou por terceiro por ela designado, sem qualquer restrição ou dependência da Contratada.\n\n11.5. A Contratada não poderá utilizar o nome, a marca, o logotipo, os dados, os resultados, as metodologias ou qualquer outro elemento relacionado à Contratante em materiais de marketing, portfólio, publicações, apresentações, comunicações externas ou para qualquer outra finalidade sem prévia autorização escrita e expressa da Contratante.\n\n11.6. A Contratada não poderá utilizar os dados, informações, metodologias, processos ou resultados obtidos no âmbito deste Contrato para desenvolver produtos, serviços ou soluções para terceiros, ou para treinar modelos de inteligência artificial, ou para qualquer outra finalidade que não seja a execução dos Serviços objeto deste instrumento, sem prévia autorização escrita e expressa da Contratante.\n\n11.7. A Contratada deverá manter inventário atualizado de todos os ativos de propriedade intelectual desenvolvidos no âmbito deste Contrato, submetendo-o à Contratante na periodicidade definida no Anexo I.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. A Contratada é integralmente responsável pela qualidade técnica, pela conformidade, pela segurança, pela resiliência e pelo desempenho dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos, não conformidades, falhas de desempenho e vulnerabilidades de segurança identificados durante a execução do Contrato e dentro do período de garantia de 24 (vinte e quatro) meses.\n\n12.2. A Contratada será responsável pelos danos diretos e indiretos causados à Contratante em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato, incluindo lucros cessantes, danos emergentes, danos reputacionais, custos de substituição de fornecedor, custos de remediação de incidentes de segurança, custos de notificação de titulares de dados e custos de defesa em processos administrativos e judiciais.\n\n12.3. A Contratada será responsável pelos danos causados a terceiros em decorrência da execução dos Serviços, devendo manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] e seguro de riscos cibernéticos com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato.\n\n12.4. A responsabilidade total da Contratada perante a Contratante ficará limitada ao triplo do valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados, propriedade intelectual, compliance ou responsabilidade perante terceiros, hipóteses em que a responsabilidade será ilimitada e não poderá ser objeto de negociação ou limitação contratual.\n\n12.5. A Contratada indenizará e manterá a Contratante indene de quaisquer reclamações, demandas, ações judiciais, processos administrativos, custos, despesas e condenações decorrentes de: (i) descumprimento de obrigações trabalhistas, previdenciárias, fiscais ou regulatórias da Contratada; (ii) violação de direitos de propriedade intelectual de terceiros; (iii) incidentes de segurança ou violações de proteção de dados causados pela Contratada; (iv) danos causados a terceiros em razão da execução dos Serviços; e (v) descumprimento de obrigações de compliance e anticorrupção.\n\n12.6. A Contratada não poderá invocar a responsabilidade da Contratante para se eximir de suas próprias obrigações contratuais, salvo nos casos em que o descumprimento decorra exclusivamente de atos ou omissões documentados e comprovados da Contratante.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previstos no cronograma do Anexo VI sujeitará a Contratada ao pagamento de multa moratória de 2% (dois por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 30% (trinta por cento) do valor total do Contrato.\n\n13.2. O descumprimento dos SLAs definidos no Anexo VII, além dos créditos de serviço previstos no mesmo Anexo, ensejará a aplicação de multa adicional de até 15% (quinze por cento) do valor mensal do Contrato, proporcional ao grau de descumprimento e ao impacto operacional e de segurança causado à Contratante.\n\n13.3. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 30% (trinta por cento) do valor total do Contrato, sem prejuízo do direito à reparação integral dos danos comprovadamente sofridos.\n\n13.4. A violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual sujeitará a Contratada ao pagamento de multa específica de R$ [VALOR] por ocorrência, sem prejuízo da responsabilidade pelos danos causados, da rescisão imediata do Contrato por justa causa, da execução integral da garantia contratual e das medidas legais cabíveis.\n\n13.5. O descumprimento de obrigações de compliance, ética e anticorrupção sujeitará a Contratada ao pagamento de multa de 40% (quarenta por cento) do valor total do Contrato, sem prejuízo da rescisão imediata por justa causa, da execução integral da garantia contratual e das demais sanções legais aplicáveis.\n\n13.6. A não prestação ou a não renovação da garantia contratual no prazo estabelecido sujeitará a Contratada ao pagamento de multa diária de 0,5% (zero vírgula cinco por cento) do valor total do Contrato, por dia de atraso, e à suspensão imediata dos pagamentos, sem que tal suspensão configure inadimplemento da Contratante.\n\n13.7. A rejeição de entregável em segunda análise sujeitará a Contratada ao pagamento de multa de 10% (dez por cento) do valor da parcela vinculada ao entregável, por rejeição, sem prejuízo das demais penalidades cabíveis.\n\n13.8. As penalidades previstas nesta cláusula são cumulativas entre si e com a obrigação de reparação integral dos danos, podendo ser aplicadas simultaneamente quando o mesmo fato ensejar a incidência de mais de uma penalidade.\n\n13.9. Os valores das multas serão descontados dos pagamentos devidos à Contratada, cobrados judicialmente, deduzidos de garantias contratuais ou executados diretamente sobre a garantia contratual prestada, a critério exclusivo da Contratante.\n\n13.10. Não serão aplicadas penalidades nos casos em que o descumprimento decorra exclusivamente de caso fortuito, força maior ou atos atribuíveis exclusivamente à própria Contratante, devidamente comunicados no prazo de 1 (uma) hora após a ocorrência e comprovados documentalmente com evidências contemporâneas.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido nas seguintes hipóteses:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento, acerto de contas, transição de conhecimento, transferência de responsabilidades e liberação da garantia contratual;\n\nb) Pela Contratante, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 120 (cento e vinte) dias, sem prejuízo do pagamento pelos Serviços já prestados e aprovados, dos custos comprovados de desmobilização e de multa rescisória de 15% (quinze por cento) do valor remanescente do Contrato;\n\nc) Pela Contratada, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 180 (cento e oitenta) dias, sem prejuízo do pagamento de multa rescisória de 30% (trinta por cento) do valor remanescente do Contrato, da execução parcial da garantia contratual e da obrigação de garantir a continuidade integral dos Serviços durante todo o período de aviso prévio;\n\nd) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais essenciais, após notificação prévia com prazo de 5 (cinco) dias úteis para regularização, exceto nas hipóteses de descumprimento que, por sua natureza, tornem inviável ou desnecessária a concessão de prazo;\n\ne) Pela Contratante, de forma imediata e sem necessidade de notificação prévia, nos casos de: (i) falência, recuperação judicial ou extrajudicial, insolvência, dissolução ou liquidação da Contratada; (ii) violação comprovada de obrigações de confidencialidade, proteção de dados, compliance ou anticorrupção; (iii) rejeição de 2 (dois) ou mais entregáveis em segunda análise; (iv) descumprimento reiterado de SLAs conforme definido na Cláusula Segunda; (v) qualquer ato que comprometa a segurança dos sistemas, dados ou operações da Contratante; (vi) não prestação ou não renovação da garantia contratual no prazo estabelecido; ou (vii) subcontratação não autorizada.\n\n14.2. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional, multa rescisória ou reembolso de custos, devendo ainda pagar à Contratante a multa compensatória máxima prevista na Cláusula Décima Terceira, indenizar os danos causados e sujeitar-se à execução integral da garantia contratual.\n\n14.3. Em qualquer hipótese de rescisão, a Contratada deverá: (i) continuar prestando os Serviços durante o período de transição, de até 180 (cento e oitenta) dias, mediante remuneração proporcional; (ii) transferir para a Contratante ou para terceiro por ela indicado todos os materiais, documentos, códigos, dados, credenciais, chaves de criptografia e informações relacionados aos Serviços; (iii) cooperar plenamente com o processo de transição; (iv) garantir a continuidade operacional da Contratante durante todo o período de transição; e (v) manter a garantia contratual vigente durante todo o período de transição.\n\n14.4. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados, propriedade intelectual, garantia, responsabilidade por danos causados e obrigações de transição.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992, o FCPA, o UK Bribery Act, quando aplicáveis, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno, à lavagem de dinheiro, ao financiamento do terrorismo e a práticas ilícitas.\n\n15.2. A Contratada declara possuir programa de integridade estruturado e certificado, com: (i) código de conduta e ética; (ii) canal de denúncias independente, acessível e anônimo; (iii) treinamentos regulares e documentados em ética e anticorrupção para toda a equipe; (iv) due diligence de terceiros com análise de riscos de integridade; (v) controles internos robustos e auditáveis; (vi) mecanismos de monitoramento e auditoria periódica; e (vii) política de tolerância zero a qualquer forma de corrupção, suborno ou prática ilícita, comprometendo-se a mantê-lo e aprimorá-lo durante toda a vigência do Contrato e a apresentar evidências à Contratante na periodicidade definida no Anexo I.\n\n15.3. A Contratante poderá realizar auditorias de compliance na Contratada, com aviso prévio de 3 (três) dias úteis para auditorias programadas e sem aviso prévio para auditorias emergenciais, para verificar o cumprimento das obrigações previstas nesta cláusula, devendo a Contratada cooperar plenamente, fornecer os documentos e informações solicitados e permitir o acesso às suas instalações, sistemas e registros.\n\n15.4. A Contratada deverá comunicar à Contratante, no prazo de 2 (duas) horas, qualquer investigação, processo administrativo ou judicial relacionado a práticas de corrupção, suborno, lavagem de dinheiro, financiamento do terrorismo ou outras irregularidades que possam impactar a execução deste Contrato ou a reputação da Contratante.\n\n15.5. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem necessidade de notificação prévia, sem direito a qualquer indenização pela Contratada, com execução integral da garantia contratual, com obrigação de pagamento da multa máxima prevista na Cláusula Décima Terceira e com comunicação obrigatória às autoridades competentes.\n\n15.6. A Contratada deverá submeter-se a avaliação periódica de integridade e compliance realizada pela Contratante ou por terceiro por ela designado, na periodicidade definida no Anexo I, devendo cooperar plenamente com o processo de avaliação.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A subcontratação de qualquer parte dos Serviços é expressamente vedada sem prévia autorização escrita e expressa da Contratante, que poderá recusá-la sem necessidade de justificativa. A autorização, quando concedida, será específica para o subcontratado, para a atividade indicada e para o prazo determinado, não podendo ser estendida a outros subcontratados, atividades ou prazos sem nova autorização expressa.\n\n16.2. Para obter autorização de subcontratação, a Contratada deverá apresentar à Contratante, com antecedência mínima de 45 (quarenta e cinco) dias: (i) identificação completa do subcontratado; (ii) qualificação técnica, certificações e experiência comprovada; (iii) certidões de regularidade fiscal, trabalhista e previdenciária; (iv) relatório de due diligence de compliance e integridade; (v) minuta do contrato de subcontratação com cláusulas equivalentes às deste instrumento; (vi) declaração de que o subcontratado assinou termos individuais de confidencialidade e proteção de dados; (vii) comprovante de seguro de responsabilidade civil; e (viii) declaração de ausência de conflito de interesses.\n\n16.3. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos, omissões, falhas, descumprimentos e danos dos subcontratados como se fossem seus próprios, sem direito de regresso perante a Contratante.\n\n16.4. A Contratante poderá, a seu critério exclusivo e sem necessidade de justificativa, solicitar a substituição imediata de subcontratado, devendo a Contratada promover a substituição no prazo de 3 (três) dias úteis, sem interrupção dos Serviços e sem ônus adicional para a Contratante.\n\n16.5. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato é expressamente vedada sem consentimento prévio e escrito da outra Parte, que poderá recusá-la sem necessidade de justificativa, exceto nos casos de reorganização societária, hipótese em que a cessão será condicionada à assunção integral das obrigações contratuais pela cessionária, à comprovação de capacidade técnica equivalente ou superior, à manutenção da garantia contratual e à aprovação formal da Contratante.\n\n16.6. A subcontratação não autorizada constituirá descumprimento contratual grave e imediato, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira, à execução integral da garantia contratual e conferindo à Contratante o direito de rescindir imediatamente o Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações, rejeições, solicitações e demais atos com efeitos jurídicos relacionados a este Contrato deverão ser realizados por escrito, por meio de: (i) carta com aviso de recebimento; (ii) e-mail com confirmação de leitura e com cópia para o gestor do contrato e para o assessor jurídico da Parte; ou (iii) plataforma de gestão de contratos previamente acordada entre as Partes, com registro de auditoria completo e imutável.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato e aos pontos focais indicados pelas Partes no Anexo IV, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual, com efeitos a partir do recebimento da notificação de atualização, confirmada por escrito pela Parte destinatária.\n\n17.3. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação, aplicação de penalidades, retenções de pagamento, execução de garantia e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável, com indicação expressa do objeto e dos efeitos do ato, e arquivados no dossiê do contrato.\n\n17.4. Alterações no escopo, nos valores contratuais, nos prazos globais, nos SLAs, nas condições de garantia ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo absolutamente ineficazes quaisquer acordos verbais, e-mails informais ou comunicações não formalizadas sobre tais matérias.\n\n17.5. As Partes comprometem-se a realizar reuniões semanais de acompanhamento operacional e reuniões mensais de revisão de desempenho, com registro em ata assinada pelos gestores do contrato de ambas as Partes, que integrará o histórico documental do Contrato e poderá ser utilizada como evidência em eventuais disputas.\n\n17.6. A Contratada deverá manter um sistema de gestão de comunicações do contrato, com registro de todas as comunicações, aprovações, rejeições e atos com efeitos jurídicos, disponível para consulta pela Contratante a qualquer momento.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis e de igual hierarquia, os seguintes Anexos:\n\nAnexo I — Especificação Técnica Fechada e Vinculante dos Serviços: descrição fechada do escopo, entregáveis vinculantes, especificações técnicas, critérios formais de aceite, prazo de garantia de 24 meses, requisitos de segurança, responsabilidades de cada Parte e inventário de ativos de propriedade intelectual;\nAnexo II — Cronograma Financeiro: valores, condições e datas de pagamento por entregável ou marco, incluindo retenção de garantia de execução;\nAnexo III — Dados Bancários da Contratada: informações para fins de pagamento;\nAnexo IV — Gestores do Contrato, Pontos Focais e DPO: dados de contato das Partes para fins de comunicação, gestão, resposta a incidentes e proteção de dados;\nAnexo V — Plano de Segurança da Informação: requisitos de segurança, controles obrigatórios, procedimentos de gestão de incidentes e métricas de segurança;\nAnexo VI — Cronograma de Execução: marcos intermediários, datas de entrega de entregáveis, marcos de pagamento, pontos de controle obrigatórios e marcos de auditoria;\nAnexo VII — Acordo de Nível de Serviço (SLA) de Máxima Exigência: métricas de desempenho, metas, metodologia de medição, créditos de serviço e penalidades por descumprimento;\nAnexo VIII — Matriz de Responsabilidades: definição detalhada das responsabilidades de cada Parte para cada atividade, entregável e marco do Contrato;\nAnexo IX — Garantia Contratual: modalidade, valor, prazo, condições de vigência, renovação e execução da garantia;\nAnexo X — Plano de Continuidade de Negócios e Plano de Recuperação de Desastres: requisitos, estrutura, periodicidade de testes e métricas de resiliência.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas, desde que não contrariem as disposições essenciais deste instrumento.\n\n18.3. Os Anexos I, VI, VII, VIII e X somente poderão ser atualizados mediante aditamento contratual formal, assinado por representantes autorizados de ambas as Partes. Os demais Anexos poderão ser atualizados por comunicação escrita assinada pelos gestores do contrato, desde que tais atualizações não impliquem alteração de valores, prazos globais, SLAs, escopo, obrigações essenciais ou condições de garantia.\n\n18.4. A Contratada deverá manter todos os Anexos atualizados durante a vigência do Contrato, submetendo versões atualizadas à aprovação da Contratante sempre que houver alteração relevante, na periodicidade definida em cada Anexo.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações, propostas, cartas de intenção e acordos anteriores, verbais ou escritos, sobre a mesma matéria, não podendo ser alterado por acordos verbais ou comunicações informais.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente vinculante para situações futuras ou modificação tácita das condições contratuais, devendo qualquer renúncia ser expressa, específica, formalizada por escrito e assinada pelo representante autorizado da Parte renunciante.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original das Partes e o nível máximo de proteção estabelecido neste instrumento.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001, da Lei n.º 14.063/2020 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica e probatória, devendo a plataforma de assinatura digital ser aprovada previamente pela Contratante.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor, apresentados antes da assinatura.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo absolutamente ineficazes quaisquer acordos verbais ou comunicações informais sobre matérias essenciais do Contrato.\n\n19.7. Este Contrato é regido pela legislação brasileira, em especial pelo Código Civil, pela Lei Anticorrupção, pela LGPD, pela Lei de Propriedade Industrial e pelas demais normas aplicáveis à sua natureza e objeto.\n\n19.8. As Partes comprometem-se a manter o presente instrumento e seus Anexos em sigilo, não divulgando seu conteúdo a terceiros sem prévia autorização escrita da outra Parte, exceto quando necessário para o cumprimento de obrigações legais ou regulatórias.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário ou à arbitragem, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato e, se necessário, entre seus representantes legais, pelo prazo de 10 (dez) dias corridos contados da notificação formal do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes comprometem-se a submeter a controvérsia à mediação, nos termos da Lei n.º 13.140/2015, perante câmara de mediação de reconhecida reputação e com especialização em contratos empresariais, pelo prazo de 20 (vinte) dias, antes de recorrer ao Poder Judiciário ou à arbitragem.\n\n20.4. Não sendo resolvida a controvérsia por mediação, as Partes submeterão obrigatoriamente a questão à arbitragem, nos termos da Lei n.º 9.307/1996, perante câmara arbitral de reconhecida reputação e com especialização em contratos empresariais, com sede em [CIDADE], aplicando-se o regulamento da câmara escolhida, com árbitros especializados em direito empresarial e contratos de tecnologia e serviços.\n\n20.5. O procedimento arbitral será conduzido em língua portuguesa, com sede em [CIDADE], e a sentença arbitral será definitiva, vinculante e não sujeita a recurso, exceto nas hipóteses legais de nulidade.\n\n20.6. As medidas cautelares e de urgência poderão ser requeridas ao Poder Judiciário antes ou durante o procedimento arbitral, sem que tal requerimento implique renúncia à arbitragem.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas, ou eletronicamente por meio de plataforma de assinatura digital certificada previamente aprovada pela Contratante.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 1, NULL, '2026-04-15 20:17:30', '2026-04-15 20:17:30', NULL, NULL, NULL, NULL, NULL);

-- ------------------------------------------------------------
-- Tabela: contract_versions
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contract_versions`;
CREATE TABLE `contract_versions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `versionNumber` int NOT NULL DEFAULT '1',
  `content` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `changeDescription` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `totalValue` decimal(15,2) DEFAULT NULL,
  `startDate` timestamp NULL DEFAULT NULL,
  `endDate` timestamp NULL DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `contract_versions_contractId_contracts_id_fk` (`contractId`),
  KEY `contract_versions_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `contract_versions_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `contract_versions_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contract_versions` (`id`, `contractId`, `versionNumber`, `content`, `changeDescription`, `title`, `totalValue`, `startDate`, `endDate`, `createdById`, `createdAt`) VALUES
  (30003, 240005, 1, 'CONTRATO CORPORATIVO DE PRESTAÇÃO DE SERVIÇOS COM SLA\n\nModelo Contratual — Nível de Rigidez: 3/5\nTipo: Prestação de Serviços Corporativos com Acordo de Nível de Serviço\n\n---\n\nCONTRATO CORPORATIVO DE PRESTAÇÃO DE SERVIÇOS COM SLA N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato Corporativo de Prestação de Serviços com Acordo de Nível de Serviço ("Contrato"), que se regerá pelas cláusulas e condições seguintes, as quais as Partes declaram ter lido, compreendido e aceito integralmente:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], CEP [CEP], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF], nos termos de [INSTRUMENTO DE REPRESENTAÇÃO] ("Contratada").\n\nAs Partes, em conjunto, serão denominadas "Partes" e, individualmente, "Parte".\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços técnicos especializados descritos no Anexo I — Especificação Técnica dos Serviços ("Serviços"), a serem executados em conformidade com o escopo, os entregáveis, os critérios de aceite, os Acordos de Nível de Serviço (SLA) e o cronograma estabelecidos neste instrumento e em seus Anexos.\n\n1.2. Os Serviços objeto deste Contrato possuem escopo técnico detalhado, com entregáveis claramente identificados, métricas de desempenho mensuráveis e critérios formais de aceite, devendo ser executados com estrita observância das especificações técnicas, das normas aplicáveis, dos padrões de qualidade corporativa e dos SLAs definidos no Anexo VI.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional, financeira e legal necessária para a execução integral dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato e a comunicar imediatamente à Contratante qualquer alteração que possa comprometer tal capacidade.\n\n1.4. Quaisquer serviços não expressamente previstos no Anexo I não integram o escopo deste Contrato e somente poderão ser executados mediante prévia aprovação formal da Contratante e formalização de aditamento contratual escrito, com definição de escopo, valor, prazo e entregáveis adicionais.\n\n1.5. A Contratada reconhece que a execução dos Serviços poderá envolver acesso a sistemas, infraestrutura, dados e informações sensíveis da Contratante, comprometendo-se a observar todos os protocolos de segurança, confidencialidade e proteção de dados estabelecidos neste instrumento e nas políticas internas da Contratante que lhe forem comunicadas.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO, DOS ENTREGÁVEIS, DOS CRITÉRIOS DE ACEITE E DO SLA\n\n2.1. O escopo técnico dos Serviços compreende todas as atividades, tarefas, entregáveis e responsabilidades descritas no Anexo I, que integra o presente Contrato para todos os fins de direito, com indicação expressa das especificações técnicas, dos padrões de qualidade aplicáveis e dos marcos de execução.\n\n2.2. Cada entregável previsto no Anexo I deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado de documentação técnica completa, relatório de testes ou validação e declaração de conformidade com as especificações, observado o prazo de submissão estabelecido no cronograma do Anexo V.\n\n2.3. Os critérios formais de aceite de cada entregável estão definidos no Anexo I e incluem, sem limitação: conformidade técnica com as especificações, aderência aos padrões de qualidade estabelecidos, ausência de defeitos críticos ou bloqueadores, cumprimento dos SLAs aplicáveis e aprovação nos testes de aceitação definidos.\n\n2.4. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento formal de cada entregável com sua documentação completa, para aprová-lo ou rejeitá-lo mediante comunicação escrita fundamentada, com indicação detalhada das não conformidades identificadas e dos critérios de aceite não atendidos.\n\n2.5. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo de [PRAZO] dias úteis para realizar as correções e ajustes necessários, sem ônus adicional para a Contratante, submetendo nova versão acompanhada de relatório de correções com indicação das não conformidades sanadas.\n\n2.6. A rejeição de entregável em segunda análise, por não conformidades já identificadas na primeira rejeição e não devidamente corrigidas, constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades previstas na Cláusula Décima Terceira e podendo ensejar a rescisão do Contrato por justa causa.\n\n2.7. Os Acordos de Nível de Serviço (SLA) aplicáveis a cada categoria de serviço estão definidos no Anexo VI e incluem, sem limitação: disponibilidade mínima dos sistemas ou serviços, tempo máximo de resposta a incidentes, tempo máximo de resolução, janelas de manutenção programada e métricas de desempenho operacional.\n\n2.8. O descumprimento dos SLAs definidos no Anexo VI ensejará a aplicação de créditos de serviço ou penalidades conforme tabela constante do mesmo Anexo, calculados proporcionalmente ao grau e à duração do descumprimento, sem prejuízo das demais sanções contratuais aplicáveis.\n\n2.9. A Contratada deverá disponibilizar à Contratante relatórios mensais de desempenho com indicação dos SLAs medidos no período, comparação com as metas estabelecidas, análise de causa raiz de eventuais descumprimentos e plano de ação corretiva para os indicadores abaixo da meta.\n\n2.10. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos, defeitos latentes ou não conformidades que se manifestem posteriormente, dentro do prazo de garantia estabelecido no Anexo I.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por períodos iguais e sucessivos mediante acordo escrito entre as Partes, formalizado com antecedência mínima de 60 (sessenta) dias antes do término da vigência.\n\n3.2. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo V, e estará condicionado ao cumprimento das condições precedentes eventualmente estabelecidas no Anexo I.\n\n3.3. O cronograma detalhado de execução dos Serviços, com os marcos intermediários, as datas de entrega de cada entregável e os marcos de pagamento correspondentes, constará do Anexo V e será de cumprimento obrigatório por ambas as Partes.\n\n3.4. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com antecedência mínima de [PRAZO] dias antes da data prevista de entrega, acompanhados de justificativa técnica detalhada, análise de impacto e proposta de replanejamento, para análise e aprovação formal da Contratante.\n\n3.5. A aprovação de replanejamento pela Contratante não constituirá renúncia ao direito de aplicar as penalidades cabíveis pelo atraso, salvo se expressamente previsto no instrumento de aprovação do replanejamento.\n\n3.6. Atrasos decorrentes exclusivamente de atos ou omissões da Contratante, de caso fortuito ou de força maior, devidamente comunicados e comprovados documentalmente, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo formal entre as Partes.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação integral dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$ [VALOR] ([VALOR POR EXTENSO]), conforme o cronograma financeiro detalhado no Anexo II deste instrumento, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução.\n\n4.2. O valor contratual é fixo e irreajustável durante o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento, de alteração de escopo formalizada por aditamento contratual e de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução integral dos Serviços, incluindo, sem limitação, mão de obra especializada, encargos trabalhistas e previdenciários, tributos, licenças de software, deslocamentos, hospedagem, materiais, equipamentos e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após aprovação formal escrita da Contratante, com indicação de valor, prazo e entregáveis adicionais, e formalização de aditamento contratual. A execução de serviços adicionais sem autorização prévia não gerará obrigação de pagamento para a Contratante.\n\n4.5. A Contratante não será responsável pelo pagamento de quaisquer valores além dos expressamente previstos neste instrumento e em seus Anexos, salvo nos casos de aditamento contratual devidamente formalizado e assinado por representantes autorizados de ambas as Partes.\n\n4.6. Os créditos de serviço decorrentes de descumprimento de SLA, conforme tabela do Anexo VI, serão deduzidos automaticamente dos valores das faturas subsequentes, sem necessidade de formalização adicional, salvo contestação fundamentada da Contratada no prazo de 5 (cinco) dias úteis.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo V, mediante apresentação de nota fiscal ou fatura pela Contratada, acompanhada dos documentos comprobatórios exigidos.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da respectiva nota fiscal, devidamente acompanhada de: (i) relatório de execução do período; (ii) certidões de regularidade fiscal e trabalhista atualizadas; e (iii) comprovantes de recolhimento de encargos aplicáveis.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada no Anexo III deste instrumento, sendo vedada a emissão de duplicatas, cheques ou outros títulos de crédito sem prévia autorização escrita da Contratante.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso e atualização monetária pelo IPCA, desde que o atraso não decorra de contestação fundamentada de valores pela Contratante.\n\n5.5. A Contratante poderá reter o pagamento de parcela vinculada a entregável rejeitado, a SLA não cumprido ou a obrigações acessórias não atendidas, sem que tal retenção configure inadimplemento contratual, devendo comunicar à Contratada os motivos da retenção no prazo de 5 (cinco) dias úteis.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados e dos critérios aplicados, sob pena de aceitação tácita do valor faturado.\n\n5.7. A Contratada não poderá ceder, endossar ou transferir os créditos decorrentes deste Contrato a terceiros sem prévia autorização escrita da Contratante.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice oficial que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 45 (quarenta e cinco) dias da data de sua aplicação, sendo aplicado mediante acordo formal entre as Partes, formalizado por aditamento contratual ou por comunicação escrita assinada pelos gestores do contrato.\n\n6.3. Não haverá reajuste durante o período inicial de vigência do Contrato, salvo nos casos de alteração de escopo formalizada por aditamento, de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes, ou de alteração de legislação tributária que impacte diretamente os custos dos Serviços.\n\n6.4. Em caso de desequilíbrio econômico-financeiro do Contrato decorrente de fatos imprevisíveis e alheios à vontade das Partes, qualquer delas poderá solicitar a revisão dos valores contratuais, mediante apresentação de documentação comprobatória e negociação de boa-fé, nos termos do artigo 317 do Código Civil.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com excelência técnica, diligência, profissionalismo e observância das melhores práticas do mercado, das normas técnicas aplicáveis e das especificações do Anexo I, garantindo a qualidade e a conformidade dos entregáveis com os critérios de aceite estabelecidos;\n\nb) Cumprir rigorosamente o cronograma de execução, as datas de entrega dos entregáveis e os SLAs definidos no Anexo VI, comunicando proativamente à Contratante qualquer risco de descumprimento;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação técnica exigidas para a execução dos Serviços, incluindo registros profissionais, certificações, licenças e certidões aplicáveis;\n\nd) Designar profissional sênior qualificado como gestor técnico do contrato, com poderes para tomar decisões operacionais, coordenar a equipe de execução e ser o ponto focal de comunicação com a Contratante;\n\ne) Manter equipe técnica qualificada e em número suficiente para a execução dos Serviços dentro dos prazos e padrões de qualidade estabelecidos, comunicando à Contratante qualquer substituição de profissional-chave com antecedência mínima de [PRAZO] dias;\n\nf) Comunicar à Contratante, com a maior brevidade possível e em prazo não superior a 24 (vinte e quatro) horas, qualquer ocorrência, incidente ou evento que possa comprometer a execução regular dos Serviços, o cumprimento do cronograma ou o atendimento dos SLAs;\n\ng) Cumprir integralmente a legislação trabalhista, previdenciária, fiscal, ambiental, de segurança do trabalho e de proteção de dados aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos e por seus reflexos sobre a Contratante;\n\nh) Guardar sigilo absoluto sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato, nos termos da Cláusula Nona;\n\ni) Reparar, no prazo estabelecido na Cláusula Segunda, eventuais falhas, inadequações, não conformidades ou defeitos nos Serviços prestados ou nos entregáveis entregues, sem ônus adicional para a Contratante;\n\nj) Apresentar à Contratante, na periodicidade estabelecida no Anexo I, relatórios de progresso, de desempenho de SLA e de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável, dos indicadores de qualidade e das ações corretivas em andamento;\n\nk) Adotar, em suas operações, práticas de governança corporativa, compliance e gestão de riscos compatíveis com os padrões exigidos pela Contratante e com a legislação aplicável;\n\nl) Participar de reuniões de acompanhamento, revisão de desempenho e comitês de gestão do contrato na periodicidade e formato definidos no Anexo I.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato, observadas as condições de aprovação de entregáveis e de apresentação de documentação fiscal;\n\nb) Fornecer à Contratada, em tempo hábil e de forma completa, todas as informações, documentos, especificações, acessos, credenciais e recursos necessários à execução dos Serviços, conforme especificado no Anexo I;\n\nc) Designar gestor técnico do contrato com poderes para aprovar entregáveis, emitir ordens de serviço, autorizar alterações de escopo e tomar decisões operacionais no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada e referência expressa aos critérios de aceite não atendidos em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável e não inferior a [PRAZO] dias, eventuais alterações em seus processos internos, requisitos técnicos, sistemas, políticas de segurança ou condições operacionais que possam impactar a execução dos Serviços ou o cumprimento dos SLAs;\n\nf) Colaborar ativamente com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade, evitando atrasos no cronograma de execução e no cumprimento dos SLAs;\n\ng) Disponibilizar infraestrutura, equipamentos, sistemas e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante;\n\nh) Participar das reuniões de acompanhamento, revisão de desempenho e comitês de gestão do contrato na periodicidade e formato definidos no Anexo I;\n\ni) Notificar a Contratada, de forma tempestiva e fundamentada, sobre qualquer descumprimento de obrigação contratual ou de SLA, antes de aplicar as penalidades previstas neste instrumento.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos, de propriedade intelectual, de clientes e de colaboradores da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços, assessores jurídicos ou técnicos que: (i) necessitem conhecê-las para os fins deste Contrato; (ii) sejam previamente informados da natureza confidencial das informações; e (iii) estejam vinculados a obrigações de sigilo equivalentes às previstas neste instrumento, por contrato escrito ou por disposição legal.\n\n9.3. Cada Parte deverá adotar medidas técnicas e organizacionais adequadas para proteger as Informações Confidenciais da outra Parte contra acesso não autorizado, divulgação indevida, perda, destruição ou qualquer forma de uso inadequado, observando padrões de segurança equivalentes aos que adota para proteger suas próprias informações confidenciais de mesma natureza, mas nunca inferiores a um padrão razoável de diligência.\n\n9.4. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato ou de qualquer outra obrigação de confidencialidade;\nb) Já fossem de conhecimento comprovado e documentado da Parte receptora antes da celebração deste instrumento, sem restrição de divulgação;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais, o que deverá ser comprovado documentalmente;\nd) Sejam recebidas de terceiros que as divulguem de forma lícita e sem restrição de confidencialidade;\ne) Devam ser divulgadas por força de lei, regulamento, ordem judicial ou determinação de autoridade competente, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível, buscando a proteção das informações divulgadas na medida do possível.\n\n9.5. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 5 (cinco) anos após o término ou rescisão deste Contrato, independentemente do motivo que lhe deu causa, sendo que as informações que constituam segredo de negócio permanecerão protegidas pelo prazo legal aplicável.\n\n9.6. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará a responsabilização da Parte infratora pelos danos diretos e indiretos causados, incluindo lucros cessantes e danos reputacionais, nos termos da Cláusula Décima Segunda deste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD), o Regulamento Geral de Proteção de Dados da União Europeia (GDPR), quando aplicável, e demais normas nacionais e internacionais aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato, de acordo com as instruções documentadas da Contratante e em observância aos princípios da finalidade, adequação, necessidade, livre acesso, qualidade dos dados, transparência, segurança, prevenção, não discriminação e responsabilização.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais robustas e proporcionais aos riscos envolvidos para proteger os dados pessoais a que tiver acesso, incluindo, sem limitação: controles de acesso baseados em perfil, criptografia de dados em trânsito e em repouso, registros de auditoria (logs), planos de resposta a incidentes e treinamento regular de sua equipe em proteção de dados.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 24 (vinte e quatro) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre: (i) natureza do incidente; (ii) categorias e volume de dados afetados; (iii) possível impacto sobre os titulares; (iv) medidas adotadas ou a adotar para mitigar os efeitos do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução documentada da Contratante, devolver ou eliminar de forma segura e irreversível os dados pessoais tratados em razão deste instrumento, fornecendo comprovação técnica da eliminação, salvo obrigação legal de retenção, hipótese em que deverá informar à Contratante os dados retidos e o fundamento legal aplicável.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita da Contratante, devendo garantir contratualmente que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento e respondendo solidariamente por eventuais violações.\n\n10.7. A Contratada deverá designar encarregado de proteção de dados (DPO) ou ponto focal de privacidade para as atividades desenvolvidas no âmbito deste Contrato, cujos dados de contato deverão constar do Anexo IV.\n\n10.8. As Partes comprometem-se a cooperar com a Autoridade Nacional de Proteção de Dados (ANPD) e com as autoridades de proteção de dados de outras jurisdições aplicáveis, fornecendo as informações solicitadas no âmbito de suas competências.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos, códigos, algoritmos, metodologias, materiais e demais criações intelectuais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição, ônus adicional ou necessidade de autorização da Contratada.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável, universal e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação, comunicação ao público, transformação, incorporação em outras obras e quaisquer outros direitos de exploração previstos na legislação de propriedade intelectual aplicável.\n\n11.3. A Contratada declara que os Serviços prestados, os entregáveis entregues e os materiais produzidos não violam direitos de propriedade intelectual, direitos autorais, patentes, marcas ou segredos de negócio de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas, notificações ou ações judiciais nesse sentido, incluindo os custos razoáveis de defesa da Contratante.\n\n11.4. As ferramentas, metodologias, frameworks, processos, bibliotecas e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade exclusiva, sendo concedida à Contratante licença de uso não exclusiva, intransferível, irrevogável e limitada aos fins deste Contrato e à operação dos entregáveis produzidos.\n\n11.5. A Contratada deverá, ao final do Contrato e quando solicitado durante sua vigência, entregar à Contratante todos os arquivos, documentos, códigos-fonte, scripts, configurações e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica completa e atualizada.\n\n11.6. A Contratada não poderá utilizar o nome, a marca, o logotipo ou qualquer outro elemento de identidade visual da Contratante em materiais de marketing, portfólio ou comunicações externas sem prévia autorização escrita da Contratante.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos e comprovados que causar à outra em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato, devendo a Parte prejudicada demonstrar o nexo de causalidade entre o descumprimento e o dano sofrido.\n\n12.2. A Contratada será responsável pela qualidade técnica dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos, não conformidades e falhas de desempenho identificados durante a execução do Contrato e dentro do prazo de garantia estabelecido no Anexo I.\n\n12.3. A Contratada será responsável pelos danos causados a terceiros em decorrência da execução dos Serviços, incluindo danos a colaboradores, clientes e parceiros da Contratante, devendo manter seguro de responsabilidade civil com cobertura mínima de R$ [VALOR] durante toda a vigência do Contrato.\n\n12.4. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio, danos imateriais ou danos consequenciais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo, fraude, culpa grave, violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual, devidamente comprovados.\n\n12.5. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados, propriedade intelectual ou responsabilidade perante terceiros.\n\n12.6. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes exclusivamente de atos ou omissões da Contratante, de caso fortuito ou de força maior, desde que tais ocorrências sejam comunicadas imediatamente e comprovadas documentalmente.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previsto no cronograma do Anexo V sujeitará a Contratada ao pagamento de multa moratória de 0,5% (zero vírgula cinco por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 15% (quinze por cento) do valor total do Contrato.\n\n13.2. O descumprimento dos SLAs definidos no Anexo VI, além dos créditos de serviço previstos no mesmo Anexo, poderá ensejar a aplicação de multa adicional de até 5% (cinco por cento) do valor mensal do Contrato, proporcional ao grau de descumprimento e ao impacto operacional causado à Contratante.\n\n13.3. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 10% (dez por cento) do valor total do Contrato, sem prejuízo do direito à reparação integral dos danos comprovadamente sofridos.\n\n13.4. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observados os princípios da razoabilidade e da proporcionalidade, e somente após notificação prévia com prazo razoável para regularização, exceto nos casos de descumprimento que, por sua natureza ou gravidade, tornem inviável ou desnecessária a concessão de prazo.\n\n13.5. Os valores das multas poderão ser descontados dos pagamentos devidos à Contratada, cobrados judicialmente ou deduzidos de garantias contratuais eventualmente prestadas, a critério da Contratante.\n\n13.6. Não serão aplicadas penalidades nos casos em que o descumprimento decorra exclusivamente de caso fortuito, força maior, atos atribuíveis à própria Parte prejudicada ou de circunstâncias devidamente comunicadas, documentadas e aceitas formalmente pela outra Parte.\n\n13.7. A aplicação de penalidades não exclui o direito da Parte prejudicada de exigir a execução específica das obrigações inadimplidas ou de rescindir o Contrato por justa causa, conforme as hipóteses previstas na Cláusula Décima Quarta.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido nas seguintes hipóteses:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento, acerto de contas e transferência de responsabilidades;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 60 (sessenta) dias, sem prejuízo do pagamento pelos Serviços já prestados e das obrigações assumidas até a data de rescisão;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais essenciais, após notificação prévia com prazo de 15 (quinze) dias para regularização, exceto nas hipóteses de descumprimento que, por sua natureza, tornem inviável a concessão de prazo;\nd) Por qualquer das Partes, de forma imediata, nos casos de falência, recuperação judicial ou extrajudicial, insolvência, dissolução ou liquidação da outra Parte;\ne) Por qualquer das Partes, de forma imediata, em caso de violação comprovada de obrigações de confidencialidade, proteção de dados, compliance ou anticorrupção.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada:\n\na) Os valores correspondentes aos Serviços já prestados e entregáveis aprovados até a data de rescisão, calculados proporcionalmente ao cronograma financeiro do Anexo II;\nb) Os custos comprovados, razoáveis e não reembolsados incorridos pela Contratada em razão do Contrato, mediante apresentação de documentação comprobatória;\nc) Multa rescisória equivalente a 15% (quinze por cento) do valor remanescente do Contrato.\n\n14.3. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional, multa rescisória ou reembolso de custos.\n\n14.4. Em caso de rescisão com justa causa pela Contratada, esta terá direito ao recebimento de todos os valores devidos pelos Serviços prestados até a data de rescisão, acrescidos de indenização pelos danos diretos e comprovadamente sofridos em razão do descumprimento da Contratante.\n\n14.5. Em qualquer hipótese de rescisão, a Contratada deverá: (i) concluir os Serviços em andamento que possam ser finalizados no prazo de aviso prévio; (ii) transferir para a Contratante ou para terceiro por ela indicado todos os materiais, documentos, códigos e informações relacionados aos Serviços; e (iii) cooperar com a transição para o novo prestador de serviços pelo prazo de até 30 (trinta) dias após a data de rescisão, mediante remuneração proporcional.\n\n14.6. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados, propriedade intelectual e responsabilidade por danos causados.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa), o Foreign Corrupt Practices Act (FCPA) e o UK Bribery Act, quando aplicáveis, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno, à lavagem de dinheiro e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas, para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas, ou para qualquer finalidade que contrarie a legislação vigente ou os princípios éticos corporativos.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas robustas de governança corporativa, compliance e integridade, incluindo: (i) programa de integridade estruturado; (ii) canal de denúncias acessível e independente; (iii) treinamentos regulares em ética e anticorrupção; e (iv) due diligence de terceiros aplicável.\n\n15.4. A Contratada declara que não emprega menores de 18 (dezoito) anos em trabalho noturno, perigoso ou insalubre, nem menores de 16 (dezesseis) anos em qualquer trabalho, salvo na condição de aprendiz, a partir de 14 (quatorze) anos, e que não utiliza trabalho análogo ao escravo ou em condições degradantes.\n\n15.5. A Contratante poderá realizar auditorias de compliance na Contratada, com aviso prévio de 10 (dez) dias úteis, para verificar o cumprimento das obrigações previstas nesta cláusula, devendo a Contratada cooperar plenamente e fornecer os documentos e informações solicitados.\n\n15.6. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis, da responsabilização pelos danos causados e da comunicação às autoridades competentes.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada somente poderá subcontratar partes dos Serviços a terceiros especializados mediante prévia autorização escrita e expressa da Contratante, que poderá condicioná-la à: (i) apresentação de informações detalhadas sobre o subcontratado, incluindo qualificação técnica, experiência comprovada e certidões de regularidade; (ii) realização de due diligence de compliance; e (iii) assinatura de instrumento de confidencialidade e proteção de dados pelo subcontratado.\n\n16.2. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos, omissões, falhas e descumprimentos dos subcontratados como se fossem seus próprios.\n\n16.3. A Contratante poderá, a seu critério, solicitar a substituição imediata de subcontratado que demonstre incapacidade técnica, irregularidade legal, descumprimento de SLA, violação de obrigações de confidencialidade ou proteção de dados, ou que não atenda aos padrões de qualidade e compliance exigidos, devendo a Contratada promover a substituição no prazo de [PRAZO] dias.\n\n16.4. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte, que poderá recusá-la com ou sem justificativa, exceto nos casos de reorganização societária da Parte cedente, hipótese em que a cessão será permitida desde que a cessionária assuma integralmente as obrigações contratuais e possua capacidade técnica equivalente.\n\n16.5. A subcontratação não autorizada constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades máximas previstas na Cláusula Décima Terceira e podendo ensejar a rescisão imediata do Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações, rejeições, solicitações e demais atos com efeitos jurídicos relacionados a este Contrato deverão ser realizados por escrito, por meio de: (i) carta com aviso de recebimento; (ii) e-mail com confirmação de leitura; ou (iii) plataforma de gestão de projetos ou de comunicação corporativa previamente acordada entre as Partes.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato e aos pontos focais indicados pelas Partes no Anexo IV deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual, com efeitos a partir do recebimento da notificação de atualização.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio, desde que não haja notificação de falha no envio ou de endereço inválido.\n\n17.4. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação, aplicação de penalidades e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável, com indicação expressa do objeto e dos efeitos do ato.\n\n17.5. Alterações no escopo, nos valores contratuais, nos prazos globais, nos SLAs ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo ineficazes quaisquer acordos verbais sobre tais matérias.\n\n17.6. As Partes comprometem-se a realizar reuniões periódicas de acompanhamento do contrato, na periodicidade e formato definidos no Anexo I, para revisão de desempenho, análise de SLAs, discussão de riscos e alinhamento de expectativas.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis e de igual hierarquia, os seguintes Anexos:\n\nAnexo I — Especificação Técnica dos Serviços: descrição detalhada do escopo, entregáveis, especificações técnicas, critérios de aceite, prazo de garantia e responsabilidades de cada Parte;\nAnexo II — Cronograma Financeiro: valores, condições e datas de pagamento por entregável ou marco;\nAnexo III — Dados Bancários da Contratada: informações para fins de pagamento;\nAnexo IV — Gestores do Contrato e Pontos Focais: dados de contato das Partes para fins de comunicação e gestão;\nAnexo V — Cronograma de Execução: marcos intermediários, datas de entrega de entregáveis e marcos de pagamento;\nAnexo VI — Acordo de Nível de Serviço (SLA): métricas de desempenho, metas, metodologia de medição, créditos de serviço e penalidades por descumprimento.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas, desde que não contrariem as disposições essenciais deste instrumento.\n\n18.3. Os Anexos I, V e VI somente poderão ser atualizados mediante aditamento contratual formal, assinado por representantes autorizados de ambas as Partes. Os demais Anexos poderão ser atualizados por comunicação escrita assinada pelos gestores do contrato, desde que tais atualizações não impliquem alteração de valores, prazos globais, SLAs ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações, propostas, cartas de intenção e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente vinculante para situações futuras ou modificação tácita das condições contratuais, devendo qualquer renúncia ser expressa e formalizada por escrito.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível por decisão judicial ou arbitral transitada em julgado, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original das Partes.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001, da Lei n.º 14.063/2020 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica e probatória.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes, sendo ineficazes quaisquer acordos verbais ou comunicações informais sobre matérias essenciais do Contrato.\n\n19.7. Este Contrato é regido pela legislação brasileira, em especial pelo Código Civil, pelo Código de Defesa do Consumidor, quando aplicável, pela Lei Anticorrupção, pela LGPD e pelas demais normas aplicáveis à sua natureza e objeto.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato, pelo prazo de 20 (vinte) dias corridos contados da notificação formal do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes comprometem-se a submeter a controvérsia à mediação, nos termos da Lei n.º 13.140/2015, perante câmara de mediação de reconhecida reputação, pelo prazo de 30 (trinta) dias, antes de recorrer ao Poder Judiciário ou à arbitragem.\n\n20.4. Não sendo resolvida a controvérsia por mediação, as Partes poderão, de comum acordo, submeter a questão à arbitragem, nos termos da Lei n.º 9.307/1996, perante câmara arbitral de reconhecida reputação, com sede em [CIDADE], aplicando-se o regulamento da câmara escolhida.\n\n20.5. Não havendo acordo quanto à arbitragem ou sendo esta inviável, qualquer das Partes poderá submeter a controvérsia ao foro eleito nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas, ou eletronicamente por meio de plataforma de assinatura digital certificada.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 'Contrato gerado a partir do template "Contrato Corporativo de Prestação de Serviços com SLA"', 'Contrato - SILVIO ARAUJO ALQUIMIM', NULL, NULL, NULL, 1, '2026-04-27 21:44:48'),
  (60001, 270001, 1, 'CONTRATO SIMPLES DE PRESTAÇÃO DE SERVIÇOS RECORRENTES\n\nModelo Contratual — Nível de Rigidez: 1/5\nTipo: Prestação de Serviços Recorrentes\n\n---\n\nCONTRATO DE PRESTAÇÃO DE SERVIÇOS RECORRENTES N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato de Prestação de Serviços Recorrentes ("Contrato"), que se regerá pelas cláusulas e condições seguintes:\n\nCONTRATANTE: [RAZÃO SOCIAL DA CONTRATANTE], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratante").\n\nCONTRATADA: [RAZÃO SOCIAL DA CONTRATADA], pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º [CNPJ], com sede em [ENDEREÇO COMPLETO], neste ato representada por [NOME DO REPRESENTANTE], [CARGO], portador do CPF n.º [CPF] ("Contratada").\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços recorrentes descritos no Anexo I deste instrumento ("Serviços"), a serem executados de forma contínua durante toda a vigência contratual.\n\n1.2. Os Serviços objeto deste Contrato são de natureza recorrente e de baixa complexidade operacional, sendo prestados em regime de continuidade, conforme periodicidade e condições estabelecidas neste instrumento.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional e legal necessária para a execução dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO E DOS ENTREGÁVEIS\n\n2.1. O escopo dos Serviços compreende todas as atividades, tarefas e entregas descritas no Anexo I, que integra o presente Contrato para todos os fins de direito.\n\n2.2. A Contratada deverá executar os Serviços com diligência, profissionalismo e qualidade técnica adequada, observando as melhores práticas do mercado aplicáveis à natureza das atividades contratadas.\n\n2.3. Os entregáveis periódicos, quando aplicáveis, serão definidos de comum acordo entre as Partes e formalizados em cronograma específico, que poderá ser ajustado mediante comunicação escrita entre as Partes, sem necessidade de aditamento contratual, desde que não implique alteração de valor ou prazo global.\n\n2.4. A Contratante poderá solicitar ajustes razoáveis no escopo dos Serviços, desde que tais ajustes não impliquem acréscimo de custo ou complexidade relevante. Ajustes que impliquem variação de valor deverão ser formalizados por aditamento.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser renovado por iguais e sucessivos períodos mediante acordo escrito entre as Partes.\n\n3.2. A renovação do Contrato poderá ser formalizada por meio de simples notificação escrita, com antecedência mínima de [PRAZO DE ANTECEDÊNCIA] dias antes do término do período vigente, sem necessidade de celebração de novo instrumento.\n\n3.3. O início efetivo da prestação dos Serviços dar-se-á na data de [DATA DE INÍCIO] ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo I.\n\n3.4. Qualquer das Partes poderá não renovar o Contrato ao término do período vigente, mediante comunicação escrita à outra Parte com antecedência mínima de [PRAZO] dias, sem que tal decisão configure rescisão antecipada ou gere qualquer ônus.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor mensal de R$ [VALOR] ([VALOR POR EXTENSO]), perfazendo o valor total estimado para o período inicial de vigência de R$ [VALOR TOTAL] ([VALOR TOTAL POR EXTENSO]).\n\n4.2. O valor contratual é fixo para o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução dos Serviços, incluindo, sem limitação, mão de obra, encargos trabalhistas e previdenciários, tributos, deslocamentos e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após prévia aprovação escrita da Contratante e formalização de aditamento contratual ou ordem de serviço específica.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado mensalmente, até o [DIA] dia útil do mês subsequente à prestação dos Serviços, mediante apresentação de nota fiscal ou fatura pela Contratada, devidamente acompanhada dos documentos exigidos pela legislação fiscal aplicável.\n\n5.2. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada, cujos dados constam do Anexo II deste instrumento.\n\n5.3. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso.\n\n5.4. A Contratada deverá emitir as notas fiscais em conformidade com a legislação tributária vigente, indicando corretamente os serviços prestados, os tributos incidentes e os dados das Partes.\n\n5.5. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, sob pena de aceitação tácita do valor faturado.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 30 (trinta) dias da data de sua aplicação, sendo aplicado automaticamente caso a Contratante não se manifeste contrariamente no prazo de 15 (quinze) dias.\n\n6.3. As Partes poderão, de comum acordo, adotar índice diverso do previsto nesta cláusula, desde que tal acordo seja formalizado por escrito.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com qualidade, diligência e profissionalismo, observando as normas técnicas e legais aplicáveis;\n\nb) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação exigidas para a execução dos Serviços;\n\nc) Designar profissional qualificado como ponto focal para comunicação com a Contratante, responsável pelo acompanhamento e coordenação dos Serviços;\n\nd) Comunicar à Contratante, com a maior brevidade possível, qualquer ocorrência que possa comprometer a execução regular dos Serviços;\n\ne) Cumprir a legislação trabalhista, previdenciária, fiscal e ambiental aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos;\n\nf) Guardar sigilo sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato;\n\ng) Reparar, no prazo acordado entre as Partes, eventuais falhas ou inadequações nos Serviços prestados, sem ônus adicional para a Contratante.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato;\n\nb) Fornecer à Contratada, em tempo hábil, todas as informações, documentos e acessos necessários à execução dos Serviços;\n\nc) Designar interlocutor responsável pelo acompanhamento dos Serviços e pela comunicação com a Contratada;\n\nd) Comunicar à Contratada, com antecedência razoável, eventuais alterações em seus processos internos que possam impactar a execução dos Serviços;\n\ne) Colaborar com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade;\n\nf) Avaliar e aprovar os entregáveis no prazo acordado, evitando atrasos que possam impactar o cronograma de execução.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais e estratégicos da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços ou assessores que necessitem conhecê-las para os fins deste Contrato, desde que previamente informados da natureza confidencial das informações e vinculados a obrigações de sigilo equivalentes às previstas neste instrumento.\n\n9.3. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato;\nb) Já fossem de conhecimento da Parte receptora antes da celebração deste instrumento;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais;\nd) Devam ser divulgadas por força de lei, regulamento ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível.\n\n9.4. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 2 (dois) anos após o término ou rescisão deste Contrato.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD) e demais normas aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato e de acordo com as instruções da Contratante.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais adequadas para proteger os dados pessoais a que tiver acesso contra acessos não autorizados, perdas, destruição ou qualquer forma de tratamento inadequado.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 72 (setenta e duas) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre a natureza e extensão do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução da Contratante, devolver ou eliminar os dados pessoais tratados em razão deste instrumento, salvo obrigação legal de retenção.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos e materiais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição ou ônus adicional.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável e irretratável, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação e comunicação ao público.\n\n11.3. A Contratada declara que os Serviços prestados e os materiais entregues não violam direitos de propriedade intelectual de terceiros, responsabilizando-se por eventuais reclamações nesse sentido.\n\n11.4. As ferramentas, metodologias e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade, sendo concedida à Contratante licença de uso não exclusiva e não transferível para os fins deste Contrato.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos que causar à outra em decorrência do descumprimento das obrigações previstas neste Contrato, desde que devidamente comprovados.\n\n12.2. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio ou danos imateriais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo ou culpa grave.\n\n12.3. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total pago nos últimos 6 (seis) meses de vigência do Contrato, exceto nos casos de dolo, fraude ou violação de obrigações de confidencialidade e proteção de dados.\n\n12.4. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes de atos ou omissões da Contratante, caso fortuito ou força maior.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O descumprimento injustificado de obrigações contratuais relevantes por qualquer das Partes poderá ensejar a aplicação de advertência escrita, como medida prévia à rescisão contratual.\n\n13.2. Em caso de descumprimento reiterado ou de gravidade relevante, a Parte prejudicada poderá rescindir o Contrato, nos termos da Cláusula Décima Quarta, sem prejuízo do direito à reparação dos danos comprovadamente sofridos.\n\n13.3. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observado o princípio da razoabilidade, e somente após notificação prévia com prazo razoável para regularização.\n\n13.4. Não serão aplicadas penalidades nos casos em que o descumprimento decorra de caso fortuito, força maior ou atos atribuíveis à própria Parte prejudicada.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 30 (trinta) dias;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais, após notificação prévia com prazo de 15 (quinze) dias para regularização.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada os valores correspondentes aos Serviços já prestados e não pagos, sem qualquer multa rescisória adicional.\n\n14.3. Em caso de rescisão sem justa causa pela Contratada antes do término do período contratual, esta deverá concluir os Serviços em andamento ou garantir a transição adequada para outro prestador, no prazo acordado entre as Partes.\n\n14.4. A rescisão deste Contrato não afetará os direitos e obrigações das Partes já constituídos até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade e proteção de dados.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa) e demais normas aplicáveis ao combate à corrupção, ao suborno e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas ou para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas de governança corporativa e de compliance compatíveis com os princípios de integridade, transparência e ética nos negócios.\n\n15.4. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada poderá subcontratar partes dos Serviços a terceiros especializados, desde que previamente comunicado à Contratante, responsabilizando-se integralmente pela qualidade e pelo cumprimento das obrigações contratuais pelos subcontratados.\n\n16.2. A Contratante poderá, a seu critério, solicitar a substituição de subcontratado que demonstre incapacidade técnica ou que não atenda aos padrões mínimos de qualidade exigidos.\n\n16.3. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte.\n\n16.4. A subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações e solicitações relacionadas a este Contrato deverão ser realizadas por escrito, por meio de carta com aviso de recebimento, e-mail com confirmação de leitura ou outro meio que permita a comprovação do recebimento.\n\n17.2. As comunicações deverão ser endereçadas aos representantes e contatos indicados pelas Partes no Anexo III deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio.\n\n17.4. Alterações relevantes nas condições de execução dos Serviços, nos valores contratuais ou nos prazos deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis, os seguintes anexos:\n\nAnexo I — Descrição detalhada dos Serviços, escopo, periodicidade e entregáveis;\nAnexo II — Dados bancários da Contratada para fins de pagamento;\nAnexo III — Representantes e contatos das Partes para fins de comunicação;\nAnexo IV — Cronograma de execução e marcos de entrega, quando aplicável.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas.\n\n18.3. Os Anexos poderão ser atualizados de comum acordo entre as Partes, mediante comunicação escrita, sem necessidade de aditamento ao instrumento principal, desde que tais atualizações não impliquem alteração de valores, prazos ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos ou precedente para situações futuras.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada, tendo ambas as formas igual validade jurídica nos termos da legislação vigente.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus representantes, pelo prazo de 30 (trinta) dias contados da notificação do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido, qualquer das Partes poderá submeter a controvérsia ao foro eleito, nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas.\n\n[LOCAL], [DATA]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATANTE]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\n___________________________________\n[RAZÃO SOCIAL DA CONTRATADA]\n[NOME DO REPRESENTANTE]\n[CARGO]\nCPF: [CPF]\n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 'Contrato gerado a partir do template "Contrato Simples de Prestação de Serviços Recorrentes"', 'Contrato - CARLÚCIO DE BRITO BAIMA', NULL, NULL, NULL, 1, '2026-04-27 21:52:00'),
  (90003, 300003, 1, 'CONTRATO DE PRESTAÇÃO DE SERVIÇOS COM CONTROLE BÁSICO DE ENTREGAS\n\nModelo Contratual — Nível de Rigidez: 2/5\nTipo: Prestação de Serviços com Entregas Definidas\n\n---\n\nCONTRATO DE PRESTAÇÃO DE SERVIÇOS COM CONTROLE BÁSICO DE ENTREGAS N.º [NÚMERO]/[ANO]\n\nPelo presente instrumento particular, as partes abaixo qualificadas celebram o presente Contrato de Prestação de Serviços com Controle Básico de Entregas ("Contrato"), que se regerá pelas cláusulas e condições seguintes:\n\nCONTRATANTE: FABIANA RODRIGUES BELEM, pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º 34436775000126, com sede em DOUTOR SERGIO MEIRA, 79, BARRA FUNDA, SAO PAULO, SP, neste ato representada por , , portador do CPF n.º  ("Contratante").\n\nCONTRATADA: FABIANA RODRIGUES BELEM, pessoa jurídica de direito privado, inscrita no CNPJ sob o n.º 34436775000126, com sede em DOUTOR SERGIO MEIRA, 79, BARRA FUNDA, SAO PAULO, SP, neste ato representada por , , portador do CPF n.º  ("Contratada").\n\n---\n\nCLÁUSULA PRIMEIRA — DO OBJETO\n\n1.1. O presente Contrato tem por objeto a prestação, pela Contratada à Contratante, dos serviços especificados e delimitados no Anexo I deste instrumento ("Serviços"), a serem executados conforme o cronograma, os entregáveis e os critérios de aceite estabelecidos neste instrumento e em seus Anexos.\n\n1.2. Os Serviços objeto deste Contrato possuem escopo definido e entregas identificáveis, devendo ser executados com estrita observância das especificações técnicas, dos padrões de qualidade e dos prazos previstos neste instrumento.\n\n1.3. A Contratada declara possuir toda a capacidade técnica, operacional e legal necessária para a execução dos Serviços contratados, comprometendo-se a mantê-la durante toda a vigência deste Contrato e a comunicar à Contratante qualquer alteração que possa comprometer tal capacidade.\n\n1.4. Quaisquer serviços não expressamente previstos no Anexo I não integram o escopo deste Contrato e somente poderão ser executados mediante prévia formalização de aditamento contratual ou ordem de serviço específica, aprovada por escrito pela Contratante.\n\n---\n\nCLÁUSULA SEGUNDA — DO ESCOPO, DOS ENTREGÁVEIS E DOS CRITÉRIOS DE ACEITE\n\n2.1. O escopo dos Serviços compreende todas as atividades, tarefas e entregas descritas no Anexo I, que integra o presente Contrato para todos os fins de direito, com indicação expressa dos entregáveis, das especificações técnicas aplicáveis e dos marcos de execução.\n\n2.2. Cada entregável previsto no Anexo I deverá ser formalmente submetido pela Contratada à apreciação da Contratante, acompanhado de documentação técnica suficiente para sua avaliação, observado o prazo de submissão estabelecido no cronograma.\n\n2.3. A Contratante terá o prazo de [PRAZO] dias úteis, contados do recebimento de cada entregável, para aprová-lo ou rejeitá-lo, mediante comunicação escrita fundamentada. O silêncio da Contratante no referido prazo implicará aceitação tácita do entregável submetido.\n\n2.4. Em caso de rejeição fundamentada de entregável, a Contratada terá o prazo de [PRAZO] dias úteis para realizar as correções e ajustes indicados pela Contratante, sem ônus adicional para esta, submetendo nova versão para aprovação.\n\n2.5. A rejeição reiterada de um mesmo entregável, sem justificativa técnica válida, ou o descumprimento do prazo de correção previsto no item 2.4, poderá ensejar a aplicação das penalidades previstas na Cláusula Décima Terceira deste instrumento.\n\n2.6. A aprovação formal dos entregáveis pela Contratante não exime a Contratada de sua responsabilidade por vícios ocultos ou defeitos que se manifestem posteriormente, dentro do prazo de garantia estabelecido no Anexo I.\n\n---\n\nCLÁUSULA TERCEIRA — DO PRAZO E DA VIGÊNCIA\n\n3.1. O presente Contrato vigorará pelo prazo de [PRAZO], contado a partir da data de sua assinatura, podendo ser prorrogado por igual período mediante acordo escrito entre as Partes, formalizado com antecedência mínima de [PRAZO] dias antes do término da vigência.\n\n3.2. O início efetivo da prestação dos Serviços dar-se-á na data de  ou na data de assinatura deste instrumento, o que ocorrer primeiro, salvo disposição diversa constante do Anexo I.\n\n3.3. O cronograma detalhado de execução dos Serviços, com os marcos intermediários e as datas de entrega de cada entregável, constará do Anexo I e será de cumprimento obrigatório por ambas as Partes.\n\n3.4. Eventuais atrasos no cronograma de execução deverão ser comunicados pela Contratada à Contratante com a maior brevidade possível, acompanhados de justificativa técnica e de proposta de replanejamento, para análise e aprovação da Contratante.\n\n3.5. Atrasos decorrentes de atos ou omissões da Contratante, de caso fortuito ou de força maior, devidamente comprovados, não serão imputados à Contratada e ensejarão o replanejamento do cronograma mediante acordo entre as Partes.\n\n---\n\nCLÁUSULA QUARTA — DO VALOR DO CONTRATO\n\n4.1. Pela prestação dos Serviços objeto deste Contrato, a Contratante pagará à Contratada o valor total de R$  ([VALOR POR EXTENSO]), conforme o cronograma financeiro estabelecido no Anexo II deste instrumento.\n\n4.2. O valor contratual é fixo e irreajustável durante o período inicial de vigência, ressalvadas as hipóteses de reajuste previstas na Cláusula Sexta deste instrumento e de alteração de escopo formalizada por aditamento contratual.\n\n4.3. O valor estabelecido nesta cláusula é global e inclui todos os custos diretos e indiretos necessários à execução dos Serviços, incluindo, sem limitação, mão de obra, encargos trabalhistas e previdenciários, tributos, deslocamentos, materiais e demais despesas operacionais da Contratada, salvo disposição expressa em contrário no Anexo I.\n\n4.4. Eventuais serviços adicionais não previstos no escopo original somente serão executados após prévia aprovação escrita da Contratante e formalização de aditamento contratual com definição de valor, prazo e entregáveis adicionais.\n\n4.5. A Contratante não será responsável pelo pagamento de quaisquer valores além dos expressamente previstos neste instrumento e em seus Anexos, salvo nos casos de aditamento contratual devidamente formalizado.\n\n---\n\nCLÁUSULA QUINTA — DA FORMA E DAS CONDIÇÕES DE PAGAMENTO\n\n5.1. O pagamento será realizado conforme o cronograma financeiro constante do Anexo II, vinculado à aprovação formal dos respectivos entregáveis ou marcos de execução previstos no Anexo I, mediante apresentação de nota fiscal ou fatura pela Contratada.\n\n5.2. Cada parcela será paga no prazo de [PRAZO] dias úteis contados da aprovação formal do entregável ou marco correspondente e do recebimento da respectiva nota fiscal, devidamente acompanhada dos documentos exigidos pela legislação fiscal aplicável.\n\n5.3. O pagamento será efetuado por meio de transferência bancária para a conta indicada pela Contratada, cujos dados constam do Anexo III deste instrumento.\n\n5.4. Em caso de atraso no pagamento por parte da Contratante, incidirão sobre o valor devido juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, acrescidos de multa de 2% (dois por cento) sobre o valor em atraso, sem prejuízo da atualização monetária pelo IPCA.\n\n5.5. A Contratante poderá reter o pagamento de parcela vinculada a entregável rejeitado até a aprovação formal da versão corrigida, sem que tal retenção configure inadimplemento contratual.\n\n5.6. Eventuais glosas ou contestações de valores deverão ser comunicadas pela Contratante à Contratada no prazo de [PRAZO] dias úteis contados do recebimento da nota fiscal, com indicação fundamentada dos valores contestados, sob pena de aceitação tácita do valor faturado.\n\n---\n\nCLÁUSULA SEXTA — DO REAJUSTE\n\n6.1. Os valores contratados poderão ser reajustados anualmente, a contar da data de assinatura deste Contrato, com base na variação acumulada do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado pelo Instituto Brasileiro de Geografia e Estatística (IBGE), ou por outro índice oficial que venha a substituí-lo.\n\n6.2. O reajuste deverá ser solicitado pela Contratada mediante comunicação escrita à Contratante com antecedência mínima de 30 (trinta) dias da data de sua aplicação, sendo aplicado automaticamente caso a Contratante não se manifeste contrariamente no prazo de 15 (quinze) dias.\n\n6.3. Não haverá reajuste durante o período inicial de vigência do Contrato, salvo nos casos de alteração de escopo formalizada por aditamento ou de variação extraordinária de custos decorrente de fatos imprevisíveis e alheios à vontade das Partes.\n\n6.4. As Partes poderão, de comum acordo, adotar índice diverso do previsto nesta cláusula, desde que tal acordo seja formalizado por escrito e não implique desequilíbrio econômico-financeiro do Contrato.\n\n---\n\nCLÁUSULA SÉTIMA — DAS OBRIGAÇÕES DA CONTRATADA\n\n7.1. São obrigações da Contratada, sem prejuízo das demais previstas neste instrumento:\n\na) Executar os Serviços com qualidade, diligência e profissionalismo, observando as normas técnicas, as especificações do Anexo I e as melhores práticas do mercado aplicáveis à natureza das atividades contratadas;\n\nb) Cumprir rigorosamente o cronograma de execução e as datas de entrega dos entregáveis previstos no Anexo I;\n\nc) Manter, durante toda a vigência do Contrato, as condições de habilitação e qualificação exigidas para a execução dos Serviços, incluindo registros profissionais e certidões aplicáveis;\n\nd) Designar profissional qualificado como gestor do contrato, responsável pelo acompanhamento, coordenação e comunicação com a Contratante, com poderes para tomar decisões operacionais no âmbito dos Serviços;\n\ne) Comunicar à Contratante, com a maior brevidade possível, qualquer ocorrência que possa comprometer a execução regular dos Serviços ou o cumprimento do cronograma;\n\nf) Cumprir a legislação trabalhista, previdenciária, fiscal, ambiental e de segurança do trabalho aplicável às suas atividades, respondendo integralmente por eventuais descumprimentos;\n\ng) Guardar sigilo sobre todas as informações confidenciais da Contratante a que tiver acesso em razão da execução deste Contrato;\n\nh) Reparar, no prazo estabelecido na Cláusula Segunda, eventuais falhas, inadequações ou não conformidades nos Serviços prestados, sem ônus adicional para a Contratante;\n\ni) Apresentar, quando solicitado pela Contratante, relatórios de progresso e de status de execução dos Serviços, com indicação do percentual de conclusão de cada entregável.\n\n---\n\nCLÁUSULA OITAVA — DAS OBRIGAÇÕES DA CONTRATANTE\n\n8.1. São obrigações da Contratante, sem prejuízo das demais previstas neste instrumento:\n\na) Efetuar os pagamentos devidos à Contratada nos prazos e condições estabelecidos neste Contrato;\n\nb) Fornecer à Contratada, em tempo hábil, todas as informações, documentos, acessos e recursos necessários à execução dos Serviços, conforme especificado no Anexo I;\n\nc) Designar gestor do contrato com poderes para aprovar entregáveis, emitir ordens de serviço e tomar decisões operacionais no âmbito deste instrumento;\n\nd) Avaliar e aprovar ou rejeitar os entregáveis submetidos pela Contratada no prazo estabelecido na Cláusula Segunda, com fundamentação técnica adequada em caso de rejeição;\n\ne) Comunicar à Contratada, com antecedência razoável, eventuais alterações em seus processos internos, requisitos técnicos ou condições operacionais que possam impactar a execução dos Serviços;\n\nf) Colaborar com a Contratada para a resolução de eventuais dificuldades operacionais que estejam dentro de sua esfera de responsabilidade, evitando atrasos no cronograma de execução;\n\ng) Disponibilizar infraestrutura, equipamentos e recursos materiais necessários à execução dos Serviços, quando expressamente previstos no Anexo I como responsabilidade da Contratante.\n\n---\n\nCLÁUSULA NONA — DA CONFIDENCIALIDADE\n\n9.1. As Partes comprometem-se a manter em estrito sigilo todas as informações confidenciais a que tiverem acesso em razão da execução deste Contrato, incluindo, sem limitação, dados técnicos, comerciais, financeiros, operacionais, estratégicos e de propriedade intelectual da outra Parte ("Informações Confidenciais").\n\n9.2. As Informações Confidenciais somente poderão ser divulgadas a colaboradores, prestadores de serviços ou assessores que necessitem conhecê-las para os fins deste Contrato, desde que previamente informados da natureza confidencial das informações e vinculados a obrigações de sigilo equivalentes às previstas neste instrumento.\n\n9.3. A obrigação de confidencialidade prevista nesta cláusula não se aplica às informações que:\n\na) Sejam ou se tornem de domínio público por meios lícitos, sem violação deste Contrato;\nb) Já fossem de conhecimento comprovado da Parte receptora antes da celebração deste instrumento;\nc) Sejam desenvolvidas de forma independente pela Parte receptora, sem utilização das Informações Confidenciais, o que deverá ser comprovado documentalmente;\nd) Devam ser divulgadas por força de lei, regulamento ou ordem judicial, hipótese em que a Parte obrigada deverá notificar a outra com a maior brevidade possível, buscando, na medida do possível, a proteção das informações divulgadas.\n\n9.4. As obrigações de confidencialidade previstas nesta cláusula subsistirão pelo prazo de 3 (três) anos após o término ou rescisão deste Contrato, independentemente do motivo que lhe deu causa.\n\n9.5. A violação das obrigações de confidencialidade previstas nesta cláusula ensejará a responsabilização da Parte infratora pelos danos causados, nos termos da Cláusula Décima Segunda deste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA — DA PROTEÇÃO DE DADOS\n\n10.1. As Partes comprometem-se a cumprir integralmente a Lei n.º 13.709/2018 (Lei Geral de Proteção de Dados — LGPD), o Regulamento Geral de Proteção de Dados da União Europeia (GDPR), quando aplicável, e demais normas aplicáveis à proteção de dados pessoais no âmbito da execução deste Contrato.\n\n10.2. Caso a Contratada, no exercício de suas atividades, tenha acesso a dados pessoais de titulares relacionados à Contratante, atuará na qualidade de operadora de dados, processando-os exclusivamente para as finalidades previstas neste Contrato e de acordo com as instruções documentadas da Contratante.\n\n10.3. A Contratada adotará medidas técnicas e organizacionais adequadas e proporcionais aos riscos envolvidos para proteger os dados pessoais a que tiver acesso contra acessos não autorizados, perdas, destruição, alteração ou qualquer forma de tratamento inadequado.\n\n10.4. Em caso de incidente de segurança envolvendo dados pessoais, a Contratada notificará a Contratante no prazo máximo de 48 (quarenta e oito) horas após tomar ciência do ocorrido, fornecendo as informações disponíveis sobre a natureza, extensão e possível impacto do incidente.\n\n10.5. Ao término deste Contrato, a Contratada deverá, conforme instrução da Contratante, devolver ou eliminar de forma segura os dados pessoais tratados em razão deste instrumento, fornecendo comprovação documental da eliminação, salvo obrigação legal de retenção.\n\n10.6. A Contratada não poderá subcontratar o tratamento de dados pessoais sem prévia autorização escrita da Contratante, devendo garantir que os suboperadores observem as mesmas obrigações de proteção de dados previstas neste instrumento.\n\n---\n\nCLÁUSULA DÉCIMA PRIMEIRA — DA PROPRIEDADE INTELECTUAL\n\n11.1. Todos os produtos, obras, criações, desenvolvimentos, relatórios, documentos e materiais produzidos pela Contratada no âmbito da execução deste Contrato serão de propriedade exclusiva da Contratante, que poderá utilizá-los livremente, sem qualquer restrição ou ônus adicional.\n\n11.2. A Contratada cede à Contratante, de forma irrevogável, irretratável e a título gratuito, todos os direitos patrimoniais sobre as criações intelectuais desenvolvidas no âmbito deste Contrato, incluindo os direitos de reprodução, distribuição, adaptação, comunicação ao público e quaisquer outros direitos de exploração previstos na legislação aplicável.\n\n11.3. A Contratada declara que os Serviços prestados e os materiais entregues não violam direitos de propriedade intelectual de terceiros, responsabilizando-se integralmente por eventuais reclamações, demandas ou ações judiciais nesse sentido, incluindo os custos de defesa da Contratante.\n\n11.4. As ferramentas, metodologias, processos e conhecimentos preexistentes da Contratada utilizados na execução dos Serviços permanecerão de sua propriedade, sendo concedida à Contratante licença de uso não exclusiva, intransferível e limitada aos fins deste Contrato.\n\n11.5. A Contratada deverá, ao final do Contrato, entregar à Contratante todos os arquivos, documentos, códigos-fonte e demais materiais produzidos no âmbito dos Serviços, em formato editável e acompanhados de documentação técnica adequada.\n\n---\n\nCLÁUSULA DÉCIMA SEGUNDA — DA RESPONSABILIDADE\n\n12.1. Cada Parte será responsável pelos danos diretos e comprovados que causar à outra em decorrência do descumprimento culposo ou doloso das obrigações previstas neste Contrato.\n\n12.2. A Contratada será responsável pela qualidade técnica dos Serviços prestados e dos entregáveis entregues, respondendo pelos vícios, defeitos e não conformidades identificados durante o prazo de garantia estabelecido no Anexo I.\n\n12.3. Nenhuma das Partes será responsável por danos indiretos, lucros cessantes, perda de oportunidade de negócio ou danos imateriais decorrentes da execução ou inexecução deste Contrato, salvo nos casos de dolo, fraude ou culpa grave devidamente comprovados.\n\n12.4. A responsabilidade total da Contratada perante a Contratante, em qualquer hipótese, ficará limitada ao valor total do Contrato, exceto nos casos de dolo, fraude, violação de obrigações de confidencialidade, proteção de dados ou propriedade intelectual.\n\n12.5. A Contratada não será responsável por atrasos ou falhas na execução dos Serviços decorrentes de atos ou omissões da Contratante, de caso fortuito ou de força maior, desde que tais ocorrências sejam devidamente comunicadas e comprovadas.\n\n---\n\nCLÁUSULA DÉCIMA TERCEIRA — DAS PENALIDADES\n\n13.1. O atraso injustificado na entrega de entregáveis previsto no cronograma do Anexo I sujeitará a Contratada ao pagamento de multa moratória de 0,5% (zero vírgula cinco por cento) do valor da parcela vinculada ao entregável atrasado, por dia de atraso, limitada a 10% (dez por cento) do valor total do Contrato.\n\n13.2. O descumprimento injustificado de obrigações contratuais relevantes, não sanado no prazo de notificação, sujeitará a Parte infratora ao pagamento de multa compensatória de 5% (cinco por cento) do valor total do Contrato, sem prejuízo do direito à reparação dos danos comprovadamente sofridos.\n\n13.3. As penalidades previstas nesta cláusula serão aplicadas de forma proporcional à gravidade do descumprimento, observado o princípio da razoabilidade, e somente após notificação prévia com prazo razoável para regularização, exceto nos casos de descumprimento que, por sua natureza, tornem inviável a concessão de prazo.\n\n13.4. Os valores das multas poderão ser descontados dos pagamentos devidos à Contratada ou cobrados judicialmente, a critério da Contratante.\n\n13.5. Não serão aplicadas penalidades nos casos em que o descumprimento decorra de caso fortuito, força maior, atos atribuíveis à própria Parte prejudicada ou de circunstâncias devidamente comunicadas e aceitas pela outra Parte.\n\n---\n\nCLÁUSULA DÉCIMA QUARTA — DA RESCISÃO\n\n14.1. Este Contrato poderá ser rescindido:\n\na) Por mútuo acordo entre as Partes, formalizado por escrito, com definição das condições de encerramento;\nb) Por qualquer das Partes, sem justa causa, mediante aviso prévio escrito com antecedência mínima de 45 (quarenta e cinco) dias;\nc) Por qualquer das Partes, com justa causa, em caso de descumprimento grave e não remediado de obrigações contratuais, após notificação prévia com prazo de 15 (quinze) dias para regularização;\nd) Por qualquer das Partes, de forma imediata, nos casos de falência, recuperação judicial ou extrajudicial, insolvência ou dissolução da outra Parte.\n\n14.2. Em caso de rescisão sem justa causa pela Contratante antes do término do período contratual, esta deverá pagar à Contratada:\n\na) Os valores correspondentes aos Serviços já prestados e entregáveis aprovados até a data de rescisão;\nb) Os custos comprovados e não reembolsados incorridos pela Contratada em razão do Contrato;\nc) Multa rescisória equivalente a 10% (dez por cento) do valor remanescente do Contrato.\n\n14.3. Em caso de rescisão com justa causa pela Contratante, a Contratada fará jus apenas ao pagamento pelos Serviços efetivamente prestados e aceitos até a data de rescisão, sem direito a qualquer indenização adicional.\n\n14.4. Em caso de rescisão com justa causa pela Contratada, esta terá direito ao recebimento de todos os valores devidos pelos Serviços prestados até a data de rescisão, acrescidos de indenização pelos danos comprovadamente sofridos.\n\n14.5. A rescisão deste Contrato não afetará as obrigações das Partes já constituídas até a data de sua efetivação, incluindo obrigações de pagamento, confidencialidade, proteção de dados e propriedade intelectual.\n\n---\n\nCLÁUSULA DÉCIMA QUINTA — DO COMPLIANCE, ÉTICA E ANTICORRUPÇÃO\n\n15.1. As Partes declaram conhecer e comprometem-se a cumprir integralmente a Lei n.º 12.846/2013 (Lei Anticorrupção), a Lei n.º 8.429/1992 (Lei de Improbidade Administrativa), o Foreign Corrupt Practices Act (FCPA), quando aplicável, e demais normas nacionais e internacionais aplicáveis ao combate à corrupção, ao suborno e a práticas ilícitas.\n\n15.2. As Partes declaram que não utilizarão, direta ou indiretamente, os recursos oriundos deste Contrato para financiar atividades ilícitas, para realizar pagamentos a agentes públicos ou privados com o objetivo de obter vantagens indevidas, ou para qualquer finalidade que contrarie a legislação vigente.\n\n15.3. Cada Parte compromete-se a adotar, em suas operações, práticas de governança corporativa e de compliance compatíveis com os princípios de integridade, transparência, ética nos negócios e responsabilidade social.\n\n15.4. A Contratada declara que não emprega menores de 18 (dezoito) anos em trabalho noturno, perigoso ou insalubre, nem menores de 16 (dezesseis) anos em qualquer trabalho, salvo na condição de aprendiz, a partir de 14 (quatorze) anos.\n\n15.5. A violação das obrigações previstas nesta cláusula constituirá justa causa para rescisão imediata deste Contrato, sem prejuízo das demais sanções legais aplicáveis e da responsabilização pelos danos causados.\n\n---\n\nCLÁUSULA DÉCIMA SEXTA — DA SUBCONTRATAÇÃO E DA CESSÃO\n\n16.1. A Contratada somente poderá subcontratar partes dos Serviços a terceiros especializados mediante prévia autorização escrita da Contratante, que poderá condicioná-la à apresentação de informações sobre o subcontratado, incluindo qualificação técnica e certidões de regularidade fiscal e trabalhista.\n\n16.2. A autorização para subcontratação não exime a Contratada de sua responsabilidade perante a Contratante pelo cumprimento integral das obrigações contratuais, respondendo solidariamente pelos atos e omissões dos subcontratados.\n\n16.3. A Contratante poderá, a seu critério, solicitar a substituição de subcontratado que demonstre incapacidade técnica, irregularidade legal ou que não atenda aos padrões de qualidade exigidos, devendo a Contratada promover a substituição no prazo de [PRAZO] dias.\n\n16.4. A cessão total ou parcial dos direitos e obrigações decorrentes deste Contrato somente será permitida mediante consentimento prévio e escrito da outra Parte, não podendo ser recusado sem justificativa razoável.\n\n16.5. A subcontratação não autorizada constituirá descumprimento contratual grave, sujeitando a Contratada às penalidades previstas na Cláusula Décima Terceira e podendo ensejar a rescisão do Contrato por justa causa.\n\n---\n\nCLÁUSULA DÉCIMA SÉTIMA — DAS COMUNICAÇÕES ENTRE AS PARTES\n\n17.1. Todas as comunicações, notificações, aprovações e solicitações relacionadas a este Contrato deverão ser realizadas por escrito, por meio de carta com aviso de recebimento, e-mail com confirmação de leitura ou plataforma de gestão de projetos previamente acordada entre as Partes.\n\n17.2. As comunicações deverão ser endereçadas aos gestores do contrato indicados pelas Partes no Anexo IV deste instrumento, podendo ser atualizados mediante comunicação escrita, sem necessidade de aditamento contratual.\n\n17.3. As comunicações realizadas por e-mail serão consideradas recebidas no momento em que o remetente obtiver confirmação de leitura ou, na ausência desta, no primeiro dia útil seguinte ao envio, desde que não haja notificação de falha no envio.\n\n17.4. Aprovações de entregáveis, ordens de serviço, autorizações de subcontratação e demais atos que produzam efeitos jurídicos relevantes deverão ser realizados por escrito e assinados pelo gestor do contrato da Parte responsável.\n\n17.5. Alterações no escopo, nos valores contratuais, nos prazos ou em quaisquer condições essenciais deste instrumento deverão ser formalizadas por aditamento contratual escrito, assinado por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA DÉCIMA OITAVA — DOS ANEXOS\n\n18.1. Integram o presente Contrato, como partes indissociáveis, os seguintes anexos:\n\nAnexo I — Descrição detalhada dos Serviços, escopo, entregáveis, especificações técnicas, critérios de aceite e prazo de garantia;\nAnexo II — Cronograma financeiro com valores e condições de pagamento por entregável ou marco;\nAnexo III — Dados bancários da Contratada para fins de pagamento;\nAnexo IV — Gestores do contrato e contatos das Partes para fins de comunicação;\nAnexo V — Cronograma detalhado de execução com marcos intermediários e datas de entrega.\n\n18.2. Em caso de conflito entre o disposto neste instrumento e em seus Anexos, prevalecerão as disposições do instrumento principal, salvo quando os Anexos estabelecerem condições mais específicas para situações determinadas, hipótese em que prevalecerão as disposições mais específicas.\n\n18.3. Os Anexos poderão ser atualizados de comum acordo entre as Partes, mediante comunicação escrita assinada pelos gestores do contrato, sem necessidade de aditamento ao instrumento principal, desde que tais atualizações não impliquem alteração de valores, prazos globais ou obrigações essenciais.\n\n---\n\nCLÁUSULA DÉCIMA NONA — DAS DISPOSIÇÕES GERAIS\n\n19.1. Este Contrato representa o acordo integral entre as Partes com relação ao seu objeto, substituindo todos os entendimentos, negociações e acordos anteriores, verbais ou escritos, sobre a mesma matéria.\n\n19.2. A tolerância de qualquer das Partes em relação ao descumprimento de obrigações pela outra não constituirá novação, renúncia de direitos, precedente para situações futuras ou modificação tácita das condições contratuais.\n\n19.3. Se qualquer disposição deste Contrato for considerada inválida, ilegal ou inexequível por decisão judicial ou arbitral, as demais disposições permanecerão em pleno vigor e efeito, e as Partes negociarão de boa-fé uma disposição substituta que reflita, na medida do possível, a intenção original.\n\n19.4. Este Contrato poderá ser assinado em vias físicas ou eletronicamente, por meio de plataforma de assinatura digital certificada nos termos da Medida Provisória n.º 2.200-2/2001 e demais normas aplicáveis, tendo ambas as formas igual validade jurídica.\n\n19.5. As Partes declaram ter lido e compreendido integralmente o presente instrumento, concordando com todos os seus termos e condições, e que seus representantes possuem os poderes necessários para celebrá-lo, conforme documentos societários em vigor.\n\n19.6. Quaisquer alterações a este instrumento somente produzirão efeitos se formalizadas por escrito e assinadas por representantes autorizados de ambas as Partes.\n\n---\n\nCLÁUSULA VIGÉSIMA — DO FORO\n\n20.1. As Partes elegem o foro da Comarca de [CIDADE/ESTADO] para dirimir quaisquer controvérsias decorrentes deste Contrato, com renúncia expressa a qualquer outro, por mais privilegiado que seja.\n\n20.2. Antes de recorrer ao Poder Judiciário, as Partes comprometem-se a buscar solução amigável para eventuais divergências, por meio de negociação direta entre seus gestores do contrato, pelo prazo de 15 (quinze) dias contados da notificação do conflito.\n\n20.3. Não sendo possível a solução amigável no prazo estabelecido no item 20.2, as Partes poderão, de comum acordo, submeter a controvérsia à mediação ou à arbitragem, nos termos da Lei n.º 9.307/1996 e da Lei n.º 13.140/2015, antes de recorrer ao Poder Judiciário.\n\n20.4. Não havendo acordo quanto à mediação ou arbitragem, qualquer das Partes poderá submeter a controvérsia ao foro eleito nos termos do item 20.1.\n\n---\n\nE por estarem assim justas e contratadas, as Partes assinam o presente instrumento em 2 (duas) vias de igual teor e forma, na presença de 2 (duas) testemunhas.\n\n[LOCAL], [DATA]\n\n___________________________________\nFABIANA RODRIGUES BELEM\n\n\nCPF: \n\n___________________________________\nFABIANA RODRIGUES BELEM\n\n\nCPF: \n\nTESTEMUNHAS:\n\n1. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________\n\n2. ___________________________________\n   Nome: ___________________________\n   CPF: ____________________________', 'Contrato gerado a partir do template "Contrato de Prestação de Serviços com Controle Básico de Entregas"', 'Contrato - FABIANA RODRIGUES BELEM', NULL, NULL, NULL, 1, '2026-04-27 22:58:50'),
  (210001, 360001, 1, NULL, 'Versão enviada para assinatura Clicksign (tentativa 1)', 'teste', '500.00', NULL, NULL, 1, '2026-05-11 18:49:51'),
  (240001, 420001, 1, '**CONTRATO DE PRESTAÇÃO DE SERVIÇOS DE ENTREGA DE CAMINHÕES**\n\n**Pelo presente instrumento particular de contrato de prestação de serviços, de um lado:**\n\n**1. IDENTIFICAÇÃO DAS PARTES**\n\n**CONTRATADA:** rfffdsfssf, inscrita no CNPJ sob o nº 3132341343241414, com sede na [endereço completo], doravante denominada simplesmente “CONTRATADA”.\n\n**CONTRATANTE:** Grupo Arqueo Participações, inscrito no CNPJ sob o nº [CNPJ DO GRUPO ARQUEO], com sede na [endereço completo], doravante denominado simplesmente “CONTRATANTE”.\n\n**2. OBJETO DO CONTRATO**\n\nCláusula 1ª. O presente contrato tem por objeto a prestação de serviços de entrega de caminhões pela CONTRATADA ao CONTRATANTE, conforme as solicitações feitas pelo CONTRATANTE e a disponibilidade da CONTRATADA.\n\n**3. PRAZO DE VIGÊNCIA**\n\nCláusula 2ª. O prazo de vigência deste contrato será de 12 (doze) meses, contados a partir da data de sua assinatura, podendo ser prorrogado mediante acordo entre as partes.\n\n**4. VALOR E FORMA DE PAGAMENTO**\n\nCláusula 3ª. O valor total pelos serviços prestados será acordado entre as partes e descrito em cada solicitação de entrega, devendo ser pago pelo CONTRATANTE à CONTRATADA em até 10 (dez) dias após a entrega dos caminhões, mediante apresentação da respectiva nota fiscal.\n\n**5. OBRIGAÇÕES DAS PARTES**\n\nCláusula 4ª. São obrigações da CONTRATADA:\na) Realizar a entrega dos caminhões conforme acordado.\nb) Mantê-los em boas condições de uso durante o transporte.\nc) Cumprir prazos estabelecidos nas solicitações do CONTRATANTE.\n\nCláusula 5ª. São obrigações do CONTRATANTE:\na) Efetuar o pagamento na forma e nos prazos estipulados.\nb) Fornecer todas as informações necessárias para a execução da entrega.\n\n**6. CONFIDENCIALIDADE**\n\nCláusula 6ª. As partes obrigam-se a manter em sigilo todas as informações acessadas em razão deste contrato, salvo se autorizadas por escrito pela parte que as forneceu, ou se houver exigência legal para sua divulgação.\n\n**7. RESCISÃO**\n\nCláusula 7ª. O presente contrato poderá ser rescindido por qualquer das partes, mediante notificação prévia de 30 (trinta) dias, ou imediatamente em caso de descumprimento de suas cláusulas, garantido o direito à reparação por perdas e danos.\n\n**8. FORO**\n\nCláusula 8ª. Para dirimir quaisquer controvérsias oriundas deste contrato, as partes elegem o foro da comarca da sede da CONTRATANTE, renunciando a qualquer outro, por mais privilegiado que seja.\n\n**9. ASSINATURAS**\n\nE por estarem assim justas e contratadas, as partes assinam o presente contrato em duas vias de igual teor e forma, na presença de testemunhas.\n\n[Local], [Data].\n\n_______________________________   \n[Nome do Representante Legal da CONTRATADA]  \n[Cargo]  \nCONTRATADA\n\n_______________________________   \n[Nome do Representante Legal do CONTRATANTE]  \n[Cargo]  \nCONTRATANTE\n\nTestemunhas:\n\n_______________________________   \n[Nome da Testemunha 1]  \nCPF: [CPF da Testemunha 1]\n\n_______________________________   \n[Nome da Testemunha 2]  \nCPF: [CPF da Testemunha 2]', 'Versão enviada para assinatura Clicksign (tentativa 1)', '**CONTRATO DE PRESTAÇÃO DE SERVIÇOS DE ENTREGA DE CAMINHÕES**', NULL, NULL, NULL, 5550002, '2026-05-21 21:40:11');

-- ------------------------------------------------------------
-- Tabela: contracts
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `contracts`;
CREATE TABLE `contracts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `supplierId` int NOT NULL,
  `number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `object` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contractType` enum('service','supply','lease','consulting','maintenance','other') COLLATE utf8mb4_unicode_ci DEFAULT 'service',
  `status` enum('draft','review','active','suspended','expired','terminated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `creationMode` enum('manual','template','duplicate','ai') COLLATE utf8mb4_unicode_ci DEFAULT 'manual',
  `totalValue` decimal(15,2) DEFAULT NULL,
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'BRL',
  `paymentTerms` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `startDate` timestamp NULL DEFAULT NULL,
  `endDate` timestamp NULL DEFAULT NULL,
  `signedAt` timestamp NULL DEFAULT NULL,
  `contractorName` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contractorCnpj` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contractorRepresentative` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fileKey` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fileUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fileName` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `clicksignEnvelopeId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clicksignDocumentId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signatureStatus` enum('not_sent','sending','sent','partially_signed','signed','refused','cancelled','expired','send_failed') COLLATE utf8mb4_unicode_ci DEFAULT 'not_sent',
  `lastSendAttemptAt` timestamp NULL DEFAULT NULL,
  `lastSendError` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sendAttemptCount` int DEFAULT '0',
  `templateId` int DEFAULT NULL,
  `extractionRunId` int DEFAULT NULL,
  `aiConfidenceScore` decimal(5,2) DEFAULT NULL,
  `filledFieldsOrigin` json DEFAULT NULL,
  `templateName` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `companyScope` enum('single','all_group') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'single',
  `contractCompanySlug` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `organizationalGroupId` int DEFAULT NULL,
  `orgCompanyId` int DEFAULT NULL,
  `orgBusinessUnitId` int DEFAULT NULL,
  `organizationalScopeStatus` enum('classified','pending_classification') COLLATE utf8mb4_unicode_ci DEFAULT 'pending_classification',
  PRIMARY KEY (`id`) ,
  KEY `contracts_supplierId_suppliers_id_fk` (`supplierId`),
  KEY `contracts_createdById_users_id_fk` (`createdById`),
  KEY `contracts_templateId_contract_templates_id_fk` (`templateId`),
  CONSTRAINT `contracts_supplierId_suppliers_id_fk` FOREIGN KEY (`supplierId`) REFERENCES `suppliers` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `contracts_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `contracts_templateId_contract_templates_id_fk` FOREIGN KEY (`templateId`) REFERENCES `contract_templates` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `contracts` (`id`, `supplierId`, `number`, `title`, `object`, `contractType`, `status`, `creationMode`, `totalValue`, `currency`, `paymentTerms`, `startDate`, `endDate`, `signedAt`, `contractorName`, `contractorCnpj`, `contractorRepresentative`, `content`, `notes`, `fileKey`, `fileUrl`, `fileName`, `createdById`, `createdAt`, `updatedAt`, `clicksignEnvelopeId`, `clicksignDocumentId`, `signatureStatus`, `lastSendAttemptAt`, `lastSendError`, `sendAttemptCount`, `templateId`, `extractionRunId`, `aiConfidenceScore`, `filledFieldsOrigin`, `templateName`, `companyScope`, `contractCompanySlug`, `organizationalGroupId`, `orgCompanyId`, `orgBusinessUnitId`, `organizationalScopeStatus`) VALUES
