-- Tabela: extracted_fields
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `extracted_fields`;
CREATE TABLE `extracted_fields` (
  `id` int NOT NULL AUTO_INCREMENT,
  `extractionRunId` int NOT NULL,
  `fieldKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fieldLabel` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `extractedValue` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirmedValue` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confidence` decimal(5,2) DEFAULT NULL,
  `source` enum('ai','manual','ai_confirmed','ai_corrected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ai',
  `category` enum('supplier','contract','financial','legal','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'other',
  `needsReview` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `extracted_fields_extractionRunId_extraction_runs_id_fk` (`extractionRunId`),
  CONSTRAINT `extracted_fields_extractionRunId_extraction_runs_id_fk` FOREIGN KEY (`extractionRunId`) REFERENCES `extraction_runs` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

