-- ------------------------------------------------------------
-- Tabela: extraction_runs
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `extraction_runs`;
CREATE TABLE `extraction_runs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sourceFileUrl` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceFileKey` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceFileName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceFileMimeType` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purpose` enum('contract_fill','supplier_fill','both') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'both',
  `templateId` int DEFAULT NULL,
  `supplierId` int DEFAULT NULL,
  `contractId` int DEFAULT NULL,
  `status` enum('pending','processing','completed','failed','reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `overallConfidence` decimal(5,2) DEFAULT NULL,
  `rawResponse` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `errorMessage` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `processingTimeMs` int DEFAULT NULL,
  `reviewedById` int DEFAULT NULL,
  `reviewedAt` timestamp NULL DEFAULT NULL,
  `reviewNotes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `extraction_runs_templateId_contract_templates_id_fk` (`templateId`),
  KEY `extraction_runs_supplierId_suppliers_id_fk` (`supplierId`),
  KEY `extraction_runs_contractId_contracts_id_fk` (`contractId`),
  KEY `extraction_runs_reviewedById_users_id_fk` (`reviewedById`),
  KEY `extraction_runs_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `extraction_runs_templateId_contract_templates_id_fk` FOREIGN KEY (`templateId`) REFERENCES `contract_templates` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `extraction_runs_supplierId_suppliers_id_fk` FOREIGN KEY (`supplierId`) REFERENCES `suppliers` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `extraction_runs_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `extraction_runs_reviewedById_users_id_fk` FOREIGN KEY (`reviewedById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `extraction_runs_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

