DROP TABLE IF EXISTS `financial_milestones`;
CREATE TABLE `financial_milestones` (
  `id` int NOT NULL AUTO_INCREMENT,
  `contractId` int NOT NULL,
  `amendmentId` int DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plannedValue` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `paidValue` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dueDate` timestamp NOT NULL,
  `paidAt` timestamp NULL DEFAULT NULL,
  `paymentDeadlineDays` int DEFAULT '30',
  `status` enum('pending','paid','overdue','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdById` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `financial_milestones_contractId_contracts_id_fk` (`contractId`),
  KEY `financial_milestones_amendmentId_contract_amendments_id_fk` (`amendmentId`),
  KEY `financial_milestones_createdById_users_id_fk` (`createdById`),
  CONSTRAINT `financial_milestones_contractId_contracts_id_fk` FOREIGN KEY (`contractId`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `financial_milestones_amendmentId_contract_amendments_id_fk` FOREIGN KEY (`amendmentId`) REFERENCES `contract_amendments` (`id`) ON DELETE SET NULL ON UPDATE NO ACTION,
  CONSTRAINT `financial_milestones_createdById_users_id_fk` FOREIGN KEY (`createdById`) REFERENCES `users` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

